String _joinAtlasBackendInstallPath(List<String> pieces) {
  return pieces.join(Platform.pathSeparator);
}

class AtlasBackendInstallSupport {
  static bool looksLikeAtlasBackendPath(String path) {
    final normalized = path.trim().replaceAll('\\', '/').toLowerCase();
    if (normalized.isEmpty) return false;
    final parts = normalized.split('/').where((part) => part.isNotEmpty);
    if (parts.isEmpty) return false;
    final name = parts.last;

    if (name == 'atlas backend.exe' ||
        name == 'atlas-backend.exe' ||
        name == 'atlas_gui_flutter.exe') {
      return true;
    }
    if (name.endsWith('.exe') &&
        name.contains('atlas') &&
        name.contains('backend')) {
      return true;
    }
    if (name == 'atlas.exe' &&
        (normalized.contains('/atlas backend/') ||
            normalized.contains('/atlas-backend/'))) {
      return true;
    }

    return normalized.contains('/atlas backend') ||
        normalized.contains('/atlas-backend') ||
        normalized.endsWith('/atlas');
  }

  static String? selectInstallerUrl(dynamic assetsRaw) {
    if (assetsRaw is! List) return null;

    String? atlasSetupExe;
    String? setupExe;
    String? atlasExe;
    String? firstExe;
    String? atlasInstallerMsi;
    String? installerMsi;
    String? atlasMsi;
    String? firstMsi;

    for (final asset in assetsRaw) {
      if (asset is! Map<String, dynamic>) continue;
      final name = asset['name']?.toString().toLowerCase() ?? '';
      final url = asset['browser_download_url']?.toString().trim();
      if (url == null || url.isEmpty || name.isEmpty) continue;

      final isAtlasAsset = name.contains('atlas') || name.contains('backend');
      final isInstaller =
          name.contains('setup') ||
          name.contains('installer') ||
          name.contains('install');

      if (name.endsWith('.exe')) {
        if (isInstaller && isAtlasAsset) {
          atlasSetupExe ??= url;
        } else if (isInstaller) {
          setupExe ??= url;
        } else if (isAtlasAsset) {
          atlasExe ??= url;
        } else {
          firstExe ??= url;
        }
        continue;
      }

      if (name.endsWith('.msi')) {
        if (isInstaller && isAtlasAsset) {
          atlasInstallerMsi ??= url;
        } else if (isInstaller) {
          installerMsi ??= url;
        } else if (isAtlasAsset) {
          atlasMsi ??= url;
        } else {
          firstMsi ??= url;
        }
      }
    }

    return atlasSetupExe ??
        setupExe ??
        atlasExe ??
        firstExe ??
        atlasInstallerMsi ??
        installerMsi ??
        atlasMsi ??
        firstMsi;
  }

  static Iterable<String> executableCandidatesForRoot(String dirPath) sync* {
    final trimmed = dirPath.trim();
    if (trimmed.isEmpty) return;

    for (final executableName in const <String>[
      'ATLAS Backend.exe',
      'ATLAS-Backend.exe',
      'ATLAS.exe',
      'atlas_gui_flutter.exe',
    ]) {
      yield _joinAtlasBackendInstallPath([trimmed, executableName]);
    }

    for (final relativeParts in const <List<String>>[
      <String>['dist', 'ATLAS-Backend', 'ATLAS Backend.exe'],
      <String>['dist', 'ATLAS-Backend', 'ATLAS-Backend.exe'],
      <String>['dist', 'ATLAS-Backend', 'ATLAS.exe'],
      <String>['dist', 'ATLAS Backend', 'ATLAS Backend.exe'],
      <String>['dist', 'ATLAS Backend', 'ATLAS-Backend.exe'],
      <String>['dist', 'ATLAS Backend', 'ATLAS.exe'],
      <String>[
        'atlas_gui_flutter',
        'build',
        'windows',
        'x64',
        'runner',
        'Release',
        'ATLAS Backend.exe',
      ],
      <String>[
        'atlas_gui_flutter',
        'build',
        'windows',
        'x64',
        'runner',
        'Release',
        'ATLAS.exe',
      ],
      <String>[
        'build',
        'windows',
        'x64',
        'runner',
        'Release',
        'ATLAS Backend.exe',
      ],
      <String>['build', 'windows', 'x64', 'runner', 'Release', 'ATLAS.exe'],
    ]) {
      yield _joinAtlasBackendInstallPath([trimmed, ...relativeParts]);
    }
  }
}

const _fallbackAcrylicColorDark = Color(0x260A0E14);

RandomAccessFile? _singleInstanceLockHandle;
bool _firstFrameDeferred = false;

void _allowDeferredFirstFrame() {
  if (!_firstFrameDeferred) return;
  _firstFrameDeferred = false;
  WidgetsBinding.instance.allowFirstFrame();
}

Future<void> _releaseSingleInstanceLock() async {
  final handle = _singleInstanceLockHandle;
  if (handle == null) return;
  _singleInstanceLockHandle = null;
  try {
    await handle.unlock();
  } catch (_) {
    // Ignore if lock was already released.
  }
  try {
    await handle.close();
  } catch (_) {
    // Ignore close failures during shutdown.
  }
}

void _registerSingleInstanceReleaseHooks() {
  Future<void> onSignal(_) async {
    await _releaseSingleInstanceLock();
    exit(0);
  }

  final signals = <ProcessSignal>[
    ProcessSignal.sigint,
    if (!Platform.isWindows) ProcessSignal.sigterm,
  ];

  for (final signal in signals) {
    try {
      signal.watch().listen(
        (event) {
          unawaited(onSignal(event));
        },
        onError: (_) {
          // Some environments/signals may not be supported.
        },
      );
    } catch (_) {
      // Some environments/signals may not be supported.
    }
  }
}

Future<bool> _acquireSingleInstanceLock() async {
  try {
    final appData = Platform.environment['APPDATA']?.trim();
    final lockRoot = appData != null && appData.isNotEmpty
        ? Directory('$appData\\ATLAS Link')
        : Directory(
            '${Directory.systemTemp.path}${Platform.pathSeparator}ATLAS Link',
          );

    if (!lockRoot.existsSync()) {
      await lockRoot.create(recursive: true);
    }

    final lockFile = File(
      '${lockRoot.path}${Platform.pathSeparator}atlas_link.lock',
    );
    if (!lockFile.existsSync()) {
      await lockFile.create(recursive: true);
    }

    final handle = await lockFile.open(mode: FileMode.append);
    await handle.lock(FileLock.exclusive);
    _singleInstanceLockHandle = handle;
    return true;
  } catch (_) {
    return false;
  }
}

/// flutter_acrylic's acrylic blur-behind only behaves correctly on Windows 11.
/// On Windows 10 it renders a translucent "glossy" outline and makes the window
/// lag/glide while being dragged, so the blur effect is skipped there.
bool _isWindows11OrLater() {
  if (!Platform.isWindows) return false;
  final match = RegExp(
    r'Build (\d+)',
  ).firstMatch(Platform.operatingSystemVersion);
  if (match == null) return false;
  final build = int.tryParse(match.group(1) ?? '') ?? 0;
  // Windows 11 is build 22000 and later; everything below is Windows 10 or older.
  return build >= 22000;
}

Future<void> main() async {
  final binding = WidgetsFlutterBinding.ensureInitialized();
  media_kit.MediaKit.ensureInitialized();
  binding.deferFirstFrame();
  _firstFrameDeferred = true;
  final lockAcquired = await _acquireSingleInstanceLock();
  if (!lockAcquired) {
    exit(0);
  }
  _registerSingleInstanceReleaseHooks();
  if (Platform.isWindows) {
    try {
      await Window.initialize();
      await Window.setEffect(
        effect: _isWindows11OrLater()
            ? WindowEffect.acrylic
            : WindowEffect.disabled,
        color: _fallbackAcrylicColorDark,
      );
      await Window.makeTitlebarTransparent();
      await Window.enableFullSizeContentView();
    } catch (_) {
      // Ignore unsupported configurations and continue with native fallback.
    }
  }
  runApp(const AtlasLauncherApp());
}

class AtlasLauncherApp extends StatelessWidget {
  const AtlasLauncherApp({super.key});

  @override
  Widget build(BuildContext context) {
    const seed = Color(0xFF2A9DF4);
    const accentBlue = Color(0xFF1E88E5);

    final darkTheme = ThemeData(
      brightness: Brightness.dark,
      useMaterial3: true,
      fontFamily: 'Segoe UI',
      scaffoldBackgroundColor: const Color(0xFF0A0E14),
      colorScheme: const ColorScheme.dark(
        primary: seed,
        secondary: accentBlue,
        surface: Color(0xFF101722),
        onSurface: Color(0xFFE9F1FF),
      ),
      sliderTheme: SliderThemeData(
        activeTrackColor: accentBlue,
        inactiveTrackColor: accentBlue.withValues(alpha: 0.25),
        thumbColor: accentBlue,
        overlayColor: accentBlue.withValues(alpha: 0.25),
        valueIndicatorColor: accentBlue,
        valueIndicatorTextStyle: const TextStyle(color: Colors.white),
      ),
      elevatedButtonTheme: ElevatedButtonThemeData(
        style: ElevatedButton.styleFrom(
          backgroundColor: accentBlue,
          foregroundColor: Colors.white,
        ),
      ),
      switchTheme: SwitchThemeData(
        thumbColor: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) return accentBlue;
          return Colors.white54;
        }),
        trackColor: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) {
            return accentBlue.withValues(alpha: 0.55);
          }
          return Colors.white24;
        }),
      ),
      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(foregroundColor: accentBlue),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(foregroundColor: accentBlue),
      ),
      textTheme: const TextTheme(
        headlineLarge: TextStyle(
          fontSize: 36,
          fontWeight: FontWeight.w700,
          letterSpacing: 0.4,
        ),
        headlineMedium: TextStyle(fontSize: 24, fontWeight: FontWeight.w600),
        titleLarge: TextStyle(fontSize: 18, fontWeight: FontWeight.w600),
        bodyLarge: TextStyle(fontSize: 16, height: 1.4),
        bodyMedium: TextStyle(fontSize: 14, height: 1.4),
      ),
      snackBarTheme: const SnackBarThemeData(
        behavior: SnackBarBehavior.floating,
      ),
    );

    return MaterialApp(
      title: 'ATLAS Link',
      debugShowCheckedModeBanner: false,
      scrollBehavior: const _AtlasScrollBehavior(),
      theme: darkTheme,
      darkTheme: darkTheme,
      themeMode: ThemeMode.dark,
      home: const LauncherScreen(),
    );
  }
}

class _AtlasScrollBehavior extends MaterialScrollBehavior {
  const _AtlasScrollBehavior();

  @override
  ScrollPhysics getScrollPhysics(BuildContext context) {
    return const _SmoothScrollPhysics(
      parent: BouncingScrollPhysics(parent: AlwaysScrollableScrollPhysics()),
    );
  }

  @override
  Set<PointerDeviceKind> get dragDevices => {
    PointerDeviceKind.touch,
    PointerDeviceKind.trackpad,
    PointerDeviceKind.stylus,
  };
}

class _SmoothScrollPhysics extends ScrollPhysics {
  const _SmoothScrollPhysics({super.parent, this.multiplier = 0.35});

  final double multiplier;

  @override
  _SmoothScrollPhysics applyTo(ScrollPhysics? ancestor) {
    return _SmoothScrollPhysics(
      parent: buildParent(ancestor),
      multiplier: multiplier,
    );
  }

  @override
  double applyPhysicsToUserOffset(ScrollMetrics position, double offset) {
    return super.applyPhysicsToUserOffset(position, offset * multiplier);
  }
}

