class BackendProxyRouting {
  static const String defaultBackendHost = '127.0.0.1';
  static const int defaultBackendPort = 3551;

  static bool proxyRequired({
    required BackendConnectionType connectionType,
    required String host,
    required int port,
  }) {
    if (connectionType == BackendConnectionType.remote) {
      return !isDefaultBackendEndpoint(host, port);
    }
    return port != defaultBackendPort;
  }

  static bool isDefaultBackendEndpoint(String host, int port) {
    return port == defaultBackendPort && isLocalHost(host);
  }

  static bool isLocalHost(String host) {
    final normalized = host
        .trim()
        .toLowerCase()
        .replaceFirst(RegExp(r'^http://', caseSensitive: false), '')
        .replaceFirst(RegExp(r'^https://', caseSensitive: false), '')
        .split('/')
        .first;
    final bare = normalized.startsWith('[')
        ? normalized.split(']').first.replaceFirst('[', '')
        : normalized.split(':').first;
    return bare == 'localhost' ||
        bare == '0.0.0.0' ||
        bare == '::1' ||
        bare == '127.0.0.1' ||
        bare.startsWith('127.');
  }
}

extension _BackendConnectionTypeLabel on BackendConnectionType {
  String get label {
    switch (this) {
      case BackendConnectionType.local:
        return 'Local';
      case BackendConnectionType.embedded:
        return 'Embedded';
      case BackendConnectionType.remote:
        return 'Remote';
    }
  }
}

extension _EmbeddedBackendTypeDetails on EmbeddedBackendType {
  String get label {
    switch (this) {
      case EmbeddedBackendType.lawinServer:
        return 'LawinServer';
      case EmbeddedBackendType.neoniteV2:
        return 'NeoniteV2';
    }
  }

  int get defaultPort {
    switch (this) {
      case EmbeddedBackendType.lawinServer:
        return BackendProxyRouting.defaultBackendPort;
      case EmbeddedBackendType.neoniteV2:
        return 5595;
    }
  }

  String get bundledAssetDirectory {
    switch (this) {
      case EmbeddedBackendType.lawinServer:
        return 'assets/backend/lawinserver';
      case EmbeddedBackendType.neoniteV2:
        return 'assets/backend/neonite_v2';
    }
  }

  String get startCommand {
    switch (this) {
      case EmbeddedBackendType.lawinServer:
        return 'index.js';
      case EmbeddedBackendType.neoniteV2:
        return 'app.js';
    }
  }

  String get executableAssetPath {
    switch (this) {
      case EmbeddedBackendType.lawinServer:
        return 'assets/backend/bin/atlas_lawinserver.exe';
      case EmbeddedBackendType.neoniteV2:
        return 'assets/backend/bin/atlas_neonitev2.exe';
    }
  }

  String get requiredNodePackage {
    switch (this) {
      case EmbeddedBackendType.lawinServer:
        return 'express';
      case EmbeddedBackendType.neoniteV2:
        return 'sails';
    }
  }

  /// File name of this backend's downloadable payload zip (its folder + the
  /// shared Node runtime + its wrapper exe). Used as the temp download name.
  String get downloadAssetName {
    switch (this) {
      case EmbeddedBackendType.lawinServer:
        return 'lawinserver-backend.zip';
      case EmbeddedBackendType.neoniteV2:
        return 'neonitev2-backend.zip';
    }
  }

  /// Direct URL the payload is fetched from. The zips are committed to the repo
  /// under backends/ and served via GitHub's raw endpoint, so this is a fixed
  /// URL (no GitHub release/API lookup needed).
  String get downloadUrl {
    const base =
        'https://raw.githubusercontent.com/cipherfps/ATLAS-Link/main/backends';
    return '$base/$downloadAssetName';
  }
}

class _FortniteProcessState {
  _FortniteProcessState({
    required this.pid,
    required this.host,
    required this.versionId,
    required this.gameVersion,
    required this.clientName,
    this.headless = false,
    this.launcherPid,
    this.eacPid,
    this.child,
  });

  final int pid;
  final bool host;
  final String versionId;
  final String gameVersion;
  final String clientName;
  final bool headless;
  final int? launcherPid;
  final int? eacPid;
  final _FortniteProcessState? child;

  bool launched = false;
  bool tokenError = false;
  bool corrupted = false;
  bool killed = false;
  bool exited = false;
  bool postLoginInjected = false;
  bool largePakInjected = false;
  bool largePakScheduleRequested = false;
  bool unrealEngineInjected = false;
  bool unrealEngineInjectionScheduled = false;
  bool gameServerInjected = false;
  bool hostPostLoginPatchersInjected = false;
  bool sawContinueLoggingIn = false;
  bool sawAnyCompletedLoginLine = false;
  bool sawEnglishCompletedLoginLine = false;
  bool sawLoginUiStateTransition = false;
  bool sawUpdateSuccess = false;
  bool sawUpdateSuccessNoChange = false;
  bool sawUpdateResult1 = false;
  bool sawUpdateResult2 = false;
  bool sawLoginToSubgameSelect = false;
  bool sawSubgameSelectToFrontEnd = false;
  bool sawClientLoadingMarker = false;
  bool sawPotentialLocalizedLoginCompletion = false;
  bool sawPotentialGarbledLoginCompletion = false;
  bool loggedPotentialLoginMarkerMismatch = false;

  void killAuxiliary() {
    final launcher = launcherPid;
    final eac = eacPid;
    if (launcher != null) _killPidSafe(launcher);
    if (eac != null) _killPidSafe(eac);
  }

  void kill({bool includeChild = true}) {
    if (killed) return;
    killed = true;
    launched = true;
    exited = true;
    if (includeChild) {
      child?.killAll();
    }
    _killPidSafe(pid);
    killAuxiliary();
  }

  void killAll() {
    kill(includeChild: true);
  }

  static void _killPidSafe(int pid) {
    try {
      Process.killPid(pid, ProcessSignal.sigabrt);
    } catch (_) {
      // Ignore failures (process might already be dead / access denied).
    }
  }
}

