  void _startHomeHeroAutoRotate() {
    _homeHeroTimer?.cancel();
    if (_tab != LauncherTab.home) return;
    final page = _activeLauncherContentPage;
    final count = page.slides.length;
    if (count <= 1 || page.heroRotationSeconds <= 0) return;
    _homeHeroTimer = Timer.periodic(
      Duration(seconds: page.heroRotationSeconds),
      (_) {
        if (!mounted || _tab != LauncherTab.home) return;
        final activePage = _activeLauncherContentPage;
        final activeCount = activePage.slides.length;
        if (activeCount <= 1) return;
        setState(() {
          _homeHeroIndex = (_homeHeroIndex + 1) % activeCount;
        });
      },
    );
  }

  void _setHomeHeroIndex(int index) {
    final count = _activeLauncherContentPage.slides.length;
    if (count == 0) return;
    if (!mounted) {
      _homeHeroIndex = index % count;
      return;
    }
    setState(() => _homeHeroIndex = index % count);
    _startHomeHeroAutoRotate();
  }

  Future<void> _initStorage() async {
    final appData =
        Platform.environment['APPDATA'] ?? Directory.systemTemp.path;
    final preferredDataDir = Directory(
      _joinPath([appData, _launcherDataDirName]),
    );
    final legacyDataDir = Directory(
      _joinPath([appData, _legacyLauncherDataDirName]),
    );
    await _migrateLegacyDataDirIfNeeded(
      legacyDataDir: legacyDataDir,
      preferredDataDir: preferredDataDir,
    );
    _dataDir = preferredDataDir;
    await _dataDir.create(recursive: true);
    _settingsFile = File(_joinPath([_dataDir.path, 'settings.json']));
    _installStateFile = File(_joinPath([_dataDir.path, 'install_state.json']));
    _launcherContentCacheFile = File(
      _joinPath([_dataDir.path, 'launcher_content_cache.json']),
    );
    _modsLibraryCacheFile = File(
      _joinPath([_dataDir.path, 'mods_library_cache.json']),
    );
    _dllPresetsFile = File(_joinPath([_dataDir.path, 'dll_presets.json']));
    _injectorDllLibraryFile = File(
      _joinPath([_dataDir.path, 'injector_dlls.json']),
    );
    _installedModsFile = File(
      _joinPath([_dataDir.path, 'installed_mods.json']),
    );
    _logFile = File(_joinPath([_dataDir.path, 'launcher.log']));
    // Reset launcher logs on every app start so each run has a clean log.
    // If truncation fails (locked, permissions), keep going.
    try {
      await _logFile.writeAsString('', flush: true);
    } catch (_) {
      try {
        if (!await _logFile.exists()) {
          await _logFile.create(recursive: true);
        }
      } catch (_) {
        // Ignore log initialization failures.
      }
    }
    _logFileReady = true;
    _storageReady = true;
  }

  Future<void> _migrateLegacyDataDirIfNeeded({
    required Directory legacyDataDir,
    required Directory preferredDataDir,
  }) async {
    if (await preferredDataDir.exists()) return;
    if (!await legacyDataDir.exists()) return;

    try {
      await legacyDataDir.rename(preferredDataDir.path);
      return;
    } catch (_) {
      // Fall back to copying if rename is blocked (for example by a file lock).
    }

    try {
      await preferredDataDir.create(recursive: true);
      await for (final entity in legacyDataDir.list(
        recursive: true,
        followLinks: false,
      )) {
        final relative = entity.path
            .substring(legacyDataDir.path.length)
            .replaceFirst(RegExp(r'^[\\/]+'), '');
        if (relative.isEmpty) continue;
        final destinationPath = _joinPath([preferredDataDir.path, relative]);
        if (entity is Directory) {
          await Directory(destinationPath).create(recursive: true);
          continue;
        }
        if (entity is File) {
          final destinationFile = File(destinationPath);
          await destinationFile.parent.create(recursive: true);
          if (!await destinationFile.exists()) {
            await entity.copy(destinationPath);
          }
        }
      }
    } catch (_) {
      // If migration fails, continue with the preferred directory path.
    }
  }

  String? _resolveBundledAssetFilePath(String bundledAssetPath) {
    final normalized = bundledAssetPath
        .trim()
        .replaceAll('\\', '/')
        .replaceFirst(RegExp(r'^/+'), '');
    if (normalized.isEmpty) return null;

    final parts = normalized
        .split('/')
        .where((part) => part.trim().isNotEmpty)
        .toList();
    if (parts.isEmpty) return null;

    for (final candidate in _bundledAssetPathCandidates(parts)) {
      if (File(candidate).existsSync()) return candidate;
    }

    return null;
  }

  String? _resolveBundledAssetDirectoryPath(String bundledAssetPath) {
    final normalized = bundledAssetPath
        .trim()
        .replaceAll('\\', '/')
        .replaceFirst(RegExp(r'^/+'), '');
    if (normalized.isEmpty) return null;

    final parts = normalized
        .split('/')
        .where((part) => part.trim().isNotEmpty)
        .toList();
    if (parts.isEmpty) return null;

    final seen = <String>{};
    for (final candidate in _bundledAssetPathCandidates(parts)) {
      if (!seen.add(candidate.toLowerCase())) continue;
      if (Directory(candidate).existsSync()) return candidate;
    }
    return null;
  }

  List<String> _bundledAssetPathCandidates(List<String> parts) {
    final exeDir = File(Platform.resolvedExecutable).parent.path;
    final currentDir = Directory.current.path;
    final candidates = <String>[
      _joinPath([exeDir, 'data', 'flutter_assets', ...parts]),
      _joinPath([currentDir, ...parts]),
      _joinPath([currentDir, 'atlas_link_flutter', ...parts]),
    ];

    final parentDir = Directory(currentDir).parent.path;
    if (parentDir != currentDir) {
      candidates.add(_joinPath([parentDir, ...parts]));
      candidates.add(_joinPath([parentDir, 'atlas_link_flutter', ...parts]));
    }

    return candidates;
  }

  bool _isManagedBundledDllPath(String configuredPath, String fileName) {
    final raw = configuredPath.trim();
    if (raw.isEmpty) return false;
    if (!_bundledDllFileNameMatches(_basename(raw), fileName)) return false;

    final normalizedRaw = _normalizePath(raw);
    final names = <String>{fileName, ..._legacyBundledDllFileNames(fileName)};
    final candidates = <String>[
      for (final name in names) _joinPath([_dataDir.path, 'dlls', name]),
    ];

    final appData = Platform.environment['APPDATA'];
    if (appData != null && appData.trim().isNotEmpty) {
      for (final name in names) {
        candidates.add(
          _joinPath([appData, _legacyLauncherDataDirName, 'dlls', name]),
        );
      }
    }

    for (final candidate in candidates) {
      if (_normalizePath(candidate) == normalizedRaw) return true;
    }
    return false;
  }

  bool _looksLikeBundledAssetDllPath(String configuredPath, String fileName) {
    final raw = configuredPath.trim();
    if (raw.isEmpty) return false;
    if (!_bundledDllFileNameMatches(_basename(raw), fileName)) return false;

    final normalizedRaw = _normalizePath(raw);
    final names = <String>{fileName, ..._legacyBundledDllFileNames(fileName)};
    for (final name in names) {
      final needle = _normalizePath(
        _joinPath(['data', 'flutter_assets', 'assets', 'dlls', name]),
      );
      if (normalizedRaw.contains(needle)) return true;
    }
    return false;
  }

  bool _usesLegacyBundledDllCasing(String configuredPath, String fileName) {
    final name = _basename(configuredPath.trim());
    return name.toLowerCase() == fileName.toLowerCase() && name != fileName;
  }

  bool _usesLegacyBundledDllName(String configuredPath, String fileName) {
    final name = _basename(configuredPath.trim());
    if (name == fileName) return false;
    return _bundledDllFileNameMatches(name, fileName);
  }

  bool _bundledDllFileNameMatches(String candidate, String fileName) {
    final candidateLower = candidate.trim().toLowerCase();
    final fileLower = fileName.trim().toLowerCase();
    if (candidateLower == fileLower) return true;
    return _legacyBundledDllFileNames(fileName).contains(candidateLower);
  }

  Set<String> _legacyBundledDllFileNames(String fileName) {
    switch (fileName.trim().toLowerCase()) {
      case 'large pak patcher.dll':
        return <String>{'largepakpatch.dll', 'largepakpatcher.dll'};
      case 'remix console.dll':
        return <String>{'remixconsole.dll'};
      default:
        return const <String>{};
    }
  }

  bool _isBundledAssetDllFromCurrentInstall(
    String configuredPath,
    String fileName,
  ) {
    if (!_looksLikeBundledAssetDllPath(configuredPath, fileName)) return false;
    final exeDir = File(Platform.resolvedExecutable).parent.path;
    final normalizedExeDir = _normalizePath(exeDir);
    final normalizedPath = _normalizePath(configuredPath);
    final prefix = normalizedExeDir.endsWith('/')
        ? normalizedExeDir
        : '$normalizedExeDir/';
    return normalizedPath.startsWith(prefix);
  }

  _BundledDllSpec _bundledDllSpecByFileName(String fileName) {
    for (final spec in _bundledDllSpecs) {
      if (_bundledDllFileNameMatches(fileName, spec.fileName)) return spec;
    }
    throw StateError('Unknown bundled DLL file name: $fileName');
  }

  String? _resolveCurrentBundledDefaultDllPath(_BundledDllSpec spec) {
    final configuredPath = _configuredDllPathForSpec(spec).trim();
    final managedPath = _joinPath([_dataDir.path, 'dlls', spec.fileName]);
    final configuredLooksLikeDll =
        configuredPath.isNotEmpty &&
        configuredPath.toLowerCase().endsWith('.dll');
    final configuredIsBundledDefaultLocation =
        _isManagedBundledDllPath(configuredPath, spec.fileName) ||
        _looksLikeBundledAssetDllPath(configuredPath, spec.fileName);
    if (configuredLooksLikeDll &&
        configuredIsBundledDefaultLocation &&
        File(configuredPath).existsSync()) {
      if (_isManagedBundledDllPath(configuredPath, spec.fileName)) {
        return managedPath;
      }
      return configuredPath;
    }

    final installedPath = _resolveBundledAssetFilePath(spec.assetPath);
    if (installedPath != null && installedPath.trim().isNotEmpty) {
      return installedPath;
    }
    if (File(managedPath).existsSync()) return managedPath;
    return null;
  }

  bool _isConfiguredBundledDefaultDllSelected(_BundledDllSpec spec) {
    final configuredPath = _configuredDllPathForSpec(spec).trim();
    if (configuredPath.isEmpty) return false;
    if (!configuredPath.toLowerCase().endsWith('.dll')) return false;
    return _isManagedBundledDllPath(configuredPath, spec.fileName) ||
        _looksLikeBundledAssetDllPath(configuredPath, spec.fileName);
  }

  Future<String> _bundledDefaultDllPresetPath(_BundledDllSpec spec) async {
    final managedPath = _joinPath([_dataDir.path, 'dlls', spec.fileName]);
    if (File(managedPath).existsSync()) return managedPath;

    final path = await _ensureBundledDll(
      bundledAssetPath: spec.assetPath,
      bundledFileName: spec.fileName,
      label: spec.label,
      showFeedback: false,
    );
    return path?.trim() ?? '';
  }

  String _configuredDllPathForSpec(_BundledDllSpec spec) {
    switch (spec.fileNameLower) {
      case 'console.dll':
      case 'remix console.dll':
      case 'remixconsole.dll':
        return _settings.unrealEnginePatcherPath;
      case 'tellurium.dll':
      case 'starfall.dll':
        return _settings.authenticationPatcherPath;
      case 'memory.dll':
        return _settings.memoryPatcherPath;
      case 'magnesium.dll':
      case 'remix.dll':
        return _settings.gameServerFilePath;
      default:
        return '';
    }
  }

  Future<String?> _computeGitBlobShaForFile(File file) async {
    try {
      if (!await file.exists()) return null;
      final bytes = await file.readAsBytes();
      final header = ascii.encode('blob ${bytes.length}\u0000');
      final payload = Uint8List(header.length + bytes.length);
      payload.setRange(0, header.length, header);
      payload.setRange(header.length, payload.length, bytes);
      return crypto.sha1.convert(payload).toString().toLowerCase();
    } catch (error) {
      _log('settings', 'Failed to hash DLL file (${file.path}): $error');
      return null;
    }
  }

  Future<Map<String, _BundledDllRemoteAsset>> _fetchBundledDllRemoteAssets({
    bool forceRefresh = false,
  }) async {
    if (!forceRefresh && _bundledDllRemoteAssetsByName.isNotEmpty) {
      return _bundledDllRemoteAssetsByName;
    }

    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 8)
      ..userAgent = 'ATLAS-Link';
    try {
      final request = await client.getUrl(
        Uri.parse(_atlasLinkBundledDllContentsApi),
      );
      request.followRedirects = true;
      request.maxRedirects = 6;
      request.headers.set('Accept', 'application/vnd.github+json');
      final response = await request.close();
      if (response.statusCode != 200) {
        final remaining = response.headers.value('x-ratelimit-remaining');
        final hint = remaining == null || remaining.trim().isEmpty
            ? ''
            : ' (rate remaining $remaining)';
        _log(
          'settings',
          'GitHub bundled DLL manifest request failed (HTTP ${response.statusCode})$hint.',
        );
        return const <String, _BundledDllRemoteAsset>{};
      }

      final body = await response.transform(utf8.decoder).join();
      if (body.trim().isEmpty) {
        return const <String, _BundledDllRemoteAsset>{};
      }
      final decoded = jsonDecode(body);
      if (decoded is! List) {
        return const <String, _BundledDllRemoteAsset>{};
      }

      final next = <String, _BundledDllRemoteAsset>{};
      for (final entry in decoded) {
        if (entry is! Map) continue;
        final map = entry.cast<dynamic, dynamic>();
        final type = (map['type'] ?? '').toString().trim().toLowerCase();
        if (type != 'file') continue;

        final name = (map['name'] ?? '').toString().trim();
        final sha = (map['sha'] ?? '').toString().trim().toLowerCase();
        final downloadUrl = (map['download_url'] ?? '').toString().trim();
        if (name.isEmpty || sha.isEmpty) continue;

        next[name.toLowerCase()] = _BundledDllRemoteAsset(
          sha: sha,
          downloadUrl: downloadUrl,
        );
      }

      if (next.isNotEmpty) {
        _bundledDllRemoteAssetsByName = next;
      }
      return next;
    } catch (error) {
      _log('settings', 'Failed to fetch bundled DLL manifest: $error');
      return const <String, _BundledDllRemoteAsset>{};
    } finally {
      client.close(force: true);
    }
  }

  Future<void> _checkForBundledDllDefaultUpdates({
    required bool silent,
    bool forceRefresh = true,
  }) async {
    if (_checkingBundledDllDefaultsUpdate) return;
    _checkingBundledDllDefaultsUpdate = true;
    try {
      final remoteAssets = await _fetchBundledDllRemoteAssets(
        forceRefresh: forceRefresh,
      );
      if (remoteAssets.isEmpty) {
        if (!silent && mounted) {
          _toast('Unable to check default DLL updates right now');
        }
        return;
      }

      final updatedFiles = <String>{};
      for (final spec in _bundledDllSpecs) {
        if (!_isConfiguredBundledDefaultDllSelected(spec)) {
          continue;
        }

        final remote = remoteAssets[spec.fileNameLower];
        if (remote == null) continue;

        final configuredPath = _configuredDllPathForSpec(spec).trim();
        final localPath =
            configuredPath.isNotEmpty && File(configuredPath).existsSync()
            ? configuredPath
            : _resolveCurrentBundledDefaultDllPath(spec);
        if (localPath == null || localPath.trim().isEmpty) {
          updatedFiles.add(spec.fileNameLower);
          continue;
        }
        final localSha = await _computeGitBlobShaForFile(File(localPath));
        if (localSha == null || localSha != remote.sha) {
          updatedFiles.add(spec.fileNameLower);
        }
      }

      if (mounted) {
        setState(() {
          _bundledDllUpdatedFileNames = updatedFiles;
          _bundledDllDefaultsUpdateAvailable = updatedFiles.isNotEmpty;
        });
      } else {
        _bundledDllUpdatedFileNames = updatedFiles;
        _bundledDllDefaultsUpdateAvailable = updatedFiles.isNotEmpty;
      }

      if (!silent && mounted) {
        if (updatedFiles.isEmpty) {
          _toast('Default DLLs are up to date');
        } else {
          _toast('New Default DLL updates are available');
        }
      }
    } catch (error) {
      _log('settings', 'Failed to check for bundled DLL updates: $error');
      if (!silent && mounted) {
        _toast('Unable to check default DLL updates right now');
      }
    } finally {
      _checkingBundledDllDefaultsUpdate = false;
    }
  }

  Future<String?> _downloadLatestBundledDllFromGitHub({
    required _BundledDllSpec spec,
    Map<String, _BundledDllRemoteAsset>? remoteAssets,
    bool showProgressUi = true,
    String? outputPathOverride,
  }) async {
    final resolvedRemoteAssets =
        remoteAssets ?? await _fetchBundledDllRemoteAssets(forceRefresh: true);
    final remote = resolvedRemoteAssets[spec.fileNameLower];
    final fallbackUrl =
        '$_atlasLinkBundledDllFallbackBaseUrl${spec.normalizedAssetPath}';
    final downloadUrl = remote?.downloadUrl.trim().isNotEmpty == true
        ? remote!.downloadUrl.trim()
        : fallbackUrl;

    final outputPath = outputPathOverride?.trim().isNotEmpty == true
        ? outputPathOverride!.trim()
        : _joinPath([_dataDir.path, 'dlls', spec.fileName]);
    final outputFile = File(outputPath);
    final outputDir = outputFile.parent;
    final tmp = File('$outputPath.tmp');
    try {
      await outputDir.create(recursive: true);
      if (_isManagedBundledDllPath(outputPath, spec.fileName)) {
        await _normalizeManagedDllFileNameCasing(outputDir, spec.fileName);
      }
      if (await tmp.exists()) {
        await tmp.delete();
      }

      final progressMessage = 'Updating ${spec.fileName}...';
      if (showProgressUi && mounted) {
        _toastProgress(progressMessage, progress: null, indeterminate: true);
      }

      await _downloadToFile(
        downloadUrl,
        tmp,
        onProgress: (receivedBytes, totalBytes) {
          if (!showProgressUi || !mounted) return;
          if (totalBytes == null || totalBytes <= 0) {
            _toastProgress(
              progressMessage,
              progress: null,
              indeterminate: true,
            );
            return;
          }
          final ratio = (receivedBytes / totalBytes).clamp(0.0, 1.0);
          _toastProgress(
            progressMessage,
            progress: ratio,
            indeterminate: false,
          );
        },
      );
      final length = await tmp.length();
      if (length <= 0) {
        throw 'Downloaded file was empty.';
      }

      if (await outputFile.exists()) {
        await outputFile.delete();
      }
      await tmp.rename(outputFile.path);

      if (remote != null) {
        final localSha = await _computeGitBlobShaForFile(outputFile);
        if (localSha == null || localSha != remote.sha) {
          throw 'Downloaded file hash did not match GitHub metadata.';
        }
      }

      if (showProgressUi && mounted) {
        _toastProgressDismiss();
      }
      return outputPath;
    } catch (error) {
      _log(
        'settings',
        'Failed to download latest ${spec.label} DLL from GitHub ($downloadUrl): $error',
      );
      if (showProgressUi && mounted) {
        _toastProgressDismiss();
      }
      try {
        if (await tmp.exists()) {
          await tmp.delete();
        }
      } catch (_) {
        // Ignore cleanup failures.
      }
      return null;
    }
  }

  String _encodeGitHubPath(String path) {
    return path
        .trim()
        .replaceAll('\\', '/')
        .split('/')
        .where((part) => part.trim().isNotEmpty)
        .map(Uri.encodeComponent)
        .join('/');
  }

  String _atlasResourcesContentsApi(String path) {
    final encoded = _encodeGitHubPath(path);
    final suffix = encoded.isEmpty ? '' : '/$encoded';
    return 'https://api.github.com/repos/$_atlasResourcesOwner/$_atlasResourcesRepo/contents$suffix?ref=$_atlasResourcesRef';
  }

  String _atlasResourcesRecursiveTreeApi() {
    return 'https://api.github.com/repos/$_atlasResourcesOwner/$_atlasResourcesRepo/git/trees/$_atlasResourcesRef?recursive=1';
  }

  String _atlasResourcesRawUrl(String path) {
    final encoded = _encodeGitHubPath(path);
    return 'https://raw.githubusercontent.com/$_atlasResourcesOwner/$_atlasResourcesRepo/$_atlasResourcesRef/$encoded';
  }

  String _atlasResourcesTreeUrl(String path) {
    final encoded = _encodeGitHubPath(path);
    return '$_atlasResourcesRepository/tree/$_atlasResourcesRef/$encoded';
  }

  Uri _atlasResourcesCommitsUri(String path) {
    final normalized = path.trim().replaceAll('\\', '/');
    return Uri.https(
      'api.github.com',
      '/repos/$_atlasResourcesOwner/$_atlasResourcesRepo/commits',
      <String, String>{
        'sha': _atlasResourcesRef,
        'path': normalized,
        'per_page': '1',
      },
    );
  }

  Future<List<Map<String, dynamic>>> _fetchAtlasResourceContents(
    String path,
  ) async {
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 8)
      ..userAgent = 'ATLAS-Link';
    try {
      final request = await client.getUrl(
        Uri.parse(_atlasResourcesContentsApi(path)),
      );
      request.followRedirects = true;
      request.maxRedirects = 6;
      request.headers.set('Accept', 'application/vnd.github+json');
      final response = await request.close();
      if (response.statusCode != 200) {
        throw 'GitHub contents request failed (HTTP ${response.statusCode})';
      }
      final body = await response.transform(utf8.decoder).join();
      final decoded = jsonDecode(body);
      if (decoded is! List) return const <Map<String, dynamic>>[];
      return decoded
          .whereType<Map>()
          .map((entry) => entry.cast<String, dynamic>())
          .toList();
    } finally {
      client.close(force: true);
    }
  }

  Future<List<Map<String, dynamic>>> _fetchAtlasResourceTreeEntries() async {
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 8)
      ..userAgent = 'ATLAS-Link';
    try {
      final request = await client.getUrl(
        Uri.parse(_atlasResourcesRecursiveTreeApi()),
      );
      request.followRedirects = true;
      request.maxRedirects = 6;
      request.headers.set('Accept', 'application/vnd.github+json');
      final response = await request.close();
      if (response.statusCode != 200) {
        throw 'GitHub tree request failed (HTTP ${response.statusCode})';
      }
      final body = await response.transform(utf8.decoder).join();
      final decoded = jsonDecode(body);
      if (decoded is! Map<String, dynamic>) {
        return const <Map<String, dynamic>>[];
      }
      if (decoded['truncated'] == true) {
        throw 'GitHub tree response was truncated.';
      }
      final tree = decoded['tree'];
      if (tree is! List) return const <Map<String, dynamic>>[];
      return tree
          .whereType<Map>()
          .map((entry) => entry.cast<String, dynamic>())
          .toList();
    } finally {
      client.close(force: true);
    }
  }

  Future<int> _fetchAtlasResourceLastUpdatedEpochMs(String path) async {
    final normalized = path.trim().replaceAll('\\', '/');
    if (normalized.isEmpty) return 0;

    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 8)
      ..userAgent = 'ATLAS-Link';
    try {
      final request = await client.getUrl(
        _atlasResourcesCommitsUri(normalized),
      );
      request.followRedirects = true;
      request.maxRedirects = 6;
      request.headers.set('Accept', 'application/vnd.github+json');
      final response = await request.close();
      if (response.statusCode != 200) {
        throw 'GitHub commits request failed (HTTP ${response.statusCode})';
      }

      final body = await response.transform(utf8.decoder).join();
      final decoded = jsonDecode(body);
      if (decoded is! List || decoded.isEmpty) return 0;

      Map<String, dynamic>? firstCommit;
      for (final item in decoded) {
        if (item is Map<String, dynamic>) {
          firstCommit = item;
          break;
        }
        if (item is Map) {
          firstCommit = item.cast<String, dynamic>();
          break;
        }
      }
      if (firstCommit == null) return 0;

      final commitRaw = firstCommit['commit'];
      if (commitRaw is! Map) return 0;
      final commit = commitRaw.cast<String, dynamic>();
      final committerRaw = commit['committer'];
      final authorRaw = commit['author'];
      final committer = committerRaw is Map
          ? committerRaw.cast<String, dynamic>()
          : const <String, dynamic>{};
      final author = authorRaw is Map
          ? authorRaw.cast<String, dynamic>()
          : const <String, dynamic>{};
      final dateText = (committer['date'] ?? author['date'] ?? '')
          .toString()
          .trim();
      final parsed = DateTime.tryParse(dateText);
      return parsed?.toUtc().millisecondsSinceEpoch ?? 0;
    } finally {
      client.close(force: true);
    }
  }

  bool _isAtlasModImageFile(String name) {
    final lower = name.toLowerCase();
    return lower.endsWith('.png') ||
        lower.endsWith('.jpg') ||
        lower.endsWith('.jpeg') ||
        lower.endsWith('.webp') ||
        lower.endsWith('.gif') ||
        lower.endsWith('.bmp');
  }

  bool _isAtlasModVideoFile(String name) {
    final lower = name.toLowerCase();
    return lower.endsWith('.mp4') ||
        lower.endsWith('.webm') ||
        lower.endsWith('.mov') ||
        lower.endsWith('.m4v') ||
        lower.endsWith('.avi') ||
        lower.endsWith('.wmv') ||
        lower.endsWith('.mkv');
  }

  bool _isAtlasModMediaFile(String name) {
    return _isAtlasModImageFile(name) || _isAtlasModVideoFile(name);
  }

  _AtlasModMediaType _atlasModMediaTypeForPath(
    String path, [
    String explicitType = '',
  ]) {
    final type = explicitType.trim().toLowerCase();
    if (type == 'image' || type == 'gif' || type == 'picture') {
      return _AtlasModMediaType.image;
    }
    if (type == 'video' || type == 'movie') {
      return _AtlasModMediaType.video;
    }
    return _isAtlasModVideoFile(path)
        ? _AtlasModMediaType.video
        : _AtlasModMediaType.image;
  }

  bool _isInstallableAtlasModFile(_AtlasModType type, String name) {
    final lower = name.toLowerCase();
    return switch (type) {
      _AtlasModType.dll => lower.endsWith('.dll'),
      _AtlasModType.exe => lower.endsWith('.exe'),
      _AtlasModType.pak =>
        lower.endsWith('.pak') ||
            lower.endsWith('.sig') ||
            lower.endsWith('.ucas') ||
            lower.endsWith('.utoc'),
    };
  }

  List<_AtlasModMedia> _dedupeAtlasModMedia(List<_AtlasModMedia> media) {
    final seen = <String>{};
    final result = <_AtlasModMedia>[];
    for (final item in media) {
      final url = item.url.trim();
      if (url.isEmpty) continue;
      final key = url.toLowerCase();
      if (!seen.add(key)) continue;
      result.add(item);
    }
    return result;
  }

  List<_AtlasModMedia> _atlasModMediaFromMetadata(
    Map<String, dynamic> metadata,
    List<String> keys,
    String Function(String value) resolve,
  ) {
    final media = <_AtlasModMedia>[];
    for (final key in keys) {
      final raw = metadata[key];
      final items = raw is List
          ? raw
          : raw == null
          ? const <dynamic>[]
          : <dynamic>[raw];
      for (final item in items) {
        String value = '';
        String label = '';
        String explicitType = '';
        if (item is String) {
          value = item.trim();
        } else if (item is Map) {
          final map = item.cast<dynamic, dynamic>();
          value =
              (map['url'] ??
                      map['src'] ??
                      map['path'] ??
                      map['file'] ??
                      map['relativePath'] ??
                      '')
                  .toString()
                  .trim();
          label = (map['label'] ?? map['title'] ?? map['name'] ?? '')
              .toString()
              .trim();
          explicitType = (map['type'] ?? map['kind'] ?? '').toString().trim();
        }
        if (value.isEmpty) continue;
        final resolved = resolve(value);
        if (resolved.isEmpty) continue;
        media.add(
          _AtlasModMedia(
            url: resolved,
            type: _atlasModMediaTypeForPath(value, explicitType),
            label: label.isEmpty ? _basename(value) : label,
          ),
        );
      }
    }
    return _dedupeAtlasModMedia(media);
  }

  Future<List<_AtlasModMedia>> _fetchAtlasResourceMediaFiles(
    String path, {
    int depth = 0,
  }) async {
    if (depth > 4) return const <_AtlasModMedia>[];
    final media = <_AtlasModMedia>[];
    List<Map<String, dynamic>> contents;
    try {
      contents = await _fetchAtlasResourceContents(path);
    } catch (error) {
      _log('mods', 'Failed to scan media at $path: $error');
      return const <_AtlasModMedia>[];
    }
    for (final entry in contents) {
      final name = (entry['name'] ?? '').toString();
      final type = (entry['type'] ?? '').toString().toLowerCase();
      final entryPath = (entry['path'] ?? '').toString();
      if (type == 'file' && _isAtlasModMediaFile(name)) {
        final url = (entry['download_url'] ?? '').toString().trim();
        if (url.isEmpty) continue;
        media.add(
          _AtlasModMedia(
            url: url,
            type: _atlasModMediaTypeForPath(name),
            label: name,
          ),
        );
      } else if (type == 'dir' && entryPath.trim().isNotEmpty) {
        media.addAll(
          await _fetchAtlasResourceMediaFiles(entryPath, depth: depth + 1),
        );
      }
    }
    return _dedupeAtlasModMedia(media);
  }

  String _safeFileName(String value) {
    final sanitized = value
        .trim()
        .replaceAll(RegExp(r'[<>:"/\\|?*]'), '_')
        .replaceAll(RegExp(r'\s+'), ' ');
    return sanitized.isEmpty ? 'mod-file' : sanitized;
  }

  String _resolveAtlasResourceUrl(String value, String folderPath) {
    final trimmed = value.trim();
    if (trimmed.isEmpty) return '';
    final normalized = trimmed.replaceAll('\\', '/');
    final lower = normalized.toLowerCase();
    if (lower.startsWith('http://') || lower.startsWith('https://')) {
      return normalized;
    }
    final relative = normalized.replaceFirst(RegExp(r'^/+'), '');
    final base = folderPath.trim().replaceAll('\\', '/');
    return _atlasResourcesRawUrl(base.isEmpty ? relative : '$base/$relative');
  }

  String _stringFromJson(
    Map<String, dynamic> json,
    List<String> keys, [
    String fallback = '',
  ]) {
    for (final key in keys) {
      final value = json[key];
      if (value == null) continue;
      final text = value.toString().trim();
      if (text.isNotEmpty) return text;
    }
    return fallback;
  }

  List<String> _stringListFromJson(
    Map<String, dynamic> json,
    List<String> keys,
  ) {
    for (final key in keys) {
      final value = json[key];
      if (value is List) {
        return value
            .map((item) => item.toString().trim())
            .where((item) => item.isNotEmpty)
            .toList();
      }
      if (value is String && value.trim().isNotEmpty) {
        return <String>[value.trim()];
      }
    }
    return const <String>[];
  }

  List<_AtlasModFile> _atlasModFilesFromMetadata(
    Map<String, dynamic> metadata,
    String folderPath,
  ) {
    final raw =
        metadata['files'] ?? metadata['downloads'] ?? metadata['download'];
    final items = raw is List
        ? raw
        : raw == null
        ? const <dynamic>[]
        : <dynamic>[raw];
    final files = <_AtlasModFile>[];
    for (final item in items) {
      String name = '';
      String url = '';
      String relativePath = '';
      if (item is String) {
        relativePath = item.trim();
        url = _resolveAtlasResourceUrl(relativePath, folderPath);
        name = _basename(relativePath);
      } else if (item is Map) {
        final map = item.cast<dynamic, dynamic>();
        relativePath = (map['path'] ?? map['file'] ?? map['relativePath'] ?? '')
            .toString()
            .trim();
        url =
            (map['url'] ??
                    map['downloadUrl'] ??
                    map['download_url'] ??
                    map['href'] ??
                    '')
                .toString()
                .trim();
        if (url.isEmpty && relativePath.isNotEmpty) {
          url = _resolveAtlasResourceUrl(relativePath, folderPath);
        }
        name = (map['name'] ?? map['fileName'] ?? '').toString().trim();
        if (name.isEmpty) {
          name = _basename(relativePath.isEmpty ? url : relativePath);
        }
      }
      if (name.isEmpty || url.isEmpty) continue;
      files.add(
        _AtlasModFile(
          name: name,
          downloadUrl: _resolveAtlasResourceUrl(url, folderPath),
          relativePath: relativePath,
        ),
      );
    }
    return files;
  }

  /// Fills in git blob SHAs for [files] using a basename -> sha map built from
  /// the folder's GitHub entries, so each installable file carries a content
  /// fingerprint regardless of whether it came from metadata or inference.
  List<_AtlasModFile> _withAtlasModFileShas(
    List<_AtlasModFile> files,
    Map<String, String> shaByName,
  ) {
    if (files.isEmpty || shaByName.isEmpty) return files;
    return [
      for (final file in files)
        file.sha.isNotEmpty
            ? file
            : file.withSha(
                shaByName[_basename(file.name).toLowerCase()] ??
                    shaByName[_basename(file.relativePath).toLowerCase()] ??
                    '',
              ),
    ];
  }

  Future<_AtlasModEntry?> _parseAtlasModFolder(
    _AtlasModType type,
    Map<String, dynamic> folderEntry,
  ) async {
    final folderName = (folderEntry['name'] ?? '').toString().trim();
    final folderPath = (folderEntry['path'] ?? '${type.folderName}/$folderName')
        .toString()
        .trim()
        .replaceAll('\\', '/');
    if (folderName.isEmpty || folderPath.isEmpty) return null;

    final contents = await _fetchAtlasResourceContents(folderPath);
    Map<String, dynamic> metadata = <String, dynamic>{};
    final metadataEntry = contents.cast<Map<String, dynamic>?>().firstWhere(
      (entry) =>
          (entry?['type'] ?? '').toString().toLowerCase() == 'file' &&
          (entry?['name'] ?? '').toString().toLowerCase() == 'metadata.json',
      orElse: () => null,
    );
    final metadataUrl = (metadataEntry?['download_url'] ?? '')
        .toString()
        .trim();
    if (metadataUrl.isNotEmpty) {
      try {
        final raw = (await _downloadText(metadataUrl)).trim();
        if (raw.isNotEmpty) {
          final decoded = jsonDecode(raw);
          if (decoded is Map<String, dynamic>) {
            metadata = decoded;
          } else if (decoded is Map) {
            metadata = decoded.cast<String, dynamic>();
          }
        }
      } catch (error) {
        _log('mods', 'Failed to parse metadata for $folderPath: $error');
      }
    }

    final inferredFiles = contents
        .where((entry) {
          final name = (entry['name'] ?? '').toString();
          final entryType = (entry['type'] ?? '').toString().toLowerCase();
          return entryType == 'file' && _isInstallableAtlasModFile(type, name);
        })
        .map(
          (entry) => _AtlasModFile(
            name: (entry['name'] ?? '').toString(),
            downloadUrl: (entry['download_url'] ?? '').toString(),
            relativePath: (entry['path'] ?? '').toString(),
          ),
        )
        .where(
          (file) => file.name.trim().isNotEmpty && file.downloadUrl.isNotEmpty,
        )
        .toList();

    var files = _atlasModFilesFromMetadata(metadata, folderPath);
    if (files.isEmpty) files = inferredFiles;
    final shaByName = <String, String>{};
    for (final entry in contents) {
      if ((entry['type'] ?? '').toString().toLowerCase() != 'file') continue;
      final sha = (entry['sha'] ?? '').toString().trim();
      final name = (entry['name'] ?? '').toString().trim();
      if (sha.isEmpty || name.isEmpty) continue;
      shaByName[name.toLowerCase()] = sha;
    }
    files = _withAtlasModFileShas(files, shaByName);

    final directMedia = contents
        .where((entry) {
          final name = (entry['name'] ?? '').toString();
          final entryType = (entry['type'] ?? '').toString().toLowerCase();
          return entryType == 'file' && _isAtlasModMediaFile(name);
        })
        .map((entry) {
          final name = (entry['name'] ?? '').toString();
          return _AtlasModMedia(
            url: (entry['download_url'] ?? '').toString().trim(),
            type: _atlasModMediaTypeForPath(name),
            label: name,
          );
        })
        .where((item) => item.url.trim().isNotEmpty)
        .toList();

    final contentDirs = contents.where((entry) {
      final entryType = (entry['type'] ?? '').toString().toLowerCase();
      final name = (entry['name'] ?? '').toString().toLowerCase();
      return entryType == 'dir' &&
          (name == 'content' || name == 'media' || name == 'gallery');
    });
    final contentMedia = <_AtlasModMedia>[];
    for (final entry in contentDirs) {
      final path = (entry['path'] ?? '').toString().trim();
      if (path.isEmpty) continue;
      contentMedia.addAll(await _fetchAtlasResourceMediaFiles(path));
    }

    final metadataMedia = _atlasModMediaFromMetadata(metadata, const <String>[
      'media',
      'content',
      'gallery',
      'screenshots',
      'pictures',
      'images',
      'videos',
    ], (value) => _resolveAtlasResourceUrl(value, folderPath));
    final cardImage = _stringFromJson(metadata, const <String>[
      'cardImage',
      'thumbnail',
      'image',
      'picture',
      'cover',
      'preview',
    ]);
    final resolvedCardImage =
        cardImage.isNotEmpty && _isAtlasModImageFile(cardImage)
        ? _resolveAtlasResourceUrl(cardImage, folderPath)
        : '';
    final media = _dedupeAtlasModMedia(<_AtlasModMedia>[
      if (resolvedCardImage.isNotEmpty)
        _AtlasModMedia(
          url: resolvedCardImage,
          type: _AtlasModMediaType.image,
          label: _basename(cardImage),
        ),
      ...metadataMedia,
      ...directMedia,
      ...contentMedia,
    ]);
    final images = media
        .where((item) => item.type == _AtlasModMediaType.image)
        .map((item) => item.url)
        .toList();
    final primaryImage = resolvedCardImage.isNotEmpty
        ? resolvedCardImage
        : images.isNotEmpty
        ? images.first
        : '';

    return _AtlasModEntry(
      id: '${type.name}:${folderPath.toLowerCase()}',
      type: type,
      folderName: folderName,
      folderPath: folderPath,
      name: _stringFromJson(metadata, const <String>[
        'name',
        'title',
        'displayName',
      ], folderName),
      author: _stringFromJson(metadata, const <String>[
        'author',
        'creator',
        'by',
      ], 'ATLAS Resources'),
      cardDescription: _stringFromJson(metadata, const <String>[
        'cardDescription',
        'shortDescription',
        'summary',
        'teaser',
      ]),
      description: _stringFromJson(metadata, const <String>[
        'description',
        'detailDescription',
        'details',
        'body',
      ], _atlasModDefaultDescription(type)),
      version: _stringFromJson(metadata, const <String>[
        'version',
        'gameVersion',
        'fortniteVersion',
        'build',
      ]),
      tags: _stringListFromJson(
        metadata,
        const <String>['tags', 'labels', 'categories', 'badges'],
      ).where((tag) => tag.trim().isNotEmpty).map((tag) => tag.trim()).toList(),
      cardImage: primaryImage,
      images: images,
      media: media,
      sourceUrl: _stringFromJson(metadata, const <String>[
        'sourceUrl',
        'source',
        'repo',
        'repository',
        'url',
      ], _atlasResourcesTreeUrl(folderPath)),
      dependencies: _stringListFromJson(metadata, const <String>[
        'dependencies',
        'requires',
        'dependsOn',
      ]),
      dataSlot: _stringFromJson(metadata, const <String>[
        'dataSlot',
        'dataManagementSlot',
        'patcherSlot',
        'dllRole',
        'slot',
      ]),
      files: files,
    );
  }

  String _atlasModDefaultDescription(_AtlasModType type) => switch (type) {
    _AtlasModType.pak => 'Pak mod for ATLAS builds.',
    _AtlasModType.dll => 'DLL mod for the injector.',
    _AtlasModType.exe => 'Patched executable for ATLAS builds.',
  };

  Future<_AtlasModEntry?> _parseAtlasModFolderFromTree(
    _AtlasModType type,
    String folderPath,
    List<Map<String, dynamic>> treeEntries,
  ) async {
    final normalizedFolderPath = folderPath.trim().replaceAll('\\', '/');
    if (normalizedFolderPath.isEmpty) return null;
    final folderName = _basename(normalizedFolderPath);
    if (folderName.isEmpty) return null;

    final prefix = '$normalizedFolderPath/';
    final childEntries = treeEntries.where((entry) {
      final path = (entry['path'] ?? '').toString().replaceAll('\\', '/');
      return path.startsWith(prefix);
    }).toList();
    if (childEntries.isEmpty) return null;

    bool isBlob(Map<String, dynamic> entry) {
      return (entry['type'] ?? '').toString().toLowerCase() == 'blob';
    }

    String entryPath(Map<String, dynamic> entry) {
      return (entry['path'] ?? '').toString().replaceAll('\\', '/');
    }

    String directChildName(String path) {
      if (!path.startsWith(prefix)) return '';
      final remainder = path.substring(prefix.length);
      return remainder.contains('/') ? '' : remainder;
    }

    final directEntries = childEntries.where((entry) {
      final name = directChildName(entryPath(entry));
      return name.isNotEmpty;
    }).toList();

    Map<String, dynamic> metadata = <String, dynamic>{};
    final metadataEntry = directEntries
        .cast<Map<String, dynamic>?>()
        .firstWhere(
          (entry) =>
              entry != null &&
              isBlob(entry) &&
              directChildName(entryPath(entry)).toLowerCase() ==
                  'metadata.json',
          orElse: () => null,
        );
    final metadataPath = metadataEntry == null ? '' : entryPath(metadataEntry);
    if (metadataPath.isNotEmpty) {
      try {
        final raw = (await _downloadText(
          _atlasResourcesRawUrl(metadataPath),
        )).trim();
        if (raw.isNotEmpty) {
          final decoded = jsonDecode(raw);
          if (decoded is Map<String, dynamic>) {
            metadata = decoded;
          } else if (decoded is Map) {
            metadata = decoded.cast<String, dynamic>();
          }
        }
      } catch (error) {
        _log(
          'mods',
          'Failed to parse metadata for $normalizedFolderPath: $error',
        );
      }
    }

    final inferredFiles = directEntries
        .where((entry) {
          final name = directChildName(entryPath(entry));
          return isBlob(entry) && _isInstallableAtlasModFile(type, name);
        })
        .map((entry) {
          final path = entryPath(entry);
          final name = directChildName(path);
          return _AtlasModFile(
            name: name,
            downloadUrl: _atlasResourcesRawUrl(path),
            relativePath: path,
          );
        })
        .where(
          (file) => file.name.trim().isNotEmpty && file.downloadUrl.isNotEmpty,
        )
        .toList();

    var files = _atlasModFilesFromMetadata(metadata, normalizedFolderPath);
    if (files.isEmpty) files = inferredFiles;
    final shaByName = <String, String>{};
    for (final entry in childEntries) {
      if (!isBlob(entry)) continue;
      final sha = (entry['sha'] ?? '').toString().trim();
      if (sha.isEmpty) continue;
      shaByName[_basename(entryPath(entry)).toLowerCase()] = sha;
    }
    files = _withAtlasModFileShas(files, shaByName);

    final directMedia = directEntries
        .where((entry) {
          final name = directChildName(entryPath(entry));
          return isBlob(entry) && _isAtlasModMediaFile(name);
        })
        .map((entry) {
          final path = entryPath(entry);
          final name = directChildName(path);
          return _AtlasModMedia(
            url: _atlasResourcesRawUrl(path),
            type: _atlasModMediaTypeForPath(name),
            label: name,
          );
        })
        .where((item) => item.url.trim().isNotEmpty)
        .toList();

    final contentMedia = childEntries
        .where((entry) {
          if (!isBlob(entry)) return false;
          final path = entryPath(entry);
          if (!path.startsWith(prefix)) return false;
          final remainder = path.substring(prefix.length);
          final slashIndex = remainder.indexOf('/');
          if (slashIndex <= 0) return false;
          final topDirectory = remainder.substring(0, slashIndex).toLowerCase();
          return (topDirectory == 'content' ||
                  topDirectory == 'media' ||
                  topDirectory == 'gallery') &&
              _isAtlasModMediaFile(_basename(path));
        })
        .map((entry) {
          final path = entryPath(entry);
          final name = _basename(path);
          return _AtlasModMedia(
            url: _atlasResourcesRawUrl(path),
            type: _atlasModMediaTypeForPath(name),
            label: name,
          );
        })
        .toList();

    final metadataMedia = _atlasModMediaFromMetadata(metadata, const <String>[
      'media',
      'content',
      'gallery',
      'screenshots',
      'pictures',
      'images',
      'videos',
    ], (value) => _resolveAtlasResourceUrl(value, normalizedFolderPath));
    final cardImage = _stringFromJson(metadata, const <String>[
      'cardImage',
      'thumbnail',
      'image',
      'picture',
      'cover',
      'preview',
    ]);
    final resolvedCardImage =
        cardImage.isNotEmpty && _isAtlasModImageFile(cardImage)
        ? _resolveAtlasResourceUrl(cardImage, normalizedFolderPath)
        : '';
    final media = _dedupeAtlasModMedia(<_AtlasModMedia>[
      if (resolvedCardImage.isNotEmpty)
        _AtlasModMedia(
          url: resolvedCardImage,
          type: _AtlasModMediaType.image,
          label: _basename(cardImage),
        ),
      ...metadataMedia,
      ...directMedia,
      ...contentMedia,
    ]);
    final images = media
        .where((item) => item.type == _AtlasModMediaType.image)
        .map((item) => item.url)
        .toList();
    final primaryImage = resolvedCardImage.isNotEmpty
        ? resolvedCardImage
        : images.isNotEmpty
        ? images.first
        : '';

    return _AtlasModEntry(
      id: '${type.name}:${normalizedFolderPath.toLowerCase()}',
      type: type,
      folderName: folderName,
      folderPath: normalizedFolderPath,
      name: _stringFromJson(metadata, const <String>[
        'name',
        'title',
        'displayName',
      ], folderName),
      author: _stringFromJson(metadata, const <String>[
        'author',
        'creator',
        'by',
      ], 'ATLAS Resources'),
      cardDescription: _stringFromJson(metadata, const <String>[
        'cardDescription',
        'shortDescription',
        'summary',
        'teaser',
      ]),
      description: _stringFromJson(metadata, const <String>[
        'description',
        'detailDescription',
        'details',
        'body',
      ], _atlasModDefaultDescription(type)),
      version: _stringFromJson(metadata, const <String>[
        'version',
        'gameVersion',
        'fortniteVersion',
        'build',
      ]),
      tags: _stringListFromJson(
        metadata,
        const <String>['tags', 'labels', 'categories', 'badges'],
      ).where((tag) => tag.trim().isNotEmpty).map((tag) => tag.trim()).toList(),
      cardImage: primaryImage,
      images: images,
      media: media,
      sourceUrl: _stringFromJson(metadata, const <String>[
        'sourceUrl',
        'source',
        'repo',
        'repository',
        'url',
      ], _atlasResourcesTreeUrl(normalizedFolderPath)),
      dependencies: _stringListFromJson(metadata, const <String>[
        'dependencies',
        'requires',
        'dependsOn',
      ]),
      dataSlot: _stringFromJson(metadata, const <String>[
        'dataSlot',
        'dataManagementSlot',
        'patcherSlot',
        'dllRole',
        'slot',
      ]),
      files: files,
    );
  }

  Future<List<_AtlasModEntry>> _loadModsLibraryFromGitHubTree() async {
    final treeEntries = await _fetchAtlasResourceTreeEntries();
    final folderPaths = <String>{};
    for (final type in _AtlasModType.values) {
      final prefix = '${type.folderName}/';
      for (final entry in treeEntries) {
        final path = (entry['path'] ?? '').toString().replaceAll('\\', '/');
        if (!path.startsWith(prefix)) continue;
        final remainder = path.substring(prefix.length);
        final slashIndex = remainder.indexOf('/');
        if (slashIndex <= 0) continue;
        folderPaths.add('$prefix${remainder.substring(0, slashIndex)}');
      }
    }

    final mods = <_AtlasModEntry>[];
    for (final type in _AtlasModType.values) {
      final typePrefix = '${type.folderName}/';
      final typeFolders =
          folderPaths.where((path) => path.startsWith(typePrefix)).toList()
            ..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
      for (final folderPath in typeFolders) {
        final mod = await _parseAtlasModFolderFromTree(
          type,
          folderPath,
          treeEntries,
        );
        if (mod != null) mods.add(mod);
      }
    }
    _log('mods', 'Loaded ${mods.length} mods from ATLAS-Resources tree.');
    return mods;
  }

  Future<List<_AtlasModEntry>> _loadModsLibraryFromGitHubContents() async {
    final mods = <_AtlasModEntry>[];
    for (final type in _AtlasModType.values) {
      final entries = await _fetchAtlasResourceContents(type.folderName);
      for (final entry in entries) {
        if ((entry['type'] ?? '').toString().toLowerCase() != 'dir') {
          continue;
        }
        final mod = await _parseAtlasModFolder(type, entry);
        if (mod != null) mods.add(mod);
      }
    }
    _log('mods', 'Loaded ${mods.length} mods from ATLAS-Resources contents.');
    return mods;
  }

  Future<List<_AtlasModEntry>> _loadModsLibraryFromGitHub({
    Map<String, _AtlasModEntry> cachedModsById =
        const <String, _AtlasModEntry>{},
  }) async {
    late final List<_AtlasModEntry> mods;
    try {
      mods = await _loadModsLibraryFromGitHubTree();
    } catch (error) {
      _log('mods', 'GitHub tree load failed, trying contents API: $error');
      mods = await _loadModsLibraryFromGitHubContents();
    }
    return _refreshAtlasModLastUpdatedFromGitHub(mods, cachedModsById);
  }

  Map<String, _AtlasModEntry> _atlasModsById(List<_AtlasModEntry> mods) {
    return <String, _AtlasModEntry>{
      for (final mod in mods)
        if (mod.id.trim().isNotEmpty) mod.id: mod,
    };
  }

  List<_AtlasModEntry> _mergeAtlasModLastUpdatedCache(
    List<_AtlasModEntry> mods,
    Map<String, _AtlasModEntry> cachedModsById,
  ) {
    if (cachedModsById.isEmpty) return mods;
    var changed = false;
    final next = <_AtlasModEntry>[];
    for (final mod in mods) {
      if (mod.lastUpdatedEpochMs > 0) {
        next.add(mod);
        continue;
      }
      final cachedMs = cachedModsById[mod.id]?.lastUpdatedEpochMs ?? 0;
      if (cachedMs > 0) {
        changed = true;
        next.add(mod.copyWith(lastUpdatedEpochMs: cachedMs));
      } else {
        next.add(mod);
      }
    }
    return changed ? next : mods;
  }

  Future<List<_AtlasModEntry>> _refreshAtlasModLastUpdatedFromGitHub(
    List<_AtlasModEntry> mods,
    Map<String, _AtlasModEntry> cachedModsById,
  ) async {
    final refreshed = <_AtlasModEntry>[];
    var failures = 0;

    for (final mod in mods) {
      var lastUpdatedEpochMs = 0;
      try {
        lastUpdatedEpochMs = await _fetchAtlasResourceLastUpdatedEpochMs(
          mod.folderPath,
        );
      } catch (_) {
        failures++;
      }
      if (lastUpdatedEpochMs <= 0) {
        lastUpdatedEpochMs =
            cachedModsById[mod.id]?.lastUpdatedEpochMs ??
            mod.lastUpdatedEpochMs;
      }
      refreshed.add(
        lastUpdatedEpochMs > 0
            ? mod.copyWith(lastUpdatedEpochMs: lastUpdatedEpochMs)
            : mod,
      );
    }

    if (failures > 0) {
      _log(
        'mods',
        'Used cached update dates for $failures mod${failures == 1 ? '' : 's'}.',
      );
    }
    return refreshed;
  }

  Future<List<_AtlasModEntry>> _loadModsLibraryCache() async {
    if (!_storageReady || !await _modsLibraryCacheFile.exists()) {
      return const <_AtlasModEntry>[];
    }
    try {
      final raw = await _modsLibraryCacheFile.readAsString();
      final decoded = jsonDecode(raw);
      final modsRaw = decoded is Map ? decoded['mods'] : decoded;
      if (modsRaw is! List) return const <_AtlasModEntry>[];
      return modsRaw
          .whereType<Map>()
          .map((item) => _AtlasModEntry.fromJson(item.cast<String, dynamic>()))
          .where((mod) => mod.id.trim().isNotEmpty)
          .toList();
    } catch (error) {
      _log('mods', 'Failed to read mods library cache: $error');
      return const <_AtlasModEntry>[];
    }
  }

  Future<void> _saveModsLibraryCache(List<_AtlasModEntry> mods) async {
    if (!_storageReady) return;
    try {
      final payload = <String, dynamic>{
        'version': 1,
        'cachedAtEpochMs': DateTime.now().millisecondsSinceEpoch,
        'mods': mods.map((mod) => mod.toJson()).toList(),
      };
      final pretty = const JsonEncoder.withIndent('  ').convert(payload);
      await _modsLibraryCacheFile.writeAsString(pretty, flush: true);
    } catch (error) {
      _log('mods', 'Failed to write mods library cache: $error');
    }
  }

  Directory? _findLocalAtlasResourcesDirectory() {
    final seen = <String>{};
    final candidates = <Directory>[];

    void addCandidate(String path) {
      final normalized = _normalizePath(path);
      if (normalized.isEmpty || !seen.add(normalized)) return;
      candidates.add(Directory(path));
    }

    void addSiblingCandidates(Directory start) {
      var current = start.absolute;
      for (var depth = 0; depth < 8; depth++) {
        addCandidate(_joinPath([current.path, 'ATLAS-Resources']));
        final parent = current.parent;
        if (_normalizePath(parent.path) == _normalizePath(current.path)) break;
        addCandidate(_joinPath([parent.path, 'ATLAS-Resources']));
        current = parent;
      }
    }

    addSiblingCandidates(Directory.current);
    addSiblingCandidates(File(Platform.resolvedExecutable).parent);
    final userProfile = Platform.environment['USERPROFILE']?.trim() ?? '';
    if (userProfile.isNotEmpty) {
      addCandidate(
        _joinPath([
          userProfile,
          'OneDrive',
          'Documents',
          'GitHub',
          'ATLAS-Resources',
        ]),
      );
      addCandidate(
        _joinPath([userProfile, 'Documents', 'GitHub', 'ATLAS-Resources']),
      );
    }

    for (final candidate in candidates) {
      final paks = Directory(_joinPath([candidate.path, 'Paks']));
      final dlls = Directory(_joinPath([candidate.path, 'DLLs']));
      if (candidate.existsSync() && (paks.existsSync() || dlls.existsSync())) {
        return candidate;
      }
    }
    return null;
  }

  List<_AtlasModFile> _atlasModFilesFromLocalMetadata(
    Map<String, dynamic> metadata,
    Directory folder,
  ) {
    final raw =
        metadata['files'] ?? metadata['downloads'] ?? metadata['download'];
    final items = raw is List
        ? raw
        : raw == null
        ? const <dynamic>[]
        : <dynamic>[raw];
    final files = <_AtlasModFile>[];
    for (final item in items) {
      String name = '';
      String url = '';
      String relativePath = '';
      if (item is String) {
        relativePath = item.trim();
        final lower = relativePath.toLowerCase();
        url = lower.startsWith('http://') || lower.startsWith('https://')
            ? relativePath
            : _joinPath([folder.path, relativePath.replaceAll('/', '\\')]);
        name = _basename(relativePath);
      } else if (item is Map) {
        final map = item.cast<dynamic, dynamic>();
        relativePath = (map['path'] ?? map['file'] ?? map['relativePath'] ?? '')
            .toString()
            .trim();
        url =
            (map['url'] ??
                    map['downloadUrl'] ??
                    map['download_url'] ??
                    map['href'] ??
                    '')
                .toString()
                .trim();
        if (url.isEmpty && relativePath.isNotEmpty) {
          url = _joinPath([folder.path, relativePath.replaceAll('/', '\\')]);
        }
        name = (map['name'] ?? map['fileName'] ?? '').toString().trim();
        if (name.isEmpty) {
          name = _basename(relativePath.isEmpty ? url : relativePath);
        }
      }
      if (name.isEmpty || url.isEmpty) continue;
      files.add(
        _AtlasModFile(name: name, downloadUrl: url, relativePath: relativePath),
      );
    }
    return files;
  }

  List<_AtlasModMedia> _localAtlasResourceMediaFiles(Directory directory) {
    if (!directory.existsSync()) return const <_AtlasModMedia>[];
    final media = <_AtlasModMedia>[];
    for (final entity in directory.listSync(
      recursive: true,
      followLinks: false,
    )) {
      if (entity is! File) continue;
      final name = _basename(entity.path);
      if (!_isAtlasModMediaFile(name)) continue;
      media.add(
        _AtlasModMedia(
          url: entity.path,
          type: _atlasModMediaTypeForPath(name),
          label: name,
        ),
      );
    }
    return _dedupeAtlasModMedia(media);
  }

  Future<_AtlasModEntry?> _parseLocalAtlasModFolder(
    _AtlasModType type,
    Directory folder,
    Directory resourcesRoot,
  ) async {
    final folderName = _basename(folder.path);
    final folderPath = '${type.folderName}/$folderName';
    Map<String, dynamic> metadata = <String, dynamic>{};
    final metadataFile = File(_joinPath([folder.path, 'metadata.json']));
    if (await metadataFile.exists()) {
      try {
        final decoded = jsonDecode(await metadataFile.readAsString());
        if (decoded is Map<String, dynamic>) {
          metadata = decoded;
        } else if (decoded is Map) {
          metadata = decoded.cast<String, dynamic>();
        }
      } catch (error) {
        _log('mods', 'Failed to parse local metadata for $folderPath: $error');
      }
    }

    final directFiles = folder
        .listSync(followLinks: false)
        .whereType<File>()
        .where((file) => _isInstallableAtlasModFile(type, _basename(file.path)))
        .map(
          (file) => _AtlasModFile(
            name: _basename(file.path),
            downloadUrl: file.path,
            relativePath: _basename(file.path),
          ),
        )
        .toList();
    var files = _atlasModFilesFromLocalMetadata(metadata, folder);
    if (files.isEmpty) files = directFiles;

    final directMedia = folder
        .listSync(followLinks: false)
        .whereType<File>()
        .where((file) => _isAtlasModMediaFile(_basename(file.path)))
        .map(
          (file) => _AtlasModMedia(
            url: file.path,
            type: _atlasModMediaTypeForPath(_basename(file.path)),
            label: _basename(file.path),
          ),
        )
        .toList();
    final contentMedia = <_AtlasModMedia>[];
    for (final name in const <String>['Content', 'Media', 'Gallery']) {
      contentMedia.addAll(
        _localAtlasResourceMediaFiles(
          Directory(_joinPath([folder.path, name])),
        ),
      );
    }
    String resolveLocalMedia(String value) {
      final trimmed = value.trim();
      final lower = trimmed.toLowerCase();
      if (lower.startsWith('http://') || lower.startsWith('https://')) {
        return trimmed;
      }
      return _joinPath([folder.path, trimmed.replaceAll('/', '\\')]);
    }

    final metadataMedia = _atlasModMediaFromMetadata(metadata, const <String>[
      'media',
      'content',
      'gallery',
      'screenshots',
      'pictures',
      'images',
      'videos',
    ], resolveLocalMedia);
    final cardImage = _stringFromJson(metadata, const <String>[
      'cardImage',
      'thumbnail',
      'image',
      'picture',
      'cover',
      'preview',
    ]);
    final resolvedCardImage =
        cardImage.isNotEmpty && _isAtlasModImageFile(cardImage)
        ? resolveLocalMedia(cardImage)
        : '';
    final media = _dedupeAtlasModMedia(<_AtlasModMedia>[
      if (resolvedCardImage.isNotEmpty)
        _AtlasModMedia(
          url: resolvedCardImage,
          type: _AtlasModMediaType.image,
          label: _basename(cardImage),
        ),
      ...metadataMedia,
      ...directMedia,
      ...contentMedia,
    ]);
    final images = media
        .where((item) => item.type == _AtlasModMediaType.image)
        .map((item) => item.url)
        .toList();
    final primaryImage = resolvedCardImage.isNotEmpty
        ? resolvedCardImage
        : images.isNotEmpty
        ? images.first
        : '';

    return _AtlasModEntry(
      id: '${type.name}:${folderPath.toLowerCase()}',
      type: type,
      folderName: folderName,
      folderPath: folderPath,
      name: _stringFromJson(metadata, const <String>[
        'name',
        'title',
        'displayName',
      ], folderName),
      author: _stringFromJson(metadata, const <String>[
        'author',
        'creator',
        'by',
      ], 'ATLAS Resources'),
      cardDescription: _stringFromJson(metadata, const <String>[
        'cardDescription',
        'shortDescription',
        'summary',
        'teaser',
      ]),
      description: _stringFromJson(metadata, const <String>[
        'description',
        'detailDescription',
        'details',
        'body',
      ], _atlasModDefaultDescription(type)),
      version: _stringFromJson(metadata, const <String>[
        'version',
        'gameVersion',
        'fortniteVersion',
        'build',
      ]),
      tags: _stringListFromJson(
        metadata,
        const <String>['tags', 'labels', 'categories', 'badges'],
      ).where((tag) => tag.trim().isNotEmpty).map((tag) => tag.trim()).toList(),
      cardImage: primaryImage,
      images: images,
      media: media,
      sourceUrl: resourcesRoot.path,
      dependencies: _stringListFromJson(metadata, const <String>[
        'dependencies',
        'requires',
        'dependsOn',
      ]),
      dataSlot: _stringFromJson(metadata, const <String>[
        'dataSlot',
        'dataManagementSlot',
        'patcherSlot',
        'dllRole',
        'slot',
      ]),
      files: files,
    );
  }

  Future<List<_AtlasModEntry>> _loadModsLibraryFromLocalResources() async {
    final resourcesRoot = _findLocalAtlasResourcesDirectory();
    if (resourcesRoot == null) return const <_AtlasModEntry>[];
    final mods = <_AtlasModEntry>[];
    for (final type in _AtlasModType.values) {
      final typeDir = Directory(
        _joinPath([resourcesRoot.path, type.folderName]),
      );
      if (!await typeDir.exists()) continue;
      final folders = typeDir
          .listSync(followLinks: false)
          .whereType<Directory>();
      for (final entry in folders) {
        final mod = await _parseLocalAtlasModFolder(type, entry, resourcesRoot);
        if (mod != null) mods.add(mod);
      }
    }
    _log('mods', 'Loaded ${mods.length} mods from local ATLAS-Resources.');
    return mods;
  }

  void _sortAtlasMods(List<_AtlasModEntry> mods) {
    mods.sort((a, b) {
      final typeCompare = a.type.index.compareTo(b.type.index);
      if (typeCompare != 0) return typeCompare;
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });
  }

  Future<void> _loadModsLibrary({
    bool forceRefresh = false,
    bool silentRefreshToast = false,
  }) {
    if (_modsRefreshInFlight != null) return _modsRefreshInFlight!;
    if (!forceRefresh && _modsLibrary.isNotEmpty) return Future<void>.value();
    final hadLoadedMods = _modsLibrary.isNotEmpty;

    final future = () async {
      if (mounted) {
        setState(() {
          _modsLoading = true;
          _modsLoadError = '';
        });
      } else {
        _modsLoading = true;
        _modsLoadError = '';
      }

      final cachedMods = await _loadModsLibraryCache();
      final cachedModsById = _atlasModsById(cachedMods);

      try {
        final mods = await _loadModsLibraryFromGitHub(
          cachedModsById: cachedModsById,
        );
        _sortAtlasMods(mods);
        await _saveModsLibraryCache(mods);
        if (mounted) {
          setState(() => _modsLibrary = mods);
        } else {
          _modsLibrary = mods;
        }
        await _reconcileDetectedInstalledMods(mods);
        if (forceRefresh && !silentRefreshToast && mounted) {
          _toast('Refreshed ${mods.length} Mods');
        }
      } catch (error) {
        _log('mods', 'Failed to Load Mods Library: $error');
        var fallbackMods = await _loadModsLibraryFromLocalResources();
        var fallbackLabel = 'local ATLAS-Resources';
        if (fallbackMods.isNotEmpty) {
          fallbackMods = _mergeAtlasModLastUpdatedCache(
            fallbackMods,
            cachedModsById,
          );
        }
        if (fallbackMods.isEmpty) {
          fallbackMods = cachedMods;
          fallbackLabel = 'cached mods';
        }
        if (fallbackMods.isNotEmpty) {
          _sortAtlasMods(fallbackMods);
          if (mounted) {
            setState(() {
              _modsLibrary = fallbackMods;
              _modsLoadError = '';
            });
            if (!silentRefreshToast && (forceRefresh || !hadLoadedMods)) {
              _toast('Loaded ${fallbackMods.length} $fallbackLabel');
            }
          } else {
            _modsLibrary = fallbackMods;
            _modsLoadError = '';
          }
          await _reconcileDetectedInstalledMods(fallbackMods);
        } else if (hadLoadedMods) {
          _modsLoadError = '';
          if (mounted) _toast('Unable to Refresh Mods. Keeping Current List.');
        } else {
          _modsLoadError = 'Unable to load ATLAS Resources Mods.';
        }
        if (mounted) setState(() {});
      } finally {
        _modsLoading = false;
        if (mounted) setState(() {});
      }
    }();

    _modsRefreshInFlight = future.whenComplete(
      () => _modsRefreshInFlight = null,
    );
    return _modsRefreshInFlight!;
  }

  Future<void> _loadInstalledMods() async {
    if (!_storageReady) return;
    try {
      if (!await _installedModsFile.exists()) {
        _installedModsById = <String, _InstalledAtlasMod>{};
        return;
      }
      final raw = await _installedModsFile.readAsString();
      final decoded = jsonDecode(raw);
      final modsRaw = decoded is Map ? decoded['mods'] : decoded;
      if (modsRaw is! List) {
        _installedModsById = <String, _InstalledAtlasMod>{};
        return;
      }
      final next = <String, _InstalledAtlasMod>{};
      for (final item in modsRaw) {
        if (item is Map<String, dynamic>) {
          final mod = _InstalledAtlasMod.fromJson(item);
          if (mod.id.isNotEmpty) next[mod.id] = mod;
        } else if (item is Map) {
          final mod = _InstalledAtlasMod.fromJson(item.cast<String, dynamic>());
          if (mod.id.isNotEmpty) next[mod.id] = mod;
        }
      }
      _installedModsById = next;
    } catch (error) {
      _installedModsById = <String, _InstalledAtlasMod>{};
      _log('mods', 'Failed to load installed mods: $error');
    }
  }

  Future<void> _saveInstalledMods() async {
    if (!_storageReady) return;
    final mods = _installedModsById.values.toList()
      ..sort((a, b) => b.installedAtEpochMs.compareTo(a.installedAtEpochMs));
    final payload = <String, dynamic>{
      'version': 1,
      'mods': mods.map((mod) => mod.toJson()).toList(),
    };
    final pretty = const JsonEncoder.withIndent('  ').convert(payload);
    await _installedModsFile.writeAsString(pretty, flush: true);
  }

  String _normalizedVersionToken(String value) {
    return value.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '');
  }

  bool _versionEntryMatchesMod(VersionEntry entry, String modVersion) {
    final modToken = _normalizedVersionToken(modVersion);
    if (modToken.isEmpty) return false;
    final entryVersion = _normalizedVersionToken(entry.gameVersion);
    final entryName = _normalizedVersionToken(entry.name);
    return entryVersion == modToken ||
        entryName == modToken ||
        entryVersion.contains(modToken) ||
        entryName.contains(modToken);
  }

  /// Splits a single compatibility clause like `10.00-10.40` into its inclusive
  /// `[low, high]` bounds. Returns `null` when the clause is a single version
  /// (no dash) so callers fall back to exact/token matching.
  List<String>? _modVersionRangeBounds(String clause) {
    final dash = clause.indexOf('-');
    if (dash <= 0 || dash >= clause.length - 1) return null;
    final low = clause.substring(0, dash).trim();
    final high = clause.substring(dash + 1).trim();
    if (low.isEmpty || high.isEmpty) return null;
    return _compareVersionStrings(low, high) > 0
        ? <String>[high, low]
        : <String>[low, high];
  }

  /// A comparable season value for range matching, e.g. `10.40` -> `100040`.
  ///
  /// Only the first `major.minor` is used so trailing noise such as a build's
  /// changelist (`10.40-CL-14550713`) does not skew the comparison. A single
  /// digit minor follows the launcher's Fortnite convention (`10.4` == `10.40`).
  int? _modSeasonValue(String version) {
    final pair = RegExp(r'(\d+)\.(\d+)').firstMatch(version);
    if (pair != null) {
      final major = int.parse(pair.group(1)!);
      final minorStr = pair.group(2)!;
      final minor = minorStr.length == 1
          ? int.parse(minorStr) * 10
          : int.parse(minorStr);
      return major * 10000 + minor;
    }
    final single = RegExp(r'\d+').firstMatch(version);
    if (single == null) return null;
    return int.parse(single.group(0)!) * 10000;
  }

  /// Whether a build matches a mod's compatibility tag.
  ///
  /// The tag is a comma separated list of clauses. A clause with a dash
  /// (`10.00-10.40`) matches every version in that inclusive range; a plain
  /// clause (`10.00`) matches only that exact version. So `10.00, 10.40` covers
  /// just those two builds while `10.00-10.40` also covers everything between.
  bool _modSpecMatchesVersionEntry(String spec, VersionEntry entry) {
    final trimmedSpec = spec.trim();
    if (trimmedSpec.isEmpty) return false;
    for (final rawClause in trimmedSpec.split(',')) {
      final clause = rawClause.trim();
      if (clause.isEmpty) continue;
      final bounds = _modVersionRangeBounds(clause);
      if (bounds != null) {
        // Compare at season granularity so changelist digits in the build's
        // version don't push it outside the range.
        final entryValue = _modSeasonValue(entry.gameVersion.trim());
        final a = _modSeasonValue(bounds[0]);
        final b = _modSeasonValue(bounds[1]);
        if (entryValue != null && a != null && b != null) {
          final low = a < b ? a : b;
          final high = a < b ? b : a;
          if (entryValue >= low && entryValue <= high) return true;
        }
      } else if (_versionEntryMatchesMod(entry, clause)) {
        return true;
      }
    }
    return false;
  }

  /// Imported builds a build-targeted (pak/exe) mod can install to. An empty
  /// version spec falls back to the currently selected build (legacy behaviour).
  List<VersionEntry> _compatibleVersionsForMod(_AtlasModEntry mod) {
    final spec = mod.version.trim();
    if (spec.isEmpty) {
      final selected = _settings.selectedVersion;
      return selected == null ? <VersionEntry>[] : <VersionEntry>[selected];
    }
    return _settings.versions
        .where((version) => _modSpecMatchesVersionEntry(spec, version))
        .toList();
  }

  String _pakModTargetDirectory(VersionEntry version) {
    return _joinPath([version.location, 'FortniteGame', 'Content', 'Paks']);
  }

  /// Patched EXEs drop into the build's Win64 binaries folder, replacing the
  /// stock executable (e.g. FortniteClient-Win64-Shipping.exe).
  String _exeModTargetDirectory(VersionEntry version) {
    return _joinPath([version.location, 'FortniteGame', 'Binaries', 'Win64']);
  }

  /// Install directory for a build-targeted mod's files in a specific build.
  String _buildModTargetDirectory(_AtlasModEntry mod, VersionEntry version) {
    return mod.type == _AtlasModType.exe
        ? _exeModTargetDirectory(version)
        : _pakModTargetDirectory(version);
  }

  // A patched EXE renames the file it replaces to this suffix so it can be
  // restored verbatim on uninstall.
  static const String _exeBackupSuffix = '.atlas-original';
  // Sidecar marker written next to an installed patched EXE. A patched EXE is
  // byte-identically named to the stock executable it replaces, so file
  // presence alone can't tell whether (or which) patch is installed. The marker
  // holds the owning mod's id and is the source of truth for EXE install state.
  static const String _exeMarkerSuffix = '.atlas-mod';

  String _dllModTargetDirectory(_AtlasModEntry _) {
    return _joinPath([_dataDir.path, 'dlls']);
  }

  /// Backs up the stock executable at [destination] before a patched EXE
  /// overwrites it. Only the first install creates the backup; later installs /
  /// updates to the same slot keep the original true backup intact.
  Future<void> _backupOriginalExe(File destination) async {
    if (!await destination.exists()) return;
    final backup = File('${destination.path}$_exeBackupSuffix');
    if (await backup.exists()) return; // true original already preserved
    await destination.rename(backup.path);
  }

  /// Records which mod owns the patched EXE at [exePath] so install state (and
  /// which specific patch it is) survives restarts and can't be confused with
  /// the identically-named stock executable.
  Future<void> _writeExeMarker(String exePath, String modId) async {
    try {
      await File('$exePath$_exeMarkerSuffix').writeAsString(modId);
    } catch (error) {
      _log('mods', 'Failed to write exe marker for $exePath: $error');
    }
  }

  /// Whether the patched EXE at [exePath] is present and owned by [modId] (its
  /// marker exists and names this mod). Synchronous so it can drive UI state.
  bool _exeSlotOwnedBy(String exePath, String modId) {
    if (!File(exePath).existsSync()) return false;
    final marker = File('$exePath$_exeMarkerSuffix');
    if (!marker.existsSync()) return false;
    try {
      return marker.readAsStringSync().trim() == modId;
    } catch (_) {
      return false;
    }
  }

  /// Removes a patched EXE (and its marker) and restores the stock executable it
  /// replaced (if a backup exists). Used on uninstall and rollback so the build
  /// returns to its prior state.
  Future<void> _restorePatchedExe(String path) async {
    final file = File(path);
    final backup = File('$path$_exeBackupSuffix');
    final marker = File('$path$_exeMarkerSuffix');
    try {
      if (await marker.exists()) await marker.delete();
    } catch (error) {
      _log('mods', 'Failed to remove exe marker for $path: $error');
    }
    try {
      if (await file.exists()) await file.delete();
    } catch (error) {
      _log('mods', 'Failed to remove patched exe $path: $error');
    }
    try {
      if (await backup.exists()) await backup.rename(path);
    } catch (error) {
      _log('mods', 'Failed to restore original exe for $path: $error');
    }
  }

  /// Repairs state left by a download interrupted mid-install (launcher closed,
  /// crash, power loss). Runs once on startup. Two cases matter:
  ///  - A patched EXE install renames the stock executable to
  ///    `<name>$_exeBackupSuffix` before downloading. If the real executable is
  ///    now missing, the patched download never finished — restore the backup so
  ///    the build can still launch.
  ///  - Orphaned `<file>.part` temp files from any interrupted download.
  Future<void> _recoverInterruptedModInstalls() async {
    Future<void> sweep(String dirPath, {required bool restoreExe}) async {
      final dir = Directory(dirPath);
      if (!dir.existsSync()) return;
      List<FileSystemEntity> entries;
      try {
        entries = dir.listSync(followLinks: false);
      } catch (_) {
        return;
      }
      for (final entity in entries) {
        if (entity is! File) continue;
        final path = entity.path;
        final lower = path.toLowerCase();
        // Drop leftover partial downloads.
        if (lower.endsWith('.part')) {
          try {
            await entity.delete();
            _log('mods', 'Removed orphaned partial download: $path');
          } catch (_) {}
          continue;
        }
        // Restore a stock executable whose patch never finished downloading.
        if (restoreExe && lower.endsWith(_exeBackupSuffix)) {
          final original = path.substring(
            0,
            path.length - _exeBackupSuffix.length,
          );
          if (!File(original).existsSync()) {
            try {
              final marker = File('$original$_exeMarkerSuffix');
              if (await marker.exists()) await marker.delete();
              await entity.rename(original);
              _log(
                'mods',
                'Recovered interrupted EXE install: restored $original',
              );
            } catch (error) {
              _log('mods', 'Failed to recover EXE backup $path: $error');
            }
          }
        }
      }
    }

    for (final version in _settings.versions) {
      await sweep(_exeModTargetDirectory(version), restoreExe: true);
      await sweep(_pakModTargetDirectory(version), restoreExe: false);
    }
    // DLL mods share the same managed user DLL folder as launcher DLL assets.
    await sweep(_joinPath([_dataDir.path, 'dlls']), restoreExe: false);
  }

  List<String> _atlasModFilePathsInDirectory(
    _AtlasModEntry mod,
    String directory,
  ) {
    if (mod.files.isEmpty || directory.trim().isEmpty) return const <String>[];
    return mod.files
        .map((file) => _joinPath([directory, _safeFileName(file.name)]))
        .toList();
  }

  bool _installedAtlasModFilesPresent(_InstalledAtlasMod installed) {
    if (installed.installedFilePaths.isEmpty) return false;
    // Patched EXEs share the stock executable's name, so "file exists" isn't
    // enough — the slot must still be marked as owned by this mod.
    if (installed.type == _AtlasModType.exe) {
      return installed.installedFilePaths.every(
        (path) => _exeSlotOwnedBy(path, installed.id),
      );
    }
    return installed.installedFilePaths.every(
      (path) => File(path).existsSync(),
    );
  }

  _InstalledAtlasMod? _detectExistingAtlasModInstall(_AtlasModEntry mod) {
    if (mod.files.isEmpty) return null;
    final presentPaths = <String>[];
    final presentVersionIds = <String>[];
    if (mod.type == _AtlasModType.exe) {
      // A patched EXE is named exactly like the stock executable it replaces, so
      // we detect it by the marker we drop beside it — present and naming this
      // mod means this specific patch is installed in that build.
      for (final version in _compatibleVersionsForMod(mod)) {
        final paths = _atlasModFilePathsInDirectory(
          mod,
          _exeModTargetDirectory(version),
        );
        if (paths.isNotEmpty &&
            paths.every((path) => _exeSlotOwnedBy(path, mod.id))) {
          presentPaths.addAll(paths);
          presentVersionIds.add(version.id);
        }
      }
      if (presentPaths.isEmpty) return null;
      return _InstalledAtlasMod(
        id: mod.id,
        type: mod.type,
        name: mod.name,
        version: mod.version,
        targetVersionId: presentVersionIds.first,
        targetVersionIds: presentVersionIds,
        installedFilePaths: presentPaths,
        installedAtEpochMs: DateTime.now().millisecondsSinceEpoch,
        sourceLastUpdatedEpochMs: mod.lastUpdatedEpochMs,
        filesFingerprint: _atlasModFilesFingerprint(mod),
        dataSlot: mod.dataSlot,
      );
    }
    if (mod.type == _AtlasModType.dll) {
      // Flat DLL-folder installs are tracked by saved install records. Do not
      // auto-detect by filename here; _dataDir/dlls also contains bundled DLLs.
      return null;
    } else {
      // A pak mod can be installed to several compatible builds at once; treat
      // it as installed when its files are present in any of them.
      for (final version in _compatibleVersionsForMod(mod)) {
        final paths = _atlasModFilePathsInDirectory(
          mod,
          _pakModTargetDirectory(version),
        );
        if (paths.isNotEmpty &&
            paths.every((path) => File(path).existsSync())) {
          presentPaths.addAll(paths);
          presentVersionIds.add(version.id);
        }
      }
      if (presentPaths.isEmpty) return null;
    }
    return _InstalledAtlasMod(
      id: mod.id,
      type: mod.type,
      name: mod.name,
      version: mod.version,
      targetVersionId: presentVersionIds.isEmpty ? '' : presentVersionIds.first,
      targetVersionIds: presentVersionIds,
      installedFilePaths: presentPaths,
      installedAtEpochMs: DateTime.now().millisecondsSinceEpoch,
      sourceLastUpdatedEpochMs: mod.lastUpdatedEpochMs,
      filesFingerprint: _atlasModFilesFingerprint(mod),
      dataSlot: mod.dataSlot,
    );
  }

  bool _isAtlasModInstalled(_AtlasModEntry mod) {
    final installed = _installedModsById[mod.id];
    if (installed != null && _installedAtlasModFilesPresent(installed)) {
      return true;
    }
    return _detectExistingAtlasModInstall(mod) != null;
  }

  Future<void> _reconcileDetectedInstalledMods([
    List<_AtlasModEntry>? sourceMods,
  ]) async {
    final mods = sourceMods ?? _modsLibrary;
    var changed = false;
    for (final mod in mods) {
      final existing = _installedModsById[mod.id];
      if (existing != null && _installedAtlasModFilesPresent(existing)) {
        // Baseline the update markers for installs that predate update tracking
        // (or were installed before the catalog data was known) so they don't
        // instantly read as "update available".
        var baselined = existing;
        if (baselined.sourceLastUpdatedEpochMs == 0 &&
            mod.lastUpdatedEpochMs > 0) {
          baselined = baselined.copyWith(
            sourceLastUpdatedEpochMs: mod.lastUpdatedEpochMs,
          );
        }
        if (baselined.filesFingerprint.isEmpty) {
          final fingerprint = _atlasModFilesFingerprint(mod);
          if (fingerprint.isNotEmpty) {
            baselined = baselined.copyWith(filesFingerprint: fingerprint);
          }
        }
        if (!identical(baselined, existing)) {
          _installedModsById[mod.id] = baselined;
          changed = true;
        }
        continue;
      }
      final detected = _detectExistingAtlasModInstall(mod);
      if (detected == null) continue;
      _installedModsById[mod.id] = detected;
      changed = true;
    }
    if (!changed) return;
    await _saveInstalledMods();
    if (mounted) setState(() {});
  }

  /// Content fingerprint of a mod's installable files: a sorted `name:sha`
  /// list. Returns empty when any file's SHA is unknown so callers can fall
  /// back to the commit-time signal.
  String _atlasModFilesFingerprint(_AtlasModEntry mod) {
    if (mod.files.isEmpty) return '';
    final parts = <String>[];
    for (final file in mod.files) {
      final sha = file.sha.trim().toLowerCase();
      if (sha.isEmpty) return '';
      parts.add('${_safeFileName(file.name).toLowerCase()}:$sha');
    }
    parts.sort();
    return parts.join('|');
  }

  /// Whether the catalog has a newer copy of an installed mod. Compares the
  /// installable files' content fingerprint so it only fires when the actual
  /// game files change (added, removed, renamed, or replaced) — never for
  /// metadata or screenshot edits. Falls back to the folder commit time only
  /// when file SHAs aren't available (e.g. local resources / legacy records).
  bool _atlasModUpdateAvailable(_AtlasModEntry catalogMod) {
    final installed = _installedModsById[catalogMod.id];
    if (installed == null || !_installedAtlasModFilesPresent(installed)) {
      return false;
    }
    final catalogFingerprint = _atlasModFilesFingerprint(catalogMod);
    final installedFingerprint = installed.filesFingerprint.trim();
    if (catalogFingerprint.isNotEmpty && installedFingerprint.isNotEmpty) {
      return catalogFingerprint != installedFingerprint;
    }
    final catalogMs = catalogMod.lastUpdatedEpochMs;
    final installedMs = installed.sourceLastUpdatedEpochMs;
    return catalogMs > 0 && installedMs > 0 && catalogMs > installedMs;
  }

  bool get _hasAtlasModUpdates => _modsLibrary.any(_atlasModUpdateAvailable);

  String? _atlasModTargetPhrase({
    required _AtlasModType type,
    Iterable<String> targetVersionIds = const <String>[],
    Iterable<VersionEntry> targetBuilds = const <VersionEntry>[],
  }) {
    if (type == _AtlasModType.dll) return 'the DLL library';

    final builds = targetBuilds.toList();
    final ids = targetVersionIds
        .map((id) => id.trim())
        .where((id) => id.isNotEmpty)
        .toList();
    final count = builds.isNotEmpty ? builds.length : ids.length;
    if (count > 1) return '$count builds';
    if (count == 1) {
      final version = builds.isNotEmpty
          ? builds.single
          : _findVersionById(ids.single);
      final versionLabel = _formatLibraryVersionLabel(
        version?.gameVersion ?? '',
      );
      return versionLabel == '?' ? '1 build' : versionLabel;
    }
    return null;
  }

  String _atlasModActionToast({
    required String action,
    required String modName,
    required String preposition,
    required _AtlasModType type,
    Iterable<String> targetVersionIds = const <String>[],
    Iterable<VersionEntry> targetBuilds = const <VersionEntry>[],
  }) {
    final target = _atlasModTargetPhrase(
      type: type,
      targetVersionIds: targetVersionIds,
      targetBuilds: targetBuilds,
    );
    if (target == null) return '$action "$modName"';
    return '$action "$modName" $preposition $target';
  }

  String _atlasModAlreadyInstalledToast(_InstalledAtlasMod installed) {
    final target = _atlasModTargetPhrase(
      type: installed.type,
      targetVersionIds: installed.targetVersionIds,
    );
    if (target == null) return '${installed.name} is already installed';
    final preposition = installed.type == _AtlasModType.dll ? 'in' : 'for';
    return '${installed.name} is already installed $preposition $target';
  }

  /// Runs a single mod download operation (install/update) under a global lock
  /// so only one can run at a time. A second attempt while one is in flight is
  /// rejected with a toast — the user can still close the details dialog and
  /// browse other mods while the current download finishes.
  bool _isModDownloadLockedVersion(String versionId) {
    final id = versionId.trim();
    return _atlasModBusy &&
        id.isNotEmpty &&
        _modInstallTargetVersionIds.contains(id);
  }

  bool _hasModDownloadLockedVersions() {
    if (!_atlasModBusy || _modInstallTargetVersionIds.isEmpty) return false;
    return _settings.versions.any(
      (version) => _modInstallTargetVersionIds.contains(version.id),
    );
  }

  void _setModInstallTargetVersionIds(Iterable<String> versionIds) {
    final next = versionIds
        .map((id) => id.trim())
        .where((id) => id.isNotEmpty)
        .toSet();
    if (mounted) {
      setState(() => _modInstallTargetVersionIds = next);
    } else {
      _modInstallTargetVersionIds = next;
    }
  }

  bool _blockModDownloadForRunningTargets(Iterable<String> versionIds) {
    final running = versionIds
        .map(_findVersionById)
        .whereType<VersionEntry>()
        .where((version) => _isVersionRunning(version.id))
        .toList();
    if (running.isEmpty) return false;

    final name = running.first.name.trim().isEmpty
        ? _formatLibraryVersionLabel(running.first.gameVersion)
        : running.first.name.trim();
    _toast(
      running.length == 1
          ? 'Close $name before downloading mods for it'
          : 'Close running builds before downloading mods for them',
    );
    return true;
  }

  Future<void> _runExclusiveModOp(Future<void> Function() op) async {
    if (_atlasModBusy) {
      _toast('Finish the current download before starting another');
      return;
    }
    if (mounted) {
      setState(() => _atlasModBusy = true);
    } else {
      _atlasModBusy = true;
    }
    try {
      await op();
    } finally {
      if (mounted) {
        setState(() {
          _atlasModBusy = false;
          _modInstallTargetVersionIds = <String>{};
        });
      } else {
        _atlasModBusy = false;
        _modInstallTargetVersionIds = <String>{};
      }
    }
  }

  /// Resolves a mod's metadata dependency references against the loaded catalog.
  /// Each reference can be a mod id, a folder path ("EXEs/27.11"), or a display
  /// name (case-insensitive). Unresolvable references are skipped.
  List<_AtlasModEntry> _resolveModDependencies(_AtlasModEntry mod) {
    if (mod.dependencies.isEmpty) return const <_AtlasModEntry>[];
    final resolved = <_AtlasModEntry>[];
    final seen = <String>{};
    for (final rawRef in mod.dependencies) {
      final ref = rawRef.trim();
      if (ref.isEmpty) continue;
      final lower = ref.toLowerCase().replaceAll('\\', '/');
      _AtlasModEntry? match;
      for (final candidate in _modsLibrary) {
        if (candidate.id == mod.id) continue;
        final id = candidate.id.toLowerCase();
        final folderPath = candidate.folderPath.toLowerCase().replaceAll(
          '\\',
          '/',
        );
        final name = candidate.name.trim().toLowerCase();
        if (id == lower || folderPath == lower || name == lower) {
          match = candidate;
          break;
        }
      }
      if (match != null && seen.add(match.id)) resolved.add(match);
    }
    return resolved;
  }

  /// Asks the user to install a mod's missing dependencies before continuing.
  /// Returns true if the user chose to proceed.
  Future<bool> _promptInstallDependencies(
    _AtlasModEntry mod,
    List<_AtlasModEntry> missing,
  ) async {
    final result = await showGeneralDialog<bool>(
      context: context,
      barrierDismissible: true,
      barrierLabel: MaterialLocalizations.of(context).modalBarrierDismissLabel,
      barrierColor: Colors.transparent,
      transitionDuration: const Duration(milliseconds: 220),
      pageBuilder: (dialogContext, animation, secondaryAnimation) {
        final secondary = Theme.of(dialogContext).colorScheme.secondary;
        return SafeArea(
          child: Center(
            child: Material(
              type: MaterialType.transparency,
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 460),
                child: Container(
                  decoration: BoxDecoration(
                    color: _dialogSurfaceColor(dialogContext),
                    borderRadius: BorderRadius.circular(24),
                    border: Border.all(color: _onSurface(dialogContext, 0.1)),
                    boxShadow: [
                      BoxShadow(
                        color: _dialogShadowColor(dialogContext),
                        blurRadius: 30,
                        offset: const Offset(0, 16),
                      ),
                    ],
                  ),
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(22, 20, 22, 16),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Dependency Required',
                          style: TextStyle(
                            fontSize: 22,
                            fontWeight: FontWeight.w800,
                            color: _onSurface(dialogContext, 0.96),
                          ),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          missing.length > 1
                              ? '"${mod.name}" needs to have the following dependencies:'
                              : '"${mod.name}" needs to have the following dependency:',
                          style: TextStyle(
                            color: _onSurface(dialogContext, 0.84),
                            height: 1.35,
                          ),
                        ),
                        const SizedBox(height: 14),
                        for (final dep in missing)
                          Padding(
                            padding: const EdgeInsets.only(bottom: 8),
                            child: Row(
                              children: [
                                Icon(
                                  Icons.link_rounded,
                                  size: 18,
                                  color: secondary.withValues(alpha: 0.9),
                                ),
                                const SizedBox(width: 10),
                                Expanded(
                                  child: Text(
                                    dep.name,
                                    style: TextStyle(
                                      fontWeight: FontWeight.w700,
                                      color: _onSurface(dialogContext, 0.92),
                                    ),
                                  ),
                                ),
                                if (dep.version.trim().isNotEmpty)
                                  Text(
                                    dep.version.trim(),
                                    style: TextStyle(
                                      color: _onSurface(dialogContext, 0.6),
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                              ],
                            ),
                          ),
                        const SizedBox(height: 10),
                        Row(
                          children: [
                            _dialogCancelButton(
                              dialogContext,
                              onPressed: () =>
                                  Navigator.of(dialogContext).pop(false),
                            ),
                            const Spacer(),
                            FilledButton.icon(
                              onPressed: () =>
                                  Navigator.of(dialogContext).pop(true),
                              style: FilledButton.styleFrom(
                                backgroundColor: secondary,
                                foregroundColor: Colors.white,
                              ),
                              icon: const Icon(Icons.download_rounded),
                              label: Text(
                                missing.length > 1
                                    ? 'Install ${missing.length} & Continue'
                                    : 'Install & Continue',
                              ),
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
        );
      },
      transitionBuilder: _dialogPopupTransition,
    );
    return result ?? false;
  }

  /// Drops any other installed EXE-mod record that occupies [destinationPath],
  /// keeping the "one patched EXE per slot" invariant when a different patched
  /// EXE is installed over an existing one. The original backup is preserved.
  void _forgetConflictingExeInstall(
    String destinationPath,
    String exceptModId,
  ) {
    final conflicting = _installedModsById.entries
        .where(
          (entry) =>
              entry.key != exceptModId &&
              entry.value.type == _AtlasModType.exe &&
              entry.value.installedFilePaths.contains(destinationPath),
        )
        .map((entry) => entry.key)
        .toList();
    for (final id in conflicting) {
      _installedModsById.remove(id);
    }
  }

  Future<void> _installAtlasMod(
    _AtlasModEntry mod, {
    bool resolveDependencies = true,
    Set<String> dependencyChain = const <String>{},
  }) async {
    final detected = _detectExistingAtlasModInstall(mod);
    final savedInstall = _installedModsById[mod.id];
    if ((savedInstall != null &&
            _installedAtlasModFilesPresent(savedInstall)) ||
        detected != null) {
      if (detected != null &&
          (savedInstall == null ||
              !_installedAtlasModFilesPresent(savedInstall))) {
        _installedModsById[mod.id] = detected;
        await _saveInstalledMods();
        if (mounted) setState(() {});
      }
      _toast(_atlasModAlreadyInstalledToast(detected ?? savedInstall!));
      return;
    }

    // Dependencies: prompt for and install any required mods first, then come
    // back to install the mod the user originally chose. The dependency chain
    // guards against cycles (A requires B requires A).
    if (resolveDependencies) {
      final missing = _resolveModDependencies(mod)
          .where(
            (dep) =>
                !dependencyChain.contains(dep.id) && !_isAtlasModInstalled(dep),
          )
          .toList();
      if (missing.isNotEmpty) {
        final proceed = await _promptInstallDependencies(mod, missing);
        if (!proceed) return;
        final nextChain = <String>{...dependencyChain, mod.id};
        for (final dep in missing) {
          await _installAtlasMod(
            dep,
            resolveDependencies: true,
            dependencyChain: nextChain,
          );
          if (!_isAtlasModInstalled(dep)) {
            _toast('${mod.name} needs "${dep.name}" installed first');
            return;
          }
        }
      }
    }

    if (mod.files.isEmpty) {
      _toast('${mod.name} has no downloadable files');
      return;
    }

    // Resolve install destinations. DLL mods go to the shared injector library;
    // build-targeted mods (paks, patched EXEs) install into the matching
    // imported build. When the mod is compatible with more than one of the
    // user's builds we ask which to use; a single match installs straight away.
    final targetDirectories = <String>[];
    final targetVersionIds = <String>[];
    if (mod.type.isBuildTargeted) {
      final compatible = _compatibleVersionsForMod(mod);
      if (compatible.isEmpty) {
        final spec = mod.version.trim();
        _toast(
          spec.isEmpty
              ? 'Import a build before installing ${mod.name}'
              : 'No imported build matches $spec for ${mod.name}',
        );
        return;
      }
      final List<VersionEntry> selected;
      if (compatible.length == 1) {
        selected = compatible;
      } else {
        final picked = await _promptPakModInstallTargets(mod, compatible);
        if (picked == null || picked.isEmpty) return;
        selected = picked;
      }
      if (_blockModDownloadForRunningTargets(
        selected.map((version) => version.id),
      )) {
        return;
      }
      for (final version in selected) {
        targetDirectories.add(_buildModTargetDirectory(mod, version));
        targetVersionIds.add(version.id);
      }
    } else {
      targetDirectories.add(_dllModTargetDirectory(mod));
    }

    final installedPaths = <String>[];
    final totalDownloads = targetDirectories.length * mod.files.length;
    var completed = 0;
    _cancelModDownload = false;
    // Lock the build(s) this mod is downloading into until it's done.
    _setModInstallTargetVersionIds(targetVersionIds);
    void onCancel() => _cancelModDownload = true;
    _toastProgress(
      'Downloading "${mod.name}"...',
      progress: null,
      indeterminate: true,
      onCancel: onCancel,
    );
    try {
      for (final directoryPath in targetDirectories) {
        final targetDirectory = Directory(directoryPath);
        await targetDirectory.create(recursive: true);
        for (final file in mod.files) {
          if (_cancelModDownload) throw _kModDownloadCancelled;
          final destination = File(
            _joinPath([targetDirectory.path, _safeFileName(file.name)]),
          );
          // Patched EXEs replace a stock executable: preserve the original so we
          // can restore it on uninstall, and release the slot from any other
          // patched EXE previously installed there.
          if (mod.type == _AtlasModType.exe) {
            await _backupOriginalExe(destination);
            _forgetConflictingExeInstall(destination.path, mod.id);
          }
          final base = completed;
          await _downloadToFile(
            file.downloadUrl,
            destination,
            onProgress: (received, total) {
              final fileProgress = total == null || total <= 0
                  ? 0.0
                  : (received / total).clamp(0.0, 1.0);
              final progress = totalDownloads == 0
                  ? null
                  : (base + fileProgress) / totalDownloads;
              final pct = progress == null
                  ? ''
                  : ' ${(progress * 100).round()}%';
              _toastProgress(
                'Downloading "${mod.name}" (${base + 1}/$totalDownloads)$pct',
                progress: progress,
                indeterminate: false,
                onCancel: onCancel,
              );
            },
            resolveShareLinks: true,
            rejectHtmlResponse: true,
            isCancelled: () => _cancelModDownload,
          );
          // Mark the slot so this specific patch is distinguishable from the
          // stock executable (and from other patched EXEs).
          if (mod.type == _AtlasModType.exe) {
            await _writeExeMarker(destination.path, mod.id);
          }
          installedPaths.add(destination.path);
          completed++;
        }
      }

      _installedModsById[mod.id] = _InstalledAtlasMod(
        id: mod.id,
        type: mod.type,
        name: mod.name,
        version: mod.version,
        targetVersionId: targetVersionIds.isEmpty ? '' : targetVersionIds.first,
        targetVersionIds: targetVersionIds,
        installedFilePaths: installedPaths,
        installedAtEpochMs: DateTime.now().millisecondsSinceEpoch,
        sourceLastUpdatedEpochMs: mod.lastUpdatedEpochMs,
        filesFingerprint: _atlasModFilesFingerprint(mod),
        dataSlot: mod.dataSlot,
      );
      await _saveInstalledMods();
      if (mounted) setState(() {});
      _toastProgressDismiss();
      _toast(
        _atlasModActionToast(
          action: 'Installed',
          modName: mod.name,
          preposition: 'to',
          type: mod.type,
          targetVersionIds: targetVersionIds,
        ),
      );
    } catch (error) {
      final cancelled = error == _kModDownloadCancelled;
      if (mod.type == _AtlasModType.exe) {
        // Roll back: drop any patched EXE we wrote and restore the originals.
        for (final directoryPath in targetDirectories) {
          for (final file in mod.files) {
            await _restorePatchedExe(
              _joinPath([directoryPath, _safeFileName(file.name)]),
            );
          }
        }
      } else {
        for (final path in installedPaths) {
          try {
            await File(path).delete();
          } catch (_) {}
        }
      }
      _toastProgressDismiss();
      if (cancelled) {
        _toast('Cancelled installing "${mod.name}"');
        _log('mods', 'Install cancelled by user: ${mod.id}');
      } else {
        _toast('Failed to install "${mod.name}"');
        _log('mods', 'Failed to install ${mod.id}: $error');
      }
    } finally {
      _cancelModDownload = false;
    }
  }

  /// Multi-select build picker shared by the install and uninstall flows.
  /// Returns the chosen builds, or `null` if the user cancels. Every build
  /// starts selected so a single tap on the action keeps the common case fast.
  Future<List<VersionEntry>?> _pickPakModBuilds({
    required List<VersionEntry> builds,
    required String title,
    required String subtitle,
    required String actionLabel,
    required IconData actionIcon,
    Set<String> disabledVersionIds = const <String>{},
    Color? actionColor,
  }) async {
    final ordered = List<VersionEntry>.from(builds)
      ..sort((a, b) => _compareVersionStrings(b.gameVersion, a.gameVersion));
    final selectedIds = ordered
        .where((version) => !disabledVersionIds.contains(version.id))
        .map((version) => version.id)
        .toSet();

    return showGeneralDialog<List<VersionEntry>>(
      context: context,
      barrierDismissible: true,
      barrierLabel: MaterialLocalizations.of(context).modalBarrierDismissLabel,
      barrierColor: Colors.transparent,
      transitionDuration: const Duration(milliseconds: 220),
      pageBuilder: (dialogContext, animation, secondaryAnimation) {
        return StatefulBuilder(
          builder: (dialogContext, setDialogState) {
            final secondary = Theme.of(dialogContext).colorScheme.secondary;
            final actionButtonColor = actionColor ?? secondary;
            return SafeArea(
              child: Center(
                child: Material(
                  type: MaterialType.transparency,
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 480),
                    child: Container(
                      decoration: BoxDecoration(
                        color: _dialogSurfaceColor(dialogContext),
                        borderRadius: BorderRadius.circular(24),
                        border: Border.all(
                          color: _onSurface(dialogContext, 0.1),
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: _dialogShadowColor(dialogContext),
                            blurRadius: 30,
                            offset: const Offset(0, 16),
                          ),
                        ],
                      ),
                      child: Padding(
                        padding: const EdgeInsets.fromLTRB(22, 20, 22, 16),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              title,
                              style: TextStyle(
                                fontSize: 22,
                                fontWeight: FontWeight.w800,
                                color: _onSurface(dialogContext, 0.96),
                              ),
                            ),
                            const SizedBox(height: 8),
                            Text(
                              subtitle,
                              style: TextStyle(
                                color: _onSurface(dialogContext, 0.84),
                                height: 1.35,
                              ),
                            ),
                            const SizedBox(height: 14),
                            Flexible(
                              child: SingleChildScrollView(
                                child: Column(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    for (final version in ordered)
                                      CheckboxListTile(
                                        enabled: !disabledVersionIds.contains(
                                          version.id,
                                        ),
                                        value: selectedIds.contains(version.id),
                                        activeColor: secondary,
                                        checkColor: Colors.white,
                                        onChanged:
                                            disabledVersionIds.contains(
                                              version.id,
                                            )
                                            ? null
                                            : (checked) => setDialogState(
                                                () => checked == true
                                                    ? selectedIds.add(
                                                        version.id,
                                                      )
                                                    : selectedIds.remove(
                                                        version.id,
                                                      ),
                                              ),
                                        contentPadding: EdgeInsets.zero,
                                        controlAffinity:
                                            ListTileControlAffinity.leading,
                                        dense: true,
                                        title: Text(
                                          version.name.trim().isEmpty
                                              ? _formatLibraryVersionLabel(
                                                  version.gameVersion,
                                                )
                                              : version.name.trim(),
                                          style: TextStyle(
                                            fontWeight: FontWeight.w600,
                                            color: _onSurface(
                                              dialogContext,
                                              0.94,
                                            ),
                                          ),
                                        ),
                                        subtitle: Text(
                                          disabledVersionIds.contains(
                                                version.id,
                                              )
                                              ? 'Version ${_formatLibraryVersionLabel(version.gameVersion)} - Running'
                                              : 'Version ${_formatLibraryVersionLabel(version.gameVersion)}',
                                          style: TextStyle(
                                            color: _onSurface(
                                              dialogContext,
                                              0.6,
                                            ),
                                          ),
                                        ),
                                      ),
                                  ],
                                ),
                              ),
                            ),
                            const SizedBox(height: 16),
                            Row(
                              children: [
                                _dialogCancelButton(
                                  dialogContext,
                                  onPressed: () =>
                                      Navigator.of(dialogContext).pop(),
                                ),
                                const Spacer(),
                                FilledButton.icon(
                                  onPressed: selectedIds.isEmpty
                                      ? null
                                      : () => Navigator.of(dialogContext).pop(
                                          ordered
                                              .where(
                                                (version) => selectedIds
                                                    .contains(version.id),
                                              )
                                              .toList(),
                                        ),
                                  style: FilledButton.styleFrom(
                                    backgroundColor: actionButtonColor,
                                    foregroundColor: Colors.white,
                                    disabledBackgroundColor: _onSurface(
                                      dialogContext,
                                      0.16,
                                    ),
                                    disabledForegroundColor: _onSurface(
                                      dialogContext,
                                      0.5,
                                    ),
                                  ),
                                  icon: Icon(actionIcon),
                                  label: Text(
                                    selectedIds.length > 1
                                        ? '$actionLabel (${selectedIds.length})'
                                        : actionLabel,
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            );
          },
        );
      },
      transitionBuilder: _dialogPopupTransition,
    );
  }

  /// Asks which compatible builds to install a pak mod to.
  Future<List<VersionEntry>?> _promptPakModInstallTargets(
    _AtlasModEntry mod,
    List<VersionEntry> compatible,
  ) {
    final spec = mod.version.trim();
    final runningVersionIds = compatible
        .where((version) => _isVersionRunning(version.id))
        .map((version) => version.id)
        .toSet();
    return _pickPakModBuilds(
      builds: compatible,
      title: 'Install ${mod.name}',
      subtitle: spec.isEmpty
          ? runningVersionIds.isEmpty
                ? 'Choose which builds to install this mod to.'
                : 'Choose which builds to install this mod to. Running builds are disabled.'
          : runningVersionIds.isEmpty
          ? 'Compatible with $spec. Choose which of your builds to install to.'
          : 'Compatible with $spec. Choose which of your builds to install to. Running builds are disabled.',
      actionLabel: 'Install',
      actionIcon: Icons.download_rounded,
      disabledVersionIds: runningVersionIds,
    );
  }

  /// Asks which builds to remove a pak mod from.
  Future<List<VersionEntry>?> _promptPakModUninstallTargets(
    _AtlasModEntry mod,
    List<VersionEntry> installedBuilds,
  ) {
    return _pickPakModBuilds(
      builds: installedBuilds,
      title: 'Uninstall ${mod.name}',
      subtitle: 'Choose which builds to remove this mod from.',
      actionLabel: 'Uninstall',
      actionIcon: Icons.delete_outline_rounded,
      actionColor: const Color(0xFFB3261E),
    );
  }

  Future<void> _uninstallAtlasMod(_AtlasModEntry mod) async {
    final installed =
        _installedModsById[mod.id] ?? _detectExistingAtlasModInstall(mod);
    if (installed == null) return;

    // When a build-targeted mod is installed to more than one build, let the
    // user choose which builds to remove it from instead of wiping all of them.
    List<VersionEntry>? selectedBuilds;
    if (mod.type.isBuildTargeted && installed.targetVersionIds.length > 1) {
      final installedBuilds = installed.targetVersionIds
          .map(_findVersionById)
          .whereType<VersionEntry>()
          .toList();
      if (installedBuilds.length > 1) {
        final picked = await _promptPakModUninstallTargets(
          mod,
          installedBuilds,
        );
        if (picked == null || picked.isEmpty) return;
        selectedBuilds = picked;
      }
    }

    // Patched EXEs are restored to their original (stock) executable; everything
    // else is simply deleted from disk.
    Future<void> removePaths(Iterable<String> paths) async {
      for (final path in paths) {
        try {
          if (mod.type == _AtlasModType.exe) {
            await _restorePatchedExe(path);
          } else {
            final file = File(path);
            if (await file.exists()) await file.delete();
          }
        } catch (error) {
          _log('mods', 'Failed to remove installed mod file $path: $error');
        }
      }
    }

    if (selectedBuilds == null) {
      // Remove everything (DLL mod, single build, or legacy record).
      await removePaths(installed.installedFilePaths);
      _installedModsById.remove(mod.id);
    } else {
      final selectedIds = selectedBuilds.map((build) => build.id).toSet();
      for (final build in selectedBuilds) {
        await removePaths(
          _atlasModFilePathsInDirectory(
            mod,
            _buildModTargetDirectory(mod, build),
          ),
        );
      }
      final remainingIds = installed.targetVersionIds
          .where((id) => !selectedIds.contains(id))
          .toList();
      if (remainingIds.isEmpty) {
        _installedModsById.remove(mod.id);
      } else {
        final remainingPaths = <String>[];
        for (final id in remainingIds) {
          final version = _findVersionById(id);
          if (version == null) continue;
          remainingPaths.addAll(
            _atlasModFilePathsInDirectory(
              mod,
              _buildModTargetDirectory(mod, version),
            ),
          );
        }
        _installedModsById[mod.id] = installed.copyWith(
          targetVersionId: remainingIds.first,
          targetVersionIds: remainingIds,
          installedFilePaths: remainingPaths,
        );
      }
    }

    await _saveInstalledMods();
    if (mounted) setState(() {});
    _toast(
      _atlasModActionToast(
        action: 'Removed',
        modName: installed.name,
        preposition: 'from',
        type: installed.type,
        targetVersionIds: selectedBuilds == null
            ? installed.targetVersionIds
            : const <String>[],
        targetBuilds: selectedBuilds ?? const <VersionEntry>[],
      ),
    );
  }

  /// Re-syncs an installed mod's files to the current catalog release. Because
  /// every target build receives the same file set, the rename / replace / add
  /// scenarios all reduce to: delete files whose names are gone from the new
  /// release, then (re)download the current file set in place.
  Future<void> _updateAtlasMod(
    _AtlasModEntry mod, {
    bool announce = true,
  }) async {
    final installed = _installedModsById[mod.id];
    if (installed == null || !_installedAtlasModFilesPresent(installed)) {
      // Nothing recorded to update against; treat it as a fresh install.
      await _installAtlasMod(mod);
      return;
    }
    if (mod.files.isEmpty) {
      _toast('${mod.name} has no downloadable files');
      return;
    }

    // The directories the mod currently lives in (one per installed build, or
    // the shared DLL library).
    final targetDirectories = <String>[];
    final targetVersionIds = <String>[];
    if (mod.type.isBuildTargeted) {
      for (final id in installed.targetVersionIds) {
        final version = _findVersionById(id);
        if (version == null) continue; // build was removed; skip it
        targetDirectories.add(_buildModTargetDirectory(mod, version));
        targetVersionIds.add(id);
      }
      if (targetDirectories.isEmpty) {
        _toast('No installed build found to update ${mod.name}');
        return;
      }
      if (_blockModDownloadForRunningTargets(targetVersionIds)) return;
    } else {
      targetDirectories.add(_dllModTargetDirectory(mod));
    }

    // Files present in the old release but not the new one (renamed/removed).
    final oldNames = installed.installedFilePaths.map(_basename).toSet();
    final newNames = mod.files.map((file) => _safeFileName(file.name)).toSet();
    final staleNames = oldNames.difference(newNames);

    final installedPaths = <String>[];
    final totalDownloads = targetDirectories.length * mod.files.length;
    var completed = 0;
    _cancelModDownload = false;
    // Lock the build(s) this mod is downloading into until it's done.
    _setModInstallTargetVersionIds(targetVersionIds);
    void onCancel() => _cancelModDownload = true;
    _toastProgress(
      'Updating "${mod.name}"...',
      progress: null,
      indeterminate: true,
      onCancel: onCancel,
    );
    try {
      for (final directoryPath in targetDirectories) {
        final directory = Directory(directoryPath);
        await directory.create(recursive: true);
        // Drop files that were renamed away or dropped from the new release.
        // (For EXEs this restores the stock executable for any name no longer
        // shipped, instead of leaving a stray patched binary behind.)
        for (final stale in staleNames) {
          final stalePath = _joinPath([directory.path, stale]);
          try {
            if (mod.type == _AtlasModType.exe) {
              await _restorePatchedExe(stalePath);
            } else {
              final staleFile = File(stalePath);
              if (await staleFile.exists()) await staleFile.delete();
            }
          } catch (error) {
            _log('mods', 'Failed to remove stale mod file $stale: $error');
          }
        }
        // (Re)download the current file set: same-name files are replaced in
        // place, brand new files are added. The original stock EXE was already
        // backed up at first install, so updating just swaps the patched binary.
        for (final file in mod.files) {
          if (_cancelModDownload) throw _kModDownloadCancelled;
          final destination = File(
            _joinPath([directory.path, _safeFileName(file.name)]),
          );
          if (mod.type == _AtlasModType.exe) {
            await _backupOriginalExe(destination);
          }
          final base = completed;
          await _downloadToFile(
            file.downloadUrl,
            destination,
            onProgress: (received, total) {
              final fileProgress = total == null || total <= 0
                  ? 0.0
                  : (received / total).clamp(0.0, 1.0);
              final progress = totalDownloads == 0
                  ? null
                  : (base + fileProgress) / totalDownloads;
              final pct = progress == null
                  ? ''
                  : ' ${(progress * 100).round()}%';
              _toastProgress(
                'Updating "${mod.name}" (${base + 1}/$totalDownloads)$pct',
                progress: progress,
                indeterminate: false,
                onCancel: onCancel,
              );
            },
            resolveShareLinks: true,
            rejectHtmlResponse: true,
            isCancelled: () => _cancelModDownload,
          );
          if (mod.type == _AtlasModType.exe) {
            await _writeExeMarker(destination.path, mod.id);
          }
          installedPaths.add(destination.path);
          completed++;
        }
      }

      _installedModsById[mod.id] = installed.copyWith(
        name: mod.name,
        version: mod.version,
        targetVersionId: targetVersionIds.isEmpty
            ? installed.targetVersionId
            : targetVersionIds.first,
        targetVersionIds: targetVersionIds.isEmpty
            ? installed.targetVersionIds
            : targetVersionIds,
        installedFilePaths: installedPaths,
        installedAtEpochMs: DateTime.now().millisecondsSinceEpoch,
        sourceLastUpdatedEpochMs: mod.lastUpdatedEpochMs,
        filesFingerprint: _atlasModFilesFingerprint(mod),
        dataSlot: mod.dataSlot,
      );
      await _saveInstalledMods();
      if (mounted) setState(() {});
      _toastProgressDismiss();
      if (announce) {
        _toast(
          _atlasModActionToast(
            action: 'Updated',
            modName: mod.name,
            preposition: 'in',
            type: mod.type,
            targetVersionIds: targetVersionIds,
          ),
        );
      }
    } catch (error) {
      // Leave any partially written files and the old record in place so the
      // mod keeps working and still shows as needing an update to retry.
      _toastProgressDismiss();
      final cancelled = error == _kModDownloadCancelled;
      if (cancelled) {
        if (announce) _toast('Cancelled updating "${mod.name}"');
        _log('mods', 'Update cancelled by user: ${mod.id}');
      } else {
        if (announce) _toast('Failed to update ${mod.name}');
        _log('mods', 'Failed to update ${mod.id}: $error');
      }
    } finally {
      _cancelModDownload = false;
    }
  }

  Map<String, _InstalledAtlasMod> _installedAtlasModsSnapshot() {
    final installed = <String, _InstalledAtlasMod>{};
    for (final entry in _installedModsById.entries) {
      if (_installedAtlasModFilesPresent(entry.value)) {
        installed[entry.key] = entry.value;
      }
    }
    for (final mod in _modsLibrary) {
      final detected = _detectExistingAtlasModInstall(mod);
      if (detected != null) installed[mod.id] = detected;
    }
    return installed;
  }

  Future<void> _clearInstalledAtlasMods() async {
    final installed = _installedAtlasModsSnapshot();
    if (installed.isEmpty) {
      _toast('No installed mods to clear');
      return;
    }

    final confirmed = await showGeneralDialog<bool>(
      context: context,
      barrierDismissible: true,
      barrierLabel: MaterialLocalizations.of(context).modalBarrierDismissLabel,
      barrierColor: Colors.transparent,
      transitionDuration: const Duration(milliseconds: 220),
      pageBuilder: (dialogContext, animation, secondaryAnimation) {
        return SafeArea(
          child: Center(
            child: Material(
              type: MaterialType.transparency,
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 480),
                child: Container(
                  decoration: BoxDecoration(
                    color: _dialogSurfaceColor(dialogContext),
                    borderRadius: BorderRadius.circular(24),
                    border: Border.all(color: _onSurface(dialogContext, 0.1)),
                    boxShadow: [
                      BoxShadow(
                        color: _dialogShadowColor(dialogContext),
                        blurRadius: 30,
                        offset: const Offset(0, 16),
                      ),
                    ],
                  ),
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(22, 20, 22, 16),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Clear all installed mods?',
                          style: TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.w800,
                            color: _onSurface(dialogContext, 0.96),
                          ),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          'This will delete and clear all ${installed.length} mod${installed.length == 1 ? '' : 's'} you have currently installed. Are you sure you want to continue?',
                          style: TextStyle(
                            color: _onSurface(dialogContext, 0.84),
                            height: 1.35,
                          ),
                        ),
                        const SizedBox(height: 16),
                        Row(
                          children: [
                            _dialogCancelButton(
                              dialogContext,
                              onPressed: () =>
                                  Navigator.of(dialogContext).pop(false),
                            ),
                            const Spacer(),
                            FilledButton.icon(
                              onPressed: () =>
                                  Navigator.of(dialogContext).pop(true),
                              style: FilledButton.styleFrom(
                                backgroundColor: const Color(0xFFB3261E),
                                foregroundColor: Colors.white,
                              ),
                              icon: const Icon(Icons.delete_sweep_rounded),
                              label: const Text('Clear Mods'),
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
        );
      },
      transitionBuilder: _dialogPopupTransition,
    );

    if (confirmed != true) return;

    var deletedFiles = 0;
    for (final mod in installed.values) {
      for (final path in mod.installedFilePaths) {
        try {
          final file = File(path);
          if (await file.exists()) {
            await file.delete();
            deletedFiles++;
          }
        } catch (error) {
          _log('mods', 'Failed to delete installed mod file $path: $error');
        }
      }
      _installedModsById.remove(mod.id);
    }
    await _saveInstalledMods();
    if (mounted) setState(() {});
    _toast(
      deletedFiles == 1
          ? 'Cleared 1 mod file'
          : 'Cleared $deletedFiles mod files',
    );
  }

  List<_SavedInjectorDll> _installedModInjectorDlls() {
    final options = <_SavedInjectorDll>[];
    for (final mod in _installedModsById.values) {
      if (mod.type != _AtlasModType.dll) continue;
      final dllPaths = mod.installedFilePaths.where((path) {
        return path.toLowerCase().endsWith('.dll') && File(path).existsSync();
      }).toList();
      for (final path in dllPaths) {
        final label = dllPaths.length == 1
            ? mod.name
            : '${mod.name} - ${_basename(path)}';
        options.add(_SavedInjectorDll(label: label, path: path));
      }
    }
    return _normalizedInjectorDllLibrary(options);
  }

  Future<void> _resetBundledDllPathToLatest({
    required _BundledDllSpec spec,
    required LauncherSettings Function(LauncherSettings, String) applySetting,
    required TextEditingController controller,
    bool checkForUpdatesAfter = true,
    Map<String, _BundledDllRemoteAsset>? remoteAssets,
    bool showFeedback = true,
    bool refreshPresetSeedsAfter = true,
  }) async {
    var nextPath = await _downloadLatestBundledDllFromGitHub(
      spec: spec,
      remoteAssets: remoteAssets,
      showProgressUi: showFeedback,
    );
    if (nextPath == null || nextPath.trim().isEmpty) {
      _log(
        'settings',
        'Falling back to packaged ${spec.label} DLL after GitHub refresh failed.',
      );
      if (showFeedback && mounted) {
        _toast('Updating ${spec.fileName}...');
      }
      nextPath = await _ensureBundledDll(
        bundledAssetPath: spec.assetPath,
        bundledFileName: spec.fileName,
        label: spec.label,
        overwriteFallbackCopy: true,
        showFeedback: showFeedback,
      );
    }

    final normalized = nextPath?.trim() ?? '';
    if (mounted) {
      setState(() {
        _settings = applySetting(_settings, normalized);
        controller.text = normalized;
      });
    } else {
      _settings = applySetting(_settings, normalized);
      controller.text = normalized;
    }
    await _saveSettings(toast: false);
    if (refreshPresetSeedsAfter) {
      await _ensureBundledDllPresetSeeds();
    }
    if (checkForUpdatesAfter) {
      unawaited(_checkForBundledDllDefaultUpdates(silent: true));
    }
  }

  Future<bool> _tryDownloadBundledDllFromGitHub({
    required String bundledAssetPath,
    required File outputFile,
    required String label,
    bool showProgressUi = true,
  }) async {
    final normalized = bundledAssetPath
        .trim()
        .replaceAll('\\', '/')
        .replaceFirst(RegExp(r'^/+'), '');
    if (normalized.isEmpty) return false;

    // Only allow downloading assets that are expected to ship with the launcher.
    if (!normalized.toLowerCase().startsWith('assets/dlls/')) return false;

    final url = '$_atlasLinkBundledDllFallbackBaseUrl$normalized';
    final tmp = File('${outputFile.path}.tmp');
    try {
      if (await tmp.exists()) {
        await tmp.delete();
      }

      _log(
        'settings',
        'Bundled $label DLL missing. Downloading from GitHub...',
      );
      final progressMessage = 'Updating ${_basename(outputFile.path)}...';
      if (showProgressUi && mounted) {
        _toastProgress(progressMessage, progress: null, indeterminate: true);
      }
      await _downloadToFile(
        url,
        tmp,
        onProgress: (receivedBytes, totalBytes) {
          if (!showProgressUi || !mounted) return;
          if (totalBytes == null || totalBytes <= 0) {
            _toastProgress(
              progressMessage,
              progress: null,
              indeterminate: true,
            );
            return;
          }
          final ratio = (receivedBytes / totalBytes).clamp(0.0, 1.0);
          _toastProgress(
            progressMessage,
            progress: ratio,
            indeterminate: false,
          );
        },
      );
      final length = await tmp.length();
      if (length <= 0) {
        throw 'Downloaded file was empty.';
      }

      if (await outputFile.exists()) {
        await outputFile.delete();
      }
      await tmp.rename(outputFile.path);
      if (showProgressUi && mounted) {
        _toastProgressDismiss();
      }
      return true;
    } catch (error) {
      _log(
        'settings',
        'Failed to download default $label DLL from GitHub ($url): $error',
      );
      if (showProgressUi && mounted) {
        _toastProgressDismiss();
      }
      try {
        if (await tmp.exists()) {
          await tmp.delete();
        }
      } catch (_) {
        // Ignore cleanup failures.
      }
      return false;
    }
  }

  Future<String?> _ensureBundledDll({
    required String bundledAssetPath,
    required String bundledFileName,
    required String label,
    bool overwriteFallbackCopy = false,
    bool showFeedback = true,
  }) async {
    final installedPath = _resolveBundledAssetFilePath(bundledAssetPath);
    if (installedPath != null) return installedPath;

    final dllDir = Directory(_joinPath([_dataDir.path, 'dlls']));
    try {
      await dllDir.create(recursive: true);
      await _normalizeManagedDllFileNameCasing(dllDir, bundledFileName);
      final outputPath = _joinPath([dllDir.path, bundledFileName]);
      final outputFile = File(outputPath);
      if (overwriteFallbackCopy || !outputFile.existsSync()) {
        if (showFeedback && mounted && overwriteFallbackCopy) {
          _toast('Updating $bundledFileName...');
        }
        try {
          final bytes = await rootBundle.load(bundledAssetPath);
          await outputFile.writeAsBytes(
            bytes.buffer.asUint8List(bytes.offsetInBytes, bytes.lengthInBytes),
            flush: true,
          );
        } catch (error) {
          // If the packaged asset is missing/corrupted, fall back to fetching
          // the default from GitHub so the Reset button can still restore it.
          _log(
            'settings',
            'Failed to extract bundled $label DLL ($bundledAssetPath): $error',
          );
          final downloaded = await _tryDownloadBundledDllFromGitHub(
            bundledAssetPath: bundledAssetPath,
            outputFile: outputFile,
            label: label,
            showProgressUi: showFeedback,
          );
          if (!downloaded) rethrow;
        }
      }
      return outputPath;
    } catch (error) {
      _log(
        'settings',
        'Failed to prepare bundled $label DLL ($bundledAssetPath): $error',
      );
      return null;
    }
  }

  Future<void> _normalizeManagedDllFileNameCasing(
    Directory directory,
    String fileName,
  ) async {
    if (!Platform.isWindows) return;
    try {
      if (!await directory.exists()) return;
      await for (final entity in directory.list(followLinks: false)) {
        if (entity is! File) continue;
        final currentName = _basename(entity.path);
        if (!_bundledDllFileNameMatches(currentName, fileName)) continue;
        if (currentName == fileName) return;

        final targetPath = _joinPath([directory.path, fileName]);
        final tempPath = _joinPath([
          directory.path,
          '$fileName.rename-${DateTime.now().microsecondsSinceEpoch}.tmp',
        ]);
        final tempFile = File(tempPath);
        if (await tempFile.exists()) {
          await tempFile.delete();
        }
        await entity.rename(tempPath);
        await File(tempPath).rename(targetPath);
        _log('settings', 'Renamed bundled DLL $currentName to $fileName.');
        return;
      }
    } catch (error) {
      _log(
        'settings',
        'Failed to normalize bundled DLL filename $fileName: $error',
      );
    }
  }

  Future<int> _maybeAutoUpdateBundledDllAssetsOnLaunch({
    bool showProgressUi = false,
  }) async {
    var updatedCount = 0;
    try {
      final remoteAssets = await _fetchBundledDllRemoteAssets(
        forceRefresh: true,
      );
      if (remoteAssets.isEmpty) {
        return 0;
      }

      for (final spec in _bundledDllSpecs) {
        final remote = remoteAssets[spec.fileNameLower];
        if (remote == null) {
          continue;
        }

        final localDefaultPath = _resolveCurrentBundledDefaultDllPath(spec);
        final localDefaultSha =
            localDefaultPath == null || localDefaultPath.trim().isEmpty
            ? null
            : await _computeGitBlobShaForFile(File(localDefaultPath));
        final needsRefresh =
            localDefaultSha == null || localDefaultSha != remote.sha;

        if (localDefaultPath == null || localDefaultPath.trim().isEmpty) {
          continue;
        }

        if (needsRefresh) {
          _log(
            'settings',
            'Bundled default ${spec.fileName} is outdated on launch. Refreshing local default copy.',
          );
          var refreshedPath = await _downloadLatestBundledDllFromGitHub(
            spec: spec,
            remoteAssets: remoteAssets,
            showProgressUi: showProgressUi,
            outputPathOverride: localDefaultPath,
          );
          if (refreshedPath == null || refreshedPath.trim().isEmpty) {
            _log(
              'settings',
              'Falling back to packaged ${spec.fileName} after silent launch refresh failed.',
            );
            refreshedPath = await _ensureBundledDll(
              bundledAssetPath: spec.assetPath,
              bundledFileName: spec.fileName,
              label: spec.label,
              overwriteFallbackCopy: true,
              showFeedback: showProgressUi,
            );
          }
          if (refreshedPath != null &&
              refreshedPath.trim().isNotEmpty &&
              _normalizePath(refreshedPath) !=
                  _normalizePath(localDefaultPath)) {
            _log(
              'settings',
              'Launch refresh wrote ${spec.fileName} to a fallback path because the active default path could not be updated in place.',
            );
          }
          if (refreshedPath != null && refreshedPath.trim().isNotEmpty) {
            updatedCount += 1;
          }
        }
      }
      if (updatedCount > 0) {
        await _ensureBundledDllPresetSeeds();
      }
    } catch (error) {
      _log(
        'settings',
        'Failed to auto-refresh bundled default DLL assets on launch: $error',
      );
    }
    return updatedCount;
  }

  Future<void> _applyBundledDllDefaults({
    bool forceResetBundledPaths = false,
  }) async {
    var nextSettings = _settings;
    var changed = false;

    final bundledGameServerPath = await _ensureBundledDll(
      bundledAssetPath: 'assets/dlls/Magnesium.dll',
      bundledFileName: 'Magnesium.dll',
      label: 'game server',
      overwriteFallbackCopy: forceResetBundledPaths,
    );
    if (bundledGameServerPath != null &&
        bundledGameServerPath.trim().isNotEmpty) {
      final configuredGameServer = _settings.gameServerFilePath.trim();
      final gameServerExists =
          configuredGameServer.isNotEmpty &&
          File(configuredGameServer).existsSync();
      final looksBundledGameServer = _looksLikeBundledAssetDllPath(
        configuredGameServer,
        'Magnesium.dll',
      );
      final bundledFromCurrentInstall = _isBundledAssetDllFromCurrentInstall(
        configuredGameServer,
        'Magnesium.dll',
      );
      final shouldAdoptBundledGameServer =
          configuredGameServer.isEmpty ||
          (configuredGameServer.isNotEmpty && !gameServerExists) ||
          (looksBundledGameServer &&
              (!bundledFromCurrentInstall || forceResetBundledPaths));
      if (shouldAdoptBundledGameServer) {
        nextSettings = nextSettings.copyWith(
          gameServerFilePath: bundledGameServerPath,
        );
        _gameServerFileController.text = bundledGameServerPath;
        changed = true;
        if (configuredGameServer.isNotEmpty && !gameServerExists) {
          _log(
            'settings',
            'Game server DLL missing at $configuredGameServer. Restored bundled default.',
          );
        }
      }
    }

    final bundledMemoryPath = await _ensureBundledDll(
      bundledAssetPath: 'assets/dlls/Memory.dll',
      bundledFileName: 'Memory.dll',
      label: 'memory patcher',
      overwriteFallbackCopy: forceResetBundledPaths,
    );
    if (bundledMemoryPath != null && bundledMemoryPath.trim().isNotEmpty) {
      final configuredMemory = _settings.memoryPatcherPath.trim();
      final memoryExists =
          configuredMemory.isNotEmpty && File(configuredMemory).existsSync();
      final looksBundledMemory = _looksLikeBundledAssetDllPath(
        configuredMemory,
        'Memory.dll',
      );
      final bundledMemoryFromCurrentInstall =
          _isBundledAssetDllFromCurrentInstall(configuredMemory, 'Memory.dll');
      final shouldAdoptBundledMemory =
          configuredMemory.isEmpty ||
          (configuredMemory.isNotEmpty && !memoryExists) ||
          _usesLegacyBundledDllCasing(configuredMemory, 'Memory.dll') ||
          (looksBundledMemory &&
              (!bundledMemoryFromCurrentInstall || forceResetBundledPaths));
      if (shouldAdoptBundledMemory) {
        nextSettings = nextSettings.copyWith(
          memoryPatcherPath: bundledMemoryPath,
        );
        _memoryPatcherController.text = bundledMemoryPath;
        changed = true;
        if (configuredMemory.isNotEmpty && !memoryExists) {
          _log(
            'settings',
            'Memory patcher DLL missing at $configuredMemory. Restored bundled default.',
          );
        }
      }
    }

    final bundledAuthPath = await _ensureBundledDll(
      bundledAssetPath: 'assets/dlls/Tellurium.dll',
      bundledFileName: 'Tellurium.dll',
      label: 'authentication patcher',
      overwriteFallbackCopy: forceResetBundledPaths,
    );
    if (bundledAuthPath != null && bundledAuthPath.trim().isNotEmpty) {
      final configuredAuth = nextSettings.authenticationPatcherPath.trim();
      final authExists =
          configuredAuth.isNotEmpty && File(configuredAuth).existsSync();
      final looksBundledAuth = _looksLikeBundledAssetDllPath(
        configuredAuth,
        'Tellurium.dll',
      );
      final bundledAuthFromCurrentInstall =
          _isBundledAssetDllFromCurrentInstall(configuredAuth, 'Tellurium.dll');
      final shouldAdoptBundledAuth =
          configuredAuth.isEmpty ||
          (configuredAuth.isNotEmpty && !authExists) ||
          (looksBundledAuth &&
              (!bundledAuthFromCurrentInstall || forceResetBundledPaths));
      if (shouldAdoptBundledAuth) {
        nextSettings = nextSettings.copyWith(
          authenticationPatcherPath: bundledAuthPath,
        );
        _authenticationPatcherController.text = bundledAuthPath;
        changed = true;
        if (configuredAuth.isNotEmpty && !authExists) {
          _log(
            'settings',
            'Authentication patcher DLL missing at $configuredAuth. Restored bundled default.',
          );
        }
      }
    }

    final configuredUnrealBeforeDefault = nextSettings.unrealEnginePatcherPath
        .trim();
    if (configuredUnrealBeforeDefault.isNotEmpty &&
        (_isManagedBundledDllPath(
              configuredUnrealBeforeDefault,
              'Remix Console.dll',
            ) ||
            _looksLikeBundledAssetDllPath(
              configuredUnrealBeforeDefault,
              'Remix Console.dll',
            ) ||
            (!File(configuredUnrealBeforeDefault).existsSync() &&
                _usesLegacyBundledDllName(
                  configuredUnrealBeforeDefault,
                  'Remix Console.dll',
                )))) {
      final remixConsolePath = await _ensureBundledDll(
        bundledAssetPath: 'assets/dlls/Remix Console.dll',
        bundledFileName: 'Remix Console.dll',
        label: 'Remix unreal engine patcher',
        overwriteFallbackCopy: forceResetBundledPaths,
      );
      if (remixConsolePath != null && remixConsolePath.trim().isNotEmpty) {
        nextSettings = nextSettings.copyWith(
          unrealEnginePatcherPath: remixConsolePath,
        );
        _unrealEnginePatcherController.text = remixConsolePath;
        changed = true;
      }
    }

    final bundledUnrealPath = await _ensureBundledDll(
      bundledAssetPath: 'assets/dlls/Console.dll',
      bundledFileName: 'Console.dll',
      label: 'unreal engine patcher',
      overwriteFallbackCopy: forceResetBundledPaths,
    );
    if (bundledUnrealPath != null && bundledUnrealPath.trim().isNotEmpty) {
      final configuredUnreal = nextSettings.unrealEnginePatcherPath.trim();
      final unrealExists =
          configuredUnreal.isNotEmpty && File(configuredUnreal).existsSync();
      final looksBundledUnreal = _looksLikeBundledAssetDllPath(
        configuredUnreal,
        'Console.dll',
      );
      final bundledUnrealFromCurrentInstall =
          _isBundledAssetDllFromCurrentInstall(configuredUnreal, 'Console.dll');
      final shouldAdoptBundledUnreal =
          configuredUnreal.isEmpty ||
          (configuredUnreal.isNotEmpty && !unrealExists) ||
          _usesLegacyBundledDllCasing(configuredUnreal, 'Console.dll') ||
          _usesLegacyBundledDllName(configuredUnreal, 'Console.dll') ||
          (looksBundledUnreal &&
              (!bundledUnrealFromCurrentInstall || forceResetBundledPaths));
      if (shouldAdoptBundledUnreal) {
        nextSettings = nextSettings.copyWith(
          unrealEnginePatcherPath: bundledUnrealPath,
        );
        _unrealEnginePatcherController.text = bundledUnrealPath;
        changed = true;
        if (configuredUnreal.isNotEmpty && !unrealExists) {
          _log(
            'settings',
            'Unreal engine patcher DLL missing at $configuredUnreal. Restored bundled default.',
          );
        }
      }
    }

    if (!changed) return;
    _settings = nextSettings;
    await _saveSettings(toast: false);
  }

  Future<void> _loadInstallState() async {
    if (!await _installStateFile.exists()) {
      _installState = LauncherInstallState.defaults();
      return;
    }
    try {
      final raw = await _installStateFile.readAsString();
      final decoded = jsonDecode(raw);
      if (decoded is Map<String, dynamic>) {
        _installState = LauncherInstallState.fromJson(decoded);
      } else if (decoded is Map) {
        _installState = LauncherInstallState.fromJson(
          decoded.cast<String, dynamic>(),
        );
      } else {
        _installState = LauncherInstallState.defaults();
      }
    } catch (error) {
      _installState = LauncherInstallState.defaults();
      _log('settings', 'Invalid install state file. Loaded defaults. $error');
    }
  }

  Future<void> _saveInstallState() async {
    final pretty = const JsonEncoder.withIndent(
      '  ',
    ).convert(_installState.toJson());
    await _installStateFile.writeAsString(pretty, flush: true);
  }

  Future<void> _reconcileInstallState() async {
    final resolvedProfileSetup =
        _settings.profileSetupComplete || _installState.profileSetupComplete;
    final resolvedLibraryNudge =
        _settings.libraryActionsNudgeComplete ||
        _installState.libraryActionsNudgeComplete;
    final resolvedBackendConnectionTip =
        _settings.backendConnectionTipComplete ||
        _installState.backendConnectionTipComplete;

    var installStateChanged = false;
    var settingsChanged = false;

    if (_installState.profileSetupComplete != resolvedProfileSetup ||
        _installState.libraryActionsNudgeComplete != resolvedLibraryNudge ||
        _installState.backendConnectionTipComplete !=
            resolvedBackendConnectionTip) {
      _installState = _installState.copyWith(
        profileSetupComplete: resolvedProfileSetup,
        libraryActionsNudgeComplete: resolvedLibraryNudge,
        backendConnectionTipComplete: resolvedBackendConnectionTip,
      );
      installStateChanged = true;
    }

    if (_settings.profileSetupComplete != resolvedProfileSetup ||
        _settings.libraryActionsNudgeComplete != resolvedLibraryNudge ||
        _settings.backendConnectionTipComplete !=
            resolvedBackendConnectionTip) {
      _settings = _settings.copyWith(
        profileSetupComplete: resolvedProfileSetup,
        libraryActionsNudgeComplete: resolvedLibraryNudge,
        backendConnectionTipComplete: resolvedBackendConnectionTip,
      );
      settingsChanged = true;
    }

    if (installStateChanged) {
      try {
        await _saveInstallState();
      } catch (error) {
        _log('settings', 'Failed to save install state: $error');
      }
    }

    if (settingsChanged) {
      try {
        await _saveSettings(toast: false, applyControllers: false);
      } catch (error) {
        _log('settings', 'Failed to persist reconciled settings: $error');
      }
    }
  }

  Future<void> _loadSettings() async {
    if (!await _settingsFile.exists()) {
      _settingsRawFileData = <String, dynamic>{};
      _settings = LauncherSettings.defaults();
      await _migrateAppearanceSettingsFileIfNeeded();
      return;
    }
    try {
      final raw = await _settingsFile.readAsString();
      final decoded = jsonDecode(raw);
      if (decoded is Map<String, dynamic>) {
        _settingsRawFileData = Map<String, dynamic>.from(decoded);
        _settings = LauncherSettings.fromJson(decoded);
      } else if (decoded is Map) {
        _settingsRawFileData = decoded.cast<String, dynamic>();
        _settings = LauncherSettings.fromJson(decoded.cast<String, dynamic>());
      } else {
        _settingsRawFileData = <String, dynamic>{};
        _settings = LauncherSettings.defaults();
      }
      _settings = _settingsWithSynchronizedOverallPlaytime(_settings);
      await _migrateAppearanceSettingsFileIfNeeded();
      await _mergeSettingsSchemaIntoExistingFileIfNeeded();
    } catch (error) {
      _settingsRawFileData = <String, dynamic>{};
      _settings = LauncherSettings.defaults();
      _log('settings', 'Invalid settings file. Loaded defaults. $error');
      await _migrateAppearanceSettingsFileIfNeeded();
    }
  }

  Future<void> _loadDllPresets() async {
    if (!_storageReady) return;
    if (!await _dllPresetsFile.exists()) {
      _dllPresets = <_DllPreset>[];
      _dllPresetSeedVersion = 0;
      return;
    }

    try {
      int asInt(dynamic value, int fallback) {
        if (value is int) return value;
        if (value is num) return value.toInt();
        if (value is String) return int.tryParse(value) ?? fallback;
        return fallback;
      }

      final raw = await _dllPresetsFile.readAsString();
      final decoded = jsonDecode(raw);
      _dllPresetSeedVersion = decoded is Map
          ? asInt(
              decoded['bundledDllPresetSeedVersion'] ??
                  decoded['dllPresetSeedVersion'],
              0,
            )
          : 0;
      final presetsRaw = decoded is Map
          ? decoded['presets']
          : decoded is List
          ? decoded
          : null;
      if (presetsRaw is! List) {
        _dllPresets = <_DllPreset>[];
        return;
      }

      final parsed = <_DllPreset>[];
      for (final item in presetsRaw) {
        if (item is Map<String, dynamic>) {
          final preset = _DllPreset.fromJson(item);
          if (preset.name.trim().isNotEmpty) parsed.add(preset);
        } else if (item is Map) {
          final preset = _DllPreset.fromJson(item.cast<String, dynamic>());
          if (preset.name.trim().isNotEmpty) parsed.add(preset);
        }
      }
      _dllPresets = _normalizedDllPresets(parsed);
    } catch (error) {
      _dllPresets = <_DllPreset>[];
      _dllPresetSeedVersion = 0;
      _log('settings', 'Invalid DLL presets file. Loaded no presets. $error');
    }
  }

  List<_DllPreset> _normalizedDllPresets(Iterable<_DllPreset> presets) {
    final byName = <String, _DllPreset>{};
    for (final preset in presets) {
      final name = preset.name.trim();
      if (name.isEmpty) continue;
      byName[name.toLowerCase()] = preset.copyWith(name: name);
    }
    final normalized = byName.values.toList()
      ..sort(
        (left, right) =>
            right.updatedAtEpochMs.compareTo(left.updatedAtEpochMs),
      );
    return normalized;
  }

  Future<void> _saveDllPresets(List<_DllPreset> presets) async {
    if (!_storageReady) return;
    final normalized = _normalizedDllPresets(presets);
    final payload = <String, dynamic>{
      'version': 1,
      'bundledDllPresetSeedVersion': _dllPresetSeedVersion,
      'updatedAtEpochMs': DateTime.now().millisecondsSinceEpoch,
      'presets': normalized.map((preset) => preset.toJson()).toList(),
    };
    final pretty = const JsonEncoder.withIndent('  ').convert(payload);
    await _dllPresetsFile.writeAsString(pretty, flush: true);
    _dllPresets = normalized;
    if (mounted) setState(() {});
  }

  Future<void> _ensureBundledDllPresetSeeds() async {
    if (!_storageReady) return;

    try {
      final seededPresets = await _buildBundledDllPresetSeeds();
      final nextPresets = List<_DllPreset>.from(_dllPresets);
      var changed = _dllPresetSeedVersion < _bundledDllPresetSeedVersion;

      if (_dllPresetSeedVersion < _bundledDllPresetSeedVersion) {
        final retiredAliases = _retiredBundledDefaultDllPresetAliases();
        final beforeCount = nextPresets.length;
        nextPresets.removeWhere(
          (item) => retiredAliases.contains(item.name.trim().toLowerCase()),
        );
        changed = changed || nextPresets.length != beforeCount;
      }

      for (final preset in seededPresets) {
        final aliases = _bundledDefaultDllPresetAliases(preset.name);
        final existing = nextPresets
            .where((item) => aliases.contains(item.name.trim().toLowerCase()))
            .toList();
        final existingPreset = existing.isEmpty ? null : existing.first;
        final samePaths =
            existingPreset != null &&
            _dllPresetPathsMatch(existingPreset, preset);
        final nextPreset = existingPreset == null
            ? preset
            : preset.copyWith(
                createdAtEpochMs: existingPreset.createdAtEpochMs,
                updatedAtEpochMs: samePaths
                    ? existingPreset.updatedAtEpochMs
                    : preset.updatedAtEpochMs,
              );
        final shouldReplace =
            existing.length != 1 ||
            existingPreset == null ||
            existingPreset.name.trim() != preset.name ||
            !samePaths;
        if (!shouldReplace) continue;

        nextPresets.removeWhere(
          (item) => aliases.contains(item.name.trim().toLowerCase()),
        );
        nextPresets.add(nextPreset);
        changed = true;
      }

      _dllPresetSeedVersion = _bundledDllPresetSeedVersion;
      if (changed) await _saveDllPresets(nextPresets);
    } catch (error) {
      _log('settings', 'Failed to seed bundled DLL presets: $error');
    }
  }

  bool _dllPresetPathsMatch(_DllPreset left, _DllPreset right) {
    bool samePath(String leftPath, String rightPath) {
      final leftTrimmed = leftPath.trim();
      final rightTrimmed = rightPath.trim();
      if (leftTrimmed.isEmpty || rightTrimmed.isEmpty) {
        return leftTrimmed == rightTrimmed;
      }
      if (_basename(leftTrimmed) != _basename(rightTrimmed) &&
          _bundledDllFileNameMatches(
            _basename(leftTrimmed),
            _basename(rightTrimmed),
          )) {
        return false;
      }
      return _normalizePath(leftTrimmed) == _normalizePath(rightTrimmed);
    }

    return samePath(
          left.unrealEnginePatcherPath,
          right.unrealEnginePatcherPath,
        ) &&
        samePath(
          left.authenticationPatcherPath,
          right.authenticationPatcherPath,
        ) &&
        samePath(left.memoryPatcherPath, right.memoryPatcherPath) &&
        samePath(left.gameServerFilePath, right.gameServerFilePath);
  }

  Future<List<_DllPreset>> _buildBundledDllPresetSeeds() async {
    Future<String> defaultDllPath(String fileName) {
      return _bundledDefaultDllPresetPath(_bundledDllSpecByFileName(fileName));
    }

    final memoryPath = await defaultDllPath('Memory.dll');
    final remixConsolePath = await defaultDllPath('Remix Console.dll');
    final starfallAuthPath = await defaultDllPath('Starfall.dll');
    final remixGameServerPath = await defaultDllPath('Remix.dll');
    final now = DateTime.now().millisecondsSinceEpoch;

    return <_DllPreset>[
      _DllPreset(
        name: _remixDefaultPresetName,
        createdAtEpochMs: now,
        updatedAtEpochMs: now + 2,
        unrealEnginePatcherPath: remixConsolePath,
        authenticationPatcherPath: starfallAuthPath,
        memoryPatcherPath: memoryPath,
        gameServerFilePath: remixGameServerPath,
        largePakPatcherFilePath: '',
      ),
    ];
  }

  Set<String> _bundledDefaultDllPresetAliases(String name) {
    final lowerName = name.trim().toLowerCase();
    if (lowerName == _remixDefaultPresetName.toLowerCase()) {
      return <String>{_remixDefaultPresetName.toLowerCase()};
    }
    return <String>{lowerName};
  }

  Set<String> _retiredBundledDefaultDllPresetAliases() {
    return <String>{
      'reboot ultimate gs preset',
      'reboot ultimate v1 gameserver',
      '14.40 pak authenticator',
      'retrac pak authentication',
    };
  }

  bool _isBundledDefaultDllPresetName(String name) {
    final aliases = _bundledDefaultDllPresetAliases(name);
    return aliases.contains(_remixDefaultPresetName.toLowerCase());
  }

  bool _isBundledDefaultDllPreset(_DllPreset preset) {
    return _isBundledDefaultDllPresetName(preset.name);
  }

  Future<void> _mergeSettingsSchemaIntoExistingFileIfNeeded() async {
    if (!_storageReady) return;
    if (_settingsRawFileData.isEmpty) return;
    final mergedPayload = _buildMergedSettingsPayload();
    if (_jsonDeepEquals(_settingsRawFileData, mergedPayload)) {
      return;
    }
    final pretty = const JsonEncoder.withIndent('  ').convert(mergedPayload);
    await _settingsFile.writeAsString(pretty, flush: true);
    _settingsRawFileData = Map<String, dynamic>.from(mergedPayload);
    _log(
      'settings',
      'Merged current settings schema into existing settings.json while preserving user data.',
    );
  }

  Future<void> _migrateAppearanceSettingsFileIfNeeded() async {
    final legacyAppearanceSettingsFile = File(
      _joinPath([_dataDir.path, 'appearance_settings.json']),
    );
    if (!await legacyAppearanceSettingsFile.exists()) {
      return;
    }
    try {
      final raw = await legacyAppearanceSettingsFile.readAsString();
      final decoded = jsonDecode(raw);
      final data = decoded is Map<String, dynamic>
          ? decoded
          : decoded is Map
          ? decoded.cast<String, dynamic>()
          : const <String, dynamic>{};

      double asDouble(dynamic value, double fallback) {
        if (value is num) return value.toDouble();
        if (value is String) return double.tryParse(value) ?? fallback;
        return fallback;
      }

      bool asBool(dynamic value, bool fallback) {
        if (value is bool) return value;
        if (value is num) return value != 0;
        if (value is String) {
          final lowered = value.toLowerCase();
          if (lowered == 'true' || lowered == '1') return true;
          if (lowered == 'false' || lowered == '0') return false;
        }
        return fallback;
      }

      final merged = _settings.copyWith(
        popupBackgroundBlurEnabled: asBool(
          data['popupBackgroundBlurEnabled'] ??
              data['popupBackgroundBlur'] ??
              data['PopupBackgroundBlur'],
          _settings.popupBackgroundBlurEnabled,
        ),
        discordRpcEnabled: asBool(
          data['discordRpcEnabled'] ?? data['DiscordRpcEnabled'],
          _settings.discordRpcEnabled,
        ),
        backgroundImagePath:
            (data['backgroundImagePath'] ?? data['BackgroundImagePath'] ?? '')
                .toString(),
        backgroundBlur: asDouble(
          data['backgroundBlur'] ?? data['BackgroundBlur'],
          _settings.backgroundBlur,
        ).clamp(0, 30),
        backgroundParticlesOpacity: asDouble(
          data['backgroundParticlesOpacity'] ??
              data['BackgroundParticlesOpacity'],
          _settings.backgroundParticlesOpacity,
        ).clamp(0, 2),
        startupAnimationEnabled: asBool(
          data['startupAnimationEnabled'] ?? data['StartupAnimationEnabled'],
          _settings.startupAnimationEnabled,
        ),
      );

      _settings = merged;

      await _saveSettingsSnapshot();

      try {
        await legacyAppearanceSettingsFile.delete();
      } catch (_) {
        // Ignore legacy cleanup failures.
      }

      _log(
        'settings',
        'Migrated legacy appearance_settings.json into settings.json.',
      );
    } catch (error) {
      _log(
        'settings',
        'Invalid legacy appearance settings file. Keeping current settings values. $error',
      );
    }
  }

  Future<void> _loadLauncherContent({
    bool forceRefresh = false,
    bool silent = true,
  }) async {
    if (forceRefresh) {
      await _refreshLauncherContentFromGitHub(silent: silent);
      return;
    }

    final cachedContent = await _readCachedLauncherContent();
    _applyLauncherContent(cachedContent ?? _defaultLauncherContent());

    if (!silent && mounted) {
      _toast(
        cachedContent != null
            ? 'Using cached launcher content'
            : 'Using built-in launcher content',
      );
    }

    unawaited(_refreshLauncherContentFromGitHub(silent: true));
  }

  LauncherContentConfig _defaultLauncherContent() {
    return LauncherContentConfig.defaults(
      repositoryUrl: _atlasLinkRepository,
      discordInviteUrl: _atlasLinkDiscordInvite,
    );
  }

  Map<String, dynamic>? _launcherContentJsonMap(Object? decoded) {
    if (decoded is Map<String, dynamic>) return decoded;
    if (decoded is Map) return decoded.cast<String, dynamic>();
    return null;
  }

  LauncherContentConfig _launcherContentFromMap(Map<String, dynamic> map) {
    return LauncherContentConfig.fromJson(
      map,
      repositoryUrl: _atlasLinkRepository,
      discordInviteUrl: _atlasLinkDiscordInvite,
    );
  }

  Future<LauncherContentConfig?> _readCachedLauncherContent() async {
    if (!await _launcherContentCacheFile.exists()) return null;
    try {
      final cachedRaw = await _launcherContentCacheFile.readAsString();
      final decoded = jsonDecode(cachedRaw);
      final map = _launcherContentJsonMap(decoded);
      if (map == null) return null;
      return _launcherContentFromMap(map);
    } catch (error) {
      _log(
        'content',
        'Invalid cached launcher content config. Falling back to defaults. $error',
      );
      return null;
    }
  }

  void _applyLauncherContent(LauncherContentConfig nextContent) {
    void applyContent() {
      _launcherContent = nextContent;
      if (_selectedContentTabId != null &&
          !_launcherContent.hasPage(_selectedContentTabId)) {
        _selectedContentTabId = null;
      }
      if (_settingsReturnContentTabId != null &&
          !_launcherContent.hasPage(_settingsReturnContentTabId)) {
        _settingsReturnContentTabId = null;
      }
      final slideCount = _activeLauncherContentPage.slides.length;
      if (slideCount <= 0) {
        _homeHeroIndex = 0;
      } else {
        _homeHeroIndex = _homeHeroIndex % slideCount;
      }
    }

    if (mounted) {
      setState(applyContent);
    } else {
      applyContent();
    }
    _startHomeHeroAutoRotate();
    _syncLauncherDiscordPresence();
    _queueLauncherContentImageWarmup();
  }

  void _queueLauncherContentImageWarmup() {
    if (!mounted) return;

    final sources = <String>{};

    void collectPage(LauncherContentPage page) {
      for (final slide in page.slides) {
        final resolved = _resolveLauncherContentImagePath(slide.image);
        if (resolved.isNotEmpty) sources.add(resolved);
      }
      for (final card in page.cards) {
        final resolved = _resolveLauncherContentImagePath(card.image);
        if (resolved.isNotEmpty) sources.add(resolved);
      }
    }

    collectPage(_launcherContent.homeTab);
    for (final page in _launcherContent.tabs) {
      collectPage(page);
    }

    final signature = sources.join('|');
    if (signature.isEmpty) return;
    if (_launcherContentWarmupSignature == signature) {
      if (_launcherContentWarmupInFlight != null) return;
      return;
    }

    _launcherContentWarmupSignature = signature;
    final future = () async {
      await Future<void>.delayed(const Duration(milliseconds: 40));
      if (!mounted) return;
      for (final source in sources.take(10)) {
        if (!mounted) return;
        try {
          await precacheImage(
            _launcherContentImageProvider(
              source,
              fallbackAsset: 'assets/images/missingasset.webp',
            ),
            context,
          );
        } catch (_) {
          // Ignore bad launcher content images.
        }
        await Future<void>.delayed(const Duration(milliseconds: 8));
      }
    }();

    _launcherContentWarmupInFlight = future;
    unawaited(
      future.whenComplete(() {
        if (identical(_launcherContentWarmupInFlight, future)) {
          _launcherContentWarmupInFlight = null;
        }
      }),
    );
  }

  Future<_LauncherContentRefreshOutcome> _refreshLauncherContentFromGitHub({
    bool silent = true,
  }) async {
    final inFlight = _launcherContentRefreshInFlight;
    if (inFlight != null) {
      final outcome = await inFlight;
      if (!silent && mounted) {
        _toast(_launcherContentRefreshMessage(outcome));
      }
      return outcome;
    }

    final future = () async {
      try {
        final previousCacheRaw = await _launcherContentCacheFile.exists()
            ? await _launcherContentCacheFile.readAsString()
            : null;
        final raw = await _downloadText(_launcherContentConfigUrl);
        final decoded = jsonDecode(raw);
        final map = _launcherContentJsonMap(decoded);
        if (map == null) {
          throw const FormatException(
            'Launcher content config must be a JSON object.',
          );
        }
        final nextContent = _launcherContentFromMap(map);
        final pretty = const JsonEncoder.withIndent('  ').convert(map);
        await _launcherContentCacheFile.writeAsString(pretty, flush: true);
        _applyLauncherContent(nextContent);

        final outcome = previousCacheRaw?.trim() == pretty.trim()
            ? _LauncherContentRefreshOutcome.unchanged
            : _LauncherContentRefreshOutcome.updated;
        if (!silent && mounted) {
          _toast(_launcherContentRefreshMessage(outcome));
        }
        return outcome;
      } catch (error) {
        _log(
          'content',
          'Failed to refresh launcher content from GitHub. $error',
        );
        final fallback = await _launcherContentCacheFile.exists()
            ? _LauncherContentRefreshOutcome.cacheFallback
            : _LauncherContentRefreshOutcome.defaultsFallback;
        if (!silent && mounted) {
          _toast(_launcherContentRefreshMessage(fallback));
        }
        return fallback;
      }
    }();

    _launcherContentRefreshInFlight = future;
    try {
      return await future;
    } finally {
      if (identical(_launcherContentRefreshInFlight, future)) {
        _launcherContentRefreshInFlight = null;
      }
    }
  }

  String _launcherContentRefreshMessage(
    _LauncherContentRefreshOutcome outcome,
  ) {
    switch (outcome) {
      case _LauncherContentRefreshOutcome.updated:
        return 'Launcher content updated';
      case _LauncherContentRefreshOutcome.unchanged:
        return 'Launcher content is up to date';
      case _LauncherContentRefreshOutcome.cacheFallback:
        return 'Using cached launcher content';
      case _LauncherContentRefreshOutcome.defaultsFallback:
        return 'Using built-in launcher content';
    }
  }

  Future<String> _downloadText(String url) async {
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 8)
      ..userAgent = 'ATLAS-Link';
    try {
      final request = await client.getUrl(Uri.parse(url));
      request.followRedirects = true;
      request.maxRedirects = 8;
      final response = await request.close();
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw 'HTTP ${response.statusCode}';
      }
      final body = await response.transform(utf8.decoder).join();
      return body;
    } finally {
      client.close(force: true);
    }
  }

  Future<void> _saveProfileSettings() async {
    final useEmailPasswordAuth = _settings.profileUseEmailPasswordAuth;
    final trimmedEmail = _profileAuthEmailController.text.trim();
    final rawPassword = _profileAuthPasswordController.text;
    final validationError = _profileAuthValidationError(
      useEmailPassword: useEmailPasswordAuth,
      email: trimmedEmail,
      password: rawPassword,
    );
    if (validationError != null) {
      if (mounted) {
        setState(() => _profileAuthValidationAttempted = true);
      } else {
        _profileAuthValidationAttempted = true;
      }
      _toast(validationError);
      return;
    }

    final resolvedUsername = useEmailPasswordAuth
        ? _usernameFromEmail(trimmedEmail)
        : _usernameController.text.trim();
    final nextUsername = resolvedUsername.isEmpty ? 'Player' : resolvedUsername;

    if (mounted) {
      setState(() {
        _setActiveSettingsUsername(nextUsername);
        _usernameController.text = _settings.username;
        _settings = _settings.copyWith(
          profileAuthEmail: useEmailPasswordAuth ? trimmedEmail : '',
          profileAuthPassword: useEmailPasswordAuth ? rawPassword : '',
        );
        _profileAuthValidationAttempted = false;
      });
    } else {
      _setActiveSettingsUsername(nextUsername);
      _usernameController.text = _settings.username;
      _settings = _settings.copyWith(
        profileAuthEmail: useEmailPasswordAuth ? trimmedEmail : '',
        profileAuthPassword: useEmailPasswordAuth ? rawPassword : '',
      );
      _profileAuthValidationAttempted = false;
    }

    await _saveSettings(applyControllers: false);
  }

  Future<void> _saveSettings({
    bool toast = true,
    bool applyControllers = true,
  }) async {
    if (applyControllers) _applyControllers();
    await _saveSettingsSnapshot();
    _log('settings', 'Settings saved.');
    if (!mounted) return;
    setState(() {});
    if (toast) _toast('Settings saved');
  }

  Map<String, dynamic> _buildMergedSettingsPayload() {
    final payload = <String, dynamic>{}..addAll(_settingsRawFileData);
    payload.removeWhere(
      (key, _) => LauncherSettings.recognizedJsonKeys.contains(key),
    );
    payload.addAll(_settings.toJson());
    return payload;
  }

  Future<void> _saveSettingsSnapshot() async {
    if (!_storageReady) return;
    _syncSavedBackendsForActiveProfile();
    _settings = _settingsWithSynchronizedOverallPlaytime(_settings);
    final payload = _buildMergedSettingsPayload();
    final pretty = const JsonEncoder.withIndent('  ').convert(payload);
    await _settingsFile.writeAsString(pretty, flush: true);
    _settingsRawFileData = Map<String, dynamic>.from(payload);
  }

  void _saveSettingsSnapshotSync() {
    if (!_storageReady) return;
    _syncSavedBackendsForActiveProfile();
    _settings = _settingsWithSynchronizedOverallPlaytime(_settings);
    final payload = _buildMergedSettingsPayload();
    final pretty = const JsonEncoder.withIndent('  ').convert(payload);
    try {
      _settingsFile.writeAsStringSync(pretty, flush: true);
      _settingsRawFileData = Map<String, dynamic>.from(payload);
    } catch (_) {
      // Ignore shutdown save failures.
    }
  }

  bool _jsonDeepEquals(dynamic left, dynamic right) {
    if (identical(left, right)) return true;
    if (left is Map && right is Map) {
      if (left.length != right.length) return false;
      for (final key in left.keys) {
        if (!right.containsKey(key)) return false;
        if (!_jsonDeepEquals(left[key], right[key])) return false;
      }
      return true;
    }
    if (left is List && right is List) {
      if (left.length != right.length) return false;
      for (var index = 0; index < left.length; index++) {
        if (!_jsonDeepEquals(left[index], right[index])) return false;
      }
      return true;
    }
    return left == right;
  }

  Map<String, List<SavedBackend>> _cloneSavedBackendsByProfile({
    Map<String, List<SavedBackend>>? source,
  }) {
    final original = source ?? _settings.savedBackendsByProfile;
    final cloned = <String, List<SavedBackend>>{};
    for (final entry in original.entries) {
      final normalizedKey = LauncherSettings.profileBackendsKey(entry.key);
      cloned[normalizedKey] = List<SavedBackend>.from(entry.value);
    }
    return cloned;
  }

  LauncherSettings _settingsWithSavedBackendsForActiveProfile(
    List<SavedBackend> backends,
  ) {
    final normalizedBackends = List<SavedBackend>.from(backends);
    final scopedBackends = _cloneSavedBackendsByProfile();
    final profileKey = LauncherSettings.profileBackendsKey(_settings.username);
    scopedBackends[profileKey] = normalizedBackends;
    return _settings.copyWith(
      savedBackends: normalizedBackends,
      savedBackendsByProfile: scopedBackends,
    );
  }

  void _syncSavedBackendsForActiveProfile() {
    _settings = _settingsWithSavedBackendsForActiveProfile(
      _settings.savedBackends,
    );
  }

  void _setActiveSettingsUsername(String username) {
    final resolvedUsername = username.trim().isEmpty
        ? 'Player'
        : username.trim();
    final currentProfileKey = LauncherSettings.profileBackendsKey(
      _settings.username,
    );
    final nextProfileKey = LauncherSettings.profileBackendsKey(
      resolvedUsername,
    );
    final scopedBackends = _cloneSavedBackendsByProfile();
    final currentBackends = List<SavedBackend>.from(_settings.savedBackends);
    scopedBackends[currentProfileKey] = currentBackends;

    final nextBackends = currentProfileKey == nextProfileKey
        ? currentBackends
        : List<SavedBackend>.from(
            scopedBackends[nextProfileKey] ?? const <SavedBackend>[],
          );

    _settings = _settings.copyWith(
      username: resolvedUsername,
      savedBackends: nextBackends,
      savedBackendsByProfile: scopedBackends,
    );
  }

  void _syncControllers() {
    _usernameController.text = _settings.username;
    _profileAuthEmailController.text = _settings.profileAuthEmail;
    _profileAuthPasswordController.text = _settings.profileAuthPassword;
    _backendDirController.text = _settings.backendWorkingDirectory;
    _backendCommandController.text = _settings.backendStartCommand;
    _backendHostController.text =
        _settings.backendConnectionType == BackendConnectionType.remote
        ? _settings.remoteBackendHost
        : '';
    _backendPortController.text = _effectiveBackendPort().toString();
    _unrealEnginePatcherController.text = _settings.unrealEnginePatcherPath;
    _authenticationPatcherController.text = _settings.authenticationPatcherPath;
    _memoryPatcherController.text = _settings.memoryPatcherPath;
    _gameServerFileController.text = _settings.gameServerFilePath;
  }

  void _persistBackendFieldsFromControllers() {
    final parsedPort =
        int.tryParse(_backendPortController.text.trim()) ?? _defaultBackendPort;
    if (_settings.backendConnectionType == BackendConnectionType.embedded) {
      _settings = _settings.copyWith(
        backendHost: _defaultBackendHost,
        backendPort: _settings.embeddedBackendType.defaultPort,
      );
      return;
    }
    if (_settings.backendConnectionType == BackendConnectionType.local) {
      _settings = _settings.copyWith(
        localBackendPort: parsedPort.clamp(1, 65535),
        backendHost: _defaultBackendHost,
        backendPort: parsedPort.clamp(1, 65535),
      );
      return;
    }

    final normalizedRemoteHost = _backendHostController.text.trim();
    _settings = _settings.copyWith(
      remoteBackendHost: normalizedRemoteHost,
      remoteBackendPort: parsedPort.clamp(1, 65535),
      backendHost: normalizedRemoteHost,
      backendPort: parsedPort.clamp(1, 65535),
    );
  }

  void _applyControllers() {
    _persistBackendFieldsFromControllers();
    _settings = _settings.copyWith(
      backendWorkingDirectory: _backendDirController.text.trim(),
      backendStartCommand: _backendCommandController.text.trim(),
    );
  }

  String _effectiveBackendHost() {
    if (_settings.backendConnectionType != BackendConnectionType.remote) {
      return _defaultBackendHost;
    }
    final host = _settings.remoteBackendHost.trim();
    if (host.isEmpty) {
      return '';
    }
    return host;
  }

  int _effectiveBackendPort() {
    final port = switch (_settings.backendConnectionType) {
      BackendConnectionType.local => _settings.localBackendPort,
      BackendConnectionType.embedded =>
        _settings.embeddedBackendType.defaultPort,
      BackendConnectionType.remote => _settings.remoteBackendPort,
    };
    return port > 0 ? port : _defaultBackendPort;
  }

  int _localBackendPortAfterLeavingEmbedded() {
    final port = _settings.localBackendPort;
    if (port <= 0 || port > 65535) return _defaultBackendPort;
    if (_settings.backendConnectionType == BackendConnectionType.embedded &&
        port == _settings.embeddedBackendType.defaultPort &&
        port != _defaultBackendPort) {
      return _defaultBackendPort;
    }
    return port;
  }

  int _effectiveGameServerPort() {
    final port = _settings.hostPort;
    if (port <= 0 || port > 65535) return _defaultGameServerPort;
    return port;
  }

  VersionEntry? _findVersionById(String versionId) {
    for (final version in _settings.versions) {
      if (version.id == versionId) return version;
    }
    return null;
  }

  Iterable<_FortniteProcessState> _runningGameClients() sync* {
    final primary = _gameInstance;
    if (primary != null && !primary.host && !primary.killed) {
      yield primary;
    }
    for (final client in _extraGameInstances) {
      if (!client.host && !client.killed) {
        yield client;
      }
    }
  }

  bool get _hasRunningGameClient => _runningGameClients().isNotEmpty;

  List<VersionEntry> _activeTrackedVersions() {
    final seenVersionIds = <String>{};
    final activeVersions = <VersionEntry>[];
    for (final client in _runningGameClients()) {
      if (!seenVersionIds.add(client.versionId)) continue;
      final version = _findVersionById(client.versionId);
      if (version != null) activeVersions.add(version);
    }
    return activeVersions;
  }

  bool _hasRunningClientForVersion(String versionId) {
    for (final client in _runningGameClients()) {
      if (client.versionId == versionId) return true;
    }
    return false;
  }

  bool _isVersionRunning(String versionId) {
    final id = versionId.trim();
    if (id.isEmpty) return false;
    if (_settings.selectedVersionId == id &&
        (_gameAction == _GameActionState.launching || _gameServerLaunching)) {
      return true;
    }
    if (_hasRunningClientForVersion(id)) return true;
    final host = _gameServerInstance;
    return host != null && !host.killed && host.versionId == id;
  }

  void _recordGameplaySessionStart(String versionId) {
    final now = DateTime.now();
    _atlasPlaySessionStartedAt ??= now;
    _activeVersionPlaySessions.putIfAbsent(versionId, () => now);
    _syncPlaytimeCheckpointTimer();
  }

  LauncherSettings _withRecordedVersionPlaytime(
    LauncherSettings settings,
    String versionId, {
    required int additionalSeconds,
    required int lastPlayedAtEpochMs,
  }) {
    var updated = false;
    final versions = settings.versions.map((version) {
      if (version.id != versionId) return version;
      updated = true;
      return version.copyWith(
        playTimeSeconds: max(0, version.playTimeSeconds + additionalSeconds),
        lastPlayedAtEpochMs: lastPlayedAtEpochMs,
      );
    }).toList();

    return updated ? settings.copyWith(versions: versions) : settings;
  }

  int _persistedTrackedVersionPlaySeconds([LauncherSettings? settings]) {
    final source = settings ?? _settings;
    var total = 0;
    for (final version in source.versions) {
      total += max(0, version.playTimeSeconds);
    }
    return total;
  }

  LauncherSettings _settingsWithSynchronizedOverallPlaytime(
    LauncherSettings settings,
  ) {
    final combinedVersionSeconds = _persistedTrackedVersionPlaySeconds(
      settings,
    );
    if (settings.totalAtlasPlaySeconds == combinedVersionSeconds) {
      return settings;
    }
    return settings.copyWith(totalAtlasPlaySeconds: combinedVersionSeconds);
  }

  void _recordGameplaySessionEnd(String versionId) {
    final endedAt = DateTime.now();
    var nextSettings = _settings;

    final versionSessionStartedAt = _activeVersionPlaySessions[versionId];
    if (versionSessionStartedAt != null &&
        !_hasRunningClientForVersion(versionId)) {
      _activeVersionPlaySessions.remove(versionId);
      nextSettings = _withRecordedVersionPlaytime(
        nextSettings,
        versionId,
        additionalSeconds: max(
          0,
          endedAt.difference(versionSessionStartedAt).inSeconds,
        ),
        lastPlayedAtEpochMs: endedAt.millisecondsSinceEpoch,
      );
    }

    if (_atlasPlaySessionStartedAt != null && !_hasRunningGameClient) {
      _atlasPlaySessionStartedAt = null;
    }
    nextSettings = _settingsWithSynchronizedOverallPlaytime(nextSettings);

    if (identical(nextSettings, _settings)) {
      _syncPlaytimeCheckpointTimer();
      return;
    }

    if (mounted) {
      setState(() => _settings = nextSettings);
    } else {
      _settings = nextSettings;
    }
    _syncPlaytimeCheckpointTimer();
    unawaited(_saveSettings(toast: false, applyControllers: false));
  }

  void _syncPlaytimeCheckpointTimer() {
    final shouldRun = _activeVersionPlaySessions.isNotEmpty;
    if (!shouldRun) {
      _playtimeCheckpointTimer?.cancel();
      _playtimeCheckpointTimer = null;
      return;
    }

    _playtimeCheckpointTimer ??= Timer.periodic(
      _playtimeCheckpointInterval,
      (_) => _checkpointActivePlaytime(),
    );
  }

  void _checkpointActivePlaytime({bool syncSave = false}) {
    if (!_storageReady) return;

    final now = DateTime.now();
    var nextSettings = _settings;
    var changed = false;

    final activeVersionIds = _activeVersionPlaySessions.keys.toList();
    for (final versionId in activeVersionIds) {
      final startedAt = _activeVersionPlaySessions[versionId];
      if (startedAt == null) continue;
      if (!_hasRunningClientForVersion(versionId)) continue;

      final elapsedSeconds = max(0, now.difference(startedAt).inSeconds);
      if (elapsedSeconds == 0) continue;

      nextSettings = _withRecordedVersionPlaytime(
        nextSettings,
        versionId,
        additionalSeconds: elapsedSeconds,
        lastPlayedAtEpochMs: now.millisecondsSinceEpoch,
      );
      _activeVersionPlaySessions[versionId] = now;
      changed = true;
    }

    final synchronizedSettings = _settingsWithSynchronizedOverallPlaytime(
      nextSettings,
    );
    if (synchronizedSettings.totalAtlasPlaySeconds !=
        nextSettings.totalAtlasPlaySeconds) {
      nextSettings = synchronizedSettings;
      changed = true;
    }

    if (changed) {
      _settings = nextSettings;
      if (syncSave) {
        _saveSettingsSnapshotSync();
      } else {
        unawaited(_saveSettingsSnapshot());
      }
    }

    _syncPlaytimeCheckpointTimer();
  }

  int _effectiveTotalAtlasPlaySeconds() {
    var total = 0;
    for (final version in _settings.versions) {
      total += _effectiveVersionPlaySeconds(version);
    }
    return total;
  }

  int _effectiveVersionPlaySeconds(VersionEntry version) {
    final startedAt = _activeVersionPlaySessions[version.id];
    if (startedAt == null) return version.playTimeSeconds;
    return version.playTimeSeconds +
        max(0, DateTime.now().difference(startedAt).inSeconds);
  }

  bool _hasTrackedPlaytime(VersionEntry version) {
    return version.playTimeSeconds > 0 ||
        version.lastPlayedAtEpochMs > 0 ||
        _activeVersionPlaySessions.containsKey(version.id);
  }

  String _formatTrackedPlaytime(int totalSeconds) {
    final seconds = max(0, totalSeconds);
    final days = seconds ~/ 86400;
    final hours = (seconds % 86400) ~/ 3600;
    final minutes = (seconds % 3600) ~/ 60;
    final remainingSeconds = seconds % 60;

    if (days > 0) {
      return hours > 0 ? '${days}d ${hours}h' : '${days}d';
    }
    if (hours > 0) {
      return minutes > 0 ? '${hours}h ${minutes}m' : '${hours}h';
    }
    if (minutes > 0) {
      return remainingSeconds > 0
          ? '${minutes}m ${remainingSeconds}s'
          : '${minutes}m';
    }
    return '${remainingSeconds}s';
  }

  String _monthAbbreviation(int month) {
    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    if (month < 1 || month > 12) return 'Unknown';
    return months[month - 1];
  }

  String _formatVersionLastPlayed(VersionEntry version) {
    if (_activeVersionPlaySessions.containsKey(version.id)) {
      return 'Tracking live session';
    }
    if (version.lastPlayedAtEpochMs <= 0) return 'Not played yet';

    final playedAt = DateTime.fromMillisecondsSinceEpoch(
      version.lastPlayedAtEpochMs,
    );
    final now = DateTime.now();
    final playedDate = DateTime(playedAt.year, playedAt.month, playedAt.day);
    final today = DateTime(now.year, now.month, now.day);
    final difference = today.difference(playedDate).inDays;

    if (difference <= 0) return 'Last played today';
    if (difference == 1) return 'Last played yesterday';
    if (difference < 7) return 'Last played $difference days ago';
    return 'Last played ${_monthAbbreviation(playedAt.month)} '
        '${playedAt.day}, ${playedAt.year}';
  }

  Set<String> _activeGameClientNames() {
    final names = <String>{};
    for (final client in _runningGameClients()) {
      names.add(client.clientName.toLowerCase());
    }
    return names;
  }

  String _timeGreeting() {
    final hour = DateTime.now().hour;
    if (hour < 12) return 'Good morning';
    if (hour < 18) return 'Good afternoon';
    return 'Good evening';
  }

  Future<void> _setBackendConnectionType(BackendConnectionType type) async {
    if (_settings.backendConnectionType == type) return;
    final switchingAwayFromEmbedded =
        _settings.backendConnectionType == BackendConnectionType.embedded &&
        type != BackendConnectionType.embedded;
    if (switchingAwayFromEmbedded && _atlasBackendProcess != null) {
      await _stopManagedBackend(showToast: false);
    } else if (switchingAwayFromEmbedded) {
      await _stopBackendTerminalWindow();
      await _cleanupOrphanedEmbeddedBackendProcesses(force: true);
      await _stopBackendProxy();
      _setBackendOffline(toastIfChanged: false);
    }

    _persistBackendFieldsFromControllers();
    setState(() {
      final port = type == BackendConnectionType.embedded
          ? _settings.embeddedBackendType.defaultPort
          : type == BackendConnectionType.remote
          ? _settings.remoteBackendPort
          : _localBackendPortAfterLeavingEmbedded();
      _settings = _settings.copyWith(
        backendConnectionType: type,
        backendHost: type == BackendConnectionType.remote
            ? _settings.remoteBackendHost
            : _defaultBackendHost,
        backendPort: port,
        localBackendPort: type == BackendConnectionType.local
            ? port
            : _settings.localBackendPort,
      );
      if (type == BackendConnectionType.embedded) {
        _backendOnline = false;
      }
      _backendHostController.text = type == BackendConnectionType.remote
          ? _settings.remoteBackendHost
          : '';
      _backendPortController.text = _effectiveBackendPort().toString();
    });
    await _saveSettings(toast: false);
    await _refreshRuntime();
  }

  Future<void> _setEmbeddedBackendType(EmbeddedBackendType type) async {
    if (_atlasBackendProcess != null || _backendActionBusy) {
      if (mounted) {
        _toast('Stop the running embedded backend before switching backends');
      }
      return;
    }
    if (_settings.embeddedBackendType == type) return;

    final port = type.defaultPort;
    setState(() {
      _settings = _settings.copyWith(
        backendConnectionType: BackendConnectionType.embedded,
        embeddedBackendType: type,
        backendHost: _defaultBackendHost,
        backendPort: port,
      );
      _backendOnline = false;
      _backendHostController.text = '';
      _backendPortController.text = port.toString();
    });
    await _saveSettings(toast: false, applyControllers: false);
    await _refreshRuntime(force: true);
  }

  String _two(int value) => value.toString().padLeft(2, '0');

  void _log(String source, String message) {
    final now = DateTime.now();
    final line =
        '[${_two(now.hour)}:${_two(now.minute)}:${_two(now.second)}] [${source.toUpperCase()}] $message';
    // Never call setState here. During launch Fortnite can spew a lot of log
    // lines; rebuilding the entire UI for each line causes jank.
    _logs.addFirst(line);
    while (_logs.length > _maxLogLines) {
      _logs.removeLast();
    }

    if (_logFileReady) {
      _logWriteBuffer.writeln(line);
      _scheduleLogFlush();
    }
  }

  void _scheduleLogFlush() {
    if (_logFlushTimer != null) return;
    _logFlushTimer = Timer(const Duration(milliseconds: 250), () {
      _logFlushTimer = null;
      _flushLogBuffer();
    });
  }

  void _flushLogBuffer() {
    if (!_logFileReady) return;
    if (_logWriteBuffer.length == 0) return;

    final chunk = _logWriteBuffer.toString();
    _logWriteBuffer.clear();

    _logWriteChain = _logWriteChain.then((_) async {
      try {
        await _logFile.writeAsString(chunk, mode: FileMode.append);
      } catch (_) {
        // Ignore log write failures.
      }
    });
  }

  Future<void> _refreshRuntime({bool force = false}) async {
    if (!force && _deferNonCriticalRuntimeRefresh()) return;

    final inFlight = _runtimeRefreshInFlight;
    if (inFlight != null) {
      await inFlight;
      return;
    }

    final completer = Completer<void>();
    _runtimeRefreshInFlight = completer.future;
    try {
      if (_settings.backendConnectionType == BackendConnectionType.embedded) {
        final process = _atlasBackendProcess;
        if (process == null) {
          await _stopBackendProxy();
          _setBackendOffline(toastIfChanged: false);
          return;
        }
        final exitCode = await _tryProcessExitCode(process);
        if (exitCode != null) {
          if (identical(_atlasBackendProcess, process)) {
            _atlasBackendProcess = null;
          }
          await _stopBackendProxy();
          _setBackendOffline(toastIfChanged: false);
          return;
        }

        final embeddedPing = await _pingBackend(
          _defaultBackendHost,
          _effectiveBackendPort(),
        );
        if (embeddedPing == null) {
          await _stopBackendProxy();
          _setBackendOffline(toastIfChanged: false);
          return;
        }
      } else {
        await _cleanupOrphanedEmbeddedBackendProcesses(force: true);
      }

      final proxyOk = await _syncBackendProxy();
      if (!proxyOk) {
        _setBackendOffline(toastIfChanged: true);
        return;
      }

      final uri = Uri(
        scheme: 'http',
        host: _defaultBackendHost,
        port: _defaultBackendPort,
        path: 'unknown',
      );

      final client = HttpClient()
        ..connectionTimeout = const Duration(seconds: 3)
        ..autoUncompress = false;
      try {
        final req = await client.getUrl(uri);
        await req.close();
        if (mounted) {
          if (!_backendOnline) {
            setState(() {
              // Match Reboot: any completed HTTP response means the backend
              // endpoint is reachable, regardless of status code.
              _backendOnline = true;
            });
          }
        }
      } catch (_) {
        _setBackendOffline(toastIfChanged: true);
      } finally {
        client.close(force: true);
      }
    } finally {
      if (!completer.isCompleted) {
        completer.complete();
      }
      _runtimeRefreshInFlight = null;
    }
  }

  void _setBackendOffline({required bool toastIfChanged}) {
    final wasOnline = _backendOnline;
    if (mounted) {
      if (wasOnline) {
        setState(() => _backendOnline = false);
      }
    } else {
      _backendOnline = false;
    }
    if (toastIfChanged && wasOnline) _toastBackendUndetected();
  }

  void _toastBackendUndetected() {
    if (!mounted) return;

    final now = DateTime.now();
    final lastAt = _lastBackendUndetectedToastAt;
    if (lastAt != null && now.difference(lastAt).inSeconds < 10) {
      return;
    }
    _lastBackendUndetectedToastAt = now;

    final configured = '${_effectiveBackendHost()}:${_effectiveBackendPort()}';
    _toast('Backend undetected on $configured');
  }

  bool _backendProxyRequired() {
    return BackendProxyRouting.proxyRequired(
      connectionType: _settings.backendConnectionType,
      host: _effectiveBackendHost(),
      port: _effectiveBackendPort(),
    );
  }

  bool _isDefaultBackendEndpoint(String host, int port) {
    return BackendProxyRouting.isDefaultBackendEndpoint(host, port);
  }

  Future<bool> _syncBackendProxy() async {
    final inFlight = _backendProxySyncInFlight;
    if (inFlight != null) {
      await inFlight;
      return _backendProxyRequired()
          ? _backendProxyServer != null && _backendProxyTarget != null
          : true;
    }

    final completer = Completer<void>();
    _backendProxySyncInFlight = completer.future;
    try {
      if (!_backendProxyRequired()) {
        await _stopBackendProxy();
        return true;
      }

      final signature =
          '${_settings.backendConnectionType.name}|${_effectiveBackendHost()}|${_effectiveBackendPort()}';
      if (_backendProxyServer != null &&
          _backendProxyTarget != null &&
          _backendProxySignature == signature) {
        final target = await _resolveBackendProxyTarget();
        if (target == null) {
          _log(
            'backend',
            'Backend proxy target no longer reachable: ${_effectiveBackendHost()}:${_effectiveBackendPort()}',
          );
          await _stopBackendProxy();
          return false;
        }
        _backendProxyTarget = target;
        return true;
      }

      await _stopBackendProxy();

      final target = await _resolveBackendProxyTarget();
      if (target == null) {
        _log(
          'backend',
          'Backend unreachable: ${_effectiveBackendHost()}:${_effectiveBackendPort()}',
        );
        return false;
      }

      final server = await _bindBackendProxyServer();
      if (server == null) return false;

      _backendProxyClient = HttpClient()
        ..connectionTimeout = const Duration(seconds: 10)
        ..autoUncompress = false;
      _backendProxyServer = server;
      _backendProxyTarget = target;
      _backendProxySignature = signature;

      server.listen(
        (request) => unawaited(_handleBackendProxyRequest(request)),
        onError: (error, stackTrace) {
          _log('backend', 'Proxy server error: $error');
        },
      );

      _log(
        'backend',
        'Proxy started http://$_defaultBackendHost:$_defaultBackendPort -> $target',
      );
      return true;
    } finally {
      _backendProxySyncInFlight = null;
      completer.complete();
    }
  }

  Future<HttpServer?> _bindBackendProxyServer() async {
    Future<HttpServer?> tryBind() async {
      try {
        return await HttpServer.bind(
          InternetAddress.loopbackIPv4,
          _defaultBackendPort,
        );
      } on SocketException {
        return null;
      }
    }

    var server = await tryBind();
    if (server != null) return server;

    // Free the default backend port and try again.
    await _killExistingProcessByPort(_defaultBackendPort, exceptPid: pid);
    await Future.delayed(const Duration(milliseconds: 200));
    server = await tryBind();
    if (server == null) {
      _log(
        'backend',
        'Unable to bind backend proxy on port $_defaultBackendPort',
      );
      if (mounted) _toast('Port $_defaultBackendPort is already in use');
    }
    return server;
  }

  Future<Uri?> _resolveBackendProxyTarget() async {
    final host = _effectiveBackendHost().trim();
    final port = _effectiveBackendPort();

    if (_settings.backendConnectionType != BackendConnectionType.remote) {
      if (port == _defaultBackendPort) {
        return Uri(scheme: 'http', host: _defaultBackendHost, port: port);
      }
      final ping = await _pingBackend(_defaultBackendHost, port);
      return ping;
    }

    if (host.isEmpty) return null;
    final ping = await _pingBackend(host, port);
    if (ping == null) return null;
    return Uri(scheme: ping.scheme, host: ping.host, port: ping.port);
  }

  bool _isLocalHost(String host) {
    return BackendProxyRouting.isLocalHost(host);
  }

  Future<Uri?> _pingBackend(String host, int port, [bool https = false]) async {
    final trimmed = host.trim();
    final hostName = trimmed
        .replaceFirst(RegExp(r'^http://', caseSensitive: false), '')
        .replaceFirst(RegExp(r'^https://', caseSensitive: false), '');
    final declaredScheme = trimmed.toLowerCase().startsWith('http://')
        ? 'http'
        : trimmed.toLowerCase().startsWith('https://')
        ? 'https'
        : null;
    final uri = Uri(
      scheme: declaredScheme ?? (https ? 'https' : 'http'),
      host: hostName,
      port: port,
      path: 'unknown',
    );

    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 6)
      ..autoUncompress = false;
    try {
      final request = await client.getUrl(uri);
      await request.close().timeout(const Duration(seconds: 6));
      return uri;
    } catch (_) {
      if (https || declaredScheme != null || _isLocalHost(hostName)) {
        return null;
      }
      return _pingBackend(host, port, true);
    } finally {
      client.close(force: true);
    }
  }

  Future<void> _handleBackendProxyRequest(HttpRequest request) async {
    final targetBase = _backendProxyTarget;
    final client = _backendProxyClient;
    if (targetBase == null || client == null) {
      request.response.statusCode = HttpStatus.serviceUnavailable;
      await request.response.close();
      return;
    }
    if (_isDefaultBackendEndpoint(targetBase.host, targetBase.port)) {
      request.response.statusCode = HttpStatus.badGateway;
      request.response.write('Backend proxy self-target blocked.');
      await request.response.close();
      _log('backend', 'Blocked backend proxy self-target: $targetBase');
      return;
    }

    final targetUri = targetBase.replace(
      path: request.uri.path,
      query: request.uri.hasQuery ? request.uri.query : null,
    );

    try {
      final outbound = await client.openUrl(request.method, targetUri);
      outbound.followRedirects = false;

      request.headers.forEach((name, values) {
        final lower = name.toLowerCase();
        if (lower == 'host' ||
            lower == 'content-length' ||
            lower == 'connection') {
          return;
        }
        for (final value in values) {
          outbound.headers.add(name, value);
        }
      });

      await outbound.addStream(request);
      final response = await outbound.close();

      request.response.statusCode = response.statusCode;
      response.headers.forEach((name, values) {
        final lower = name.toLowerCase();
        if (lower == 'transfer-encoding' || lower == 'connection') return;
        for (final value in values) {
          request.response.headers.add(name, value);
        }
      });

      await response.pipe(request.response);
    } catch (error) {
      request.response.statusCode = HttpStatus.badGateway;
      request.response.write('Backend proxy error.');
      await request.response.close();
    }
  }

  Future<void> _stopBackendProxy() async {
    final server = _backendProxyServer;
    _backendProxyServer = null;
    _backendProxyTarget = null;
    _backendProxySignature = null;
    final client = _backendProxyClient;
    _backendProxyClient = null;
    client?.close(force: true);
    if (server != null) {
      try {
        await server.close(force: true);
        _log('backend', 'Proxy stopped.');
      } catch (_) {
        // Ignore.
      }
    }
  }

  Future<void> _handleRefreshPressed() async {
    await _refreshRuntime();
    // Run each check silently and surface a single result so the button never
    // stacks several toasts ("No updates available" + "Files are up to date").
    await _loadLauncherContent(forceRefresh: true, silent: true);
    var launcherUpdateShown = false;
    if (_settings.launcherUpdateChecksEnabled) {
      launcherUpdateShown = await _checkForLauncherUpdates(silent: true);
    }
    // When a launcher update dialog is showing, that's the message — skip the
    // file-status toast so it doesn't appear behind the dialog.
    await _checkForFileUpdates(silent: launcherUpdateShown);
  }

  /// Manual "Check For Updates" for launcher-managed files: bundled default
  /// DLLs plus installed Paks and library DLLs. Refreshes both sources and
  /// reports a single result so the badges reflect what's available.
  Future<void> _checkForFileUpdates({required bool silent}) async {
    await _checkForBundledDllDefaultUpdates(silent: true, forceRefresh: true);
    try {
      await _loadModsLibrary(forceRefresh: true, silentRefreshToast: true);
    } catch (error) {
      _log('mods', 'Failed to refresh mod catalog during update check: $error');
    }
    if (silent || !mounted) return;
    if (_bundledDllDefaultsUpdateAvailable || _hasAtlasModUpdates) {
      _toast('File updates are available');
    } else {
      _toast('Files are up to date');
    }
  }

  String _resolveLauncherContentImagePath(String value) {
    final trimmed = value.trim();
    if (trimmed.isEmpty) return '';
    final normalized = trimmed.replaceAll('\\', '/');
    final lower = normalized.toLowerCase();
    if (normalized.startsWith('assets/')) return normalized;
    if (lower.startsWith('http://') || lower.startsWith('https://')) {
      return normalized;
    }
    final isAbsoluteWindowsPath = RegExp(r'^[a-zA-Z]:/').hasMatch(normalized);
    if (isAbsoluteWindowsPath ||
        normalized.startsWith('/') ||
        normalized.startsWith('//')) {
      return trimmed;
    }
    final relative = normalized.replaceFirst(RegExp(r'^/+'), '');
    final strippedImagesPrefix = relative.startsWith('images/')
        ? relative.substring('images/'.length)
        : relative;
    return '$_launcherContentAssetBaseUrl$strippedImagesPrefix';
  }

  ImageProvider<Object> _launcherContentImageProvider(
    String source, {
    required String fallbackAsset,
  }) {
    final resolved = _resolveLauncherContentImagePath(source);
    if (resolved.isEmpty) return AssetImage(fallbackAsset);
    final lower = resolved.toLowerCase();
    if (lower.startsWith('http://') || lower.startsWith('https://')) {
      return NetworkImage(resolved);
    }
    if (resolved.startsWith('assets/')) {
      return AssetImage(resolved);
    }
    final file = File(resolved);
    if (file.existsSync()) {
      return FileImage(file);
    }
    return AssetImage(fallbackAsset);
  }

  IconData _launcherContentIcon(String value) {
    switch (value.trim().toLowerCase()) {
      case 'home':
      case 'home_outlined':
        return Icons.home_outlined;
      case 'folder':
      case 'folder_open_outlined':
      case 'library':
        return Icons.folder_open_outlined;
      case 'cloud':
      case 'cloud_outlined':
      case 'backend':
        return Icons.cloud_outlined;
      case 'campaign':
      case 'campaign_outlined':
        return Icons.campaign_outlined;
      case 'public':
      case 'public_rounded':
        return Icons.public_rounded;
      case 'bolt':
      case 'bolt_rounded':
        return Icons.bolt_rounded;
      case 'forum':
      case 'forum_outlined':
        return Icons.forum_outlined;
      case 'image':
      case 'image_outlined':
        return Icons.image_outlined;
      case 'sports_esports':
      case 'sports_esports_rounded':
        return Icons.sports_esports_rounded;
      case 'newspaper':
      case 'newspaper_rounded':
        return Icons.newspaper_rounded;
      case 'storefront':
      case 'storefront_rounded':
        return Icons.storefront_rounded;
      case 'web':
      case 'web_rounded':
        return Icons.web_rounded;
      default:
        return Icons.layers_outlined;
    }
  }

  /// Returns true if an update was found and its dialog was shown.
  Future<bool> _checkForLauncherUpdates({required bool silent}) async {
    if (!_settings.launcherUpdateChecksEnabled) return false;
    if (_checkingLauncherUpdate) return false;
    if (_launcherUpdateDialogVisible) return false;
    _checkingLauncherUpdate = true;
    try {
      final info = await LauncherUpdateService.checkForUpdate(
        currentVersion: _launcherVersion,
      );
      if (!mounted) return false;
      if (info == null) {
        if (!silent) _toast('No updates available');
        return false;
      }
      await _showLauncherUpdateDialog(info);
      return true;
    } catch (_) {
      if (mounted && !silent) {
        _toast('Unable to check for updates right now');
      }
      return false;
    } finally {
      _checkingLauncherUpdate = false;
    }
  }

  Widget _buildVersionTag(
    BuildContext context, {
    required String label,
    required Color accent,
  }) {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(999),
        color: accent.withValues(alpha: 0.2),
        border: Border.all(color: accent.withValues(alpha: 0.55)),
      ),
      child: Text(
        label,
        style: TextStyle(
          color: onSurface.withValues(alpha: 0.96),
          fontWeight: FontWeight.w700,
          fontSize: 12,
        ),
      ),
    );
  }

  String _versionLabel(String value) {
    final trimmed = value.trim();
    if (trimmed.isEmpty) return 'v0.0.0';
    return trimmed.toLowerCase().startsWith('v') ? trimmed : 'v$trimmed';
  }

