    final nav = _tabCapsule();
    return SizedBox(
      height: compact ? 64 : 72,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Expanded(
            flex: 3,
            child: showLeft
                ? Align(
