  Widget _libraryTab() {
    final selected = _settings.selectedVersion;
    final selectedName = selected?.name ?? 'No Version Selected';
    final selectedVersionLabel = selected == null
        ? ''
        : _formatLibraryVersionLabel(selected.gameVersion);
    final selectedVersionEyebrow =
        selectedVersionLabel.isEmpty || selectedVersionLabel == '?'
        ? 'VERSION'
        : 'VERSION $selectedVersionLabel';
    final coverImage = _libraryCoverImage(selected);
    final allInstalledVersions = _sortedInstalledVersions();
    final showingFavoriteLibrary =
        _librarySortMode == _LibrarySortMode.favoritesFirst;
    final hasFavoriteVersions = _settings.versions.any(
      (entry) => entry.isFavorite,
    );
    final installedVersions = showingFavoriteLibrary
        ? allInstalledVersions.where((entry) => entry.isFavorite).toList()
        : allInstalledVersions;
    final searchQuery = _versionSearchQuery.trim().toLowerCase();
    final filteredVersions = searchQuery.isEmpty
        ? installedVersions
        : installedVersions
              .where((entry) => entry.name.toLowerCase().contains(searchQuery))
              .toList();

    _queueLibrarySplashPrefetch(
      filteredVersions,
      signature:
          '${identityHashCode(allInstalledVersions)}|${_librarySortMode.name}|$searchQuery|${filteredVersions.length}',
    );
    final hasRunningGameClient = _hasRunningGameClient;
    final launchActsAsClose =
        hasRunningGameClient && !_settings.allowMultipleGameClients;
    final showCloseAllGamesButton =
        hasRunningGameClient && _settings.allowMultipleGameClients;
    final selectedLockedByModDownload =
        selected != null && _isModDownloadLockedVersion(selected.id);
    final launchDisabledByModDownload =
        selectedLockedByModDownload && !launchActsAsClose;
    final hostActsAsClose = _gameServerProcess != null;
    final hostDisabledByModDownload =
        selectedLockedByModDownload && !hostActsAsClose;

    final topPanel = _menuItemEntrance(
      menuKey: LauncherTab.library,
      index: 0,
      child: _glass(
        radius: 28,
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              LayoutBuilder(
                builder: (context, constraints) {
                  final compact = constraints.maxWidth < 920;
                  final dpr = MediaQuery.of(context).devicePixelRatio;
                  final coverWidth = compact ? constraints.maxWidth : 250.0;
                  final coverHeight = compact ? 300.0 : 300.0;
                  final coverCacheWidth = _imageCacheExtent(
                    max(coverWidth, coverHeight),
                    dpr,
                  );
                  final ImageProvider<Object> heroCoverProvider =
                      selected == null
                      ? coverImage
                      : ResizeImage(coverImage, width: coverCacheWidth);
                  final image = ClipRRect(
                    borderRadius: BorderRadius.circular(22),
                    child: Image(
                      image: heroCoverProvider,
                      width: compact ? double.infinity : 250,
                      height: coverHeight,
                      fit: BoxFit.cover,
                      filterQuality: FilterQuality.medium,
                      errorBuilder: (context, error, stackTrace) {
                        return Image.asset(
                          'assets/images/missingasset.webp',
                          width: compact ? double.infinity : 250,
                          height: coverHeight,
                          fit: BoxFit.cover,
                          filterQuality: FilterQuality.medium,
                        );
                      },
                    ),
