  Widget _liveTrackingSplashStack(
    List<VersionEntry> versions, {
    double splashSize = 68,
    double overlap = 24,
  }) {
    final visibleVersions = versions.take(3).toList();
    final width = splashSize + (max(visibleVersions.length - 1, 0) * overlap);
    final signature = visibleVersions.map((version) => version.id).join('|');
    final imageCacheSize = _imageCacheExtent(
      splashSize,
      MediaQuery.of(context).devicePixelRatio,
      max: 1024,
    );

    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 260),
      switchInCurve: Curves.easeOutCubic,
      switchOutCurve: Curves.easeInCubic,
      transitionBuilder: (child, animation) {
        final curved = CurvedAnimation(
          parent: animation,
          curve: Curves.easeOutCubic,
          reverseCurve: Curves.easeInCubic,
        );
        return FadeTransition(
          opacity: curved,
          child: SlideTransition(
            position: Tween<Offset>(
              begin: const Offset(-0.12, 0),
              end: Offset.zero,
            ).animate(curved),
            child: child,
          ),
        );
      },
      child: SizedBox(
        key: ValueKey<String>(signature),
        width: width,
        height: splashSize,
        child: Stack(
          clipBehavior: Clip.none,
          children: [
            for (var index = visibleVersions.length - 1; index >= 0; index--)
              AnimatedPositioned(
                duration: const Duration(milliseconds: 260),
                curve: Curves.easeOutCubic,
                left: (visibleVersions.length - 1 - index) * overlap,
                top: 0,
                child: Container(
                  width: splashSize,
                  height: splashSize,
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(color: _onSurface(context, 0.1)),
                    boxShadow: [
                      BoxShadow(
                        color: _glassShadowColor(context),
                        blurRadius: 18,
                        offset: const Offset(0, 8),
                      ),
                    ],
                  ),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(18),
                    child: Image(
                      image: ResizeImage(
                        _libraryCoverImage(visibleVersions[index]),
                        width: imageCacheSize,
                      ),
                      fit: BoxFit.cover,
                      filterQuality: FilterQuality.medium,
                      errorBuilder: (context, error, stackTrace) {
                        return Image.asset(
                          'assets/images/missingasset.webp',
                          fit: BoxFit.cover,
                          filterQuality: FilterQuality.medium,
                        );
                      },
                    ),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }

  String _formatTrackedShare(int trackedSeconds, int totalTrackedSeconds) {
    if (trackedSeconds <= 0 || totalTrackedSeconds <= 0) return '0%';
    final share = (trackedSeconds / totalTrackedSeconds).clamp(0.0, 1.0);
    final percent = share * 100;
    if (percent >= 10) return '${percent.toStringAsFixed(0)}%';
    return '${percent.toStringAsFixed(1)}%';
  }

  Widget _statsVersionInsightPanel({
    required VersionEntry entry,
    required int trackedSeconds,
    required int totalTrackedSeconds,
    required bool active,
  }) {
    final share = totalTrackedSeconds <= 0
        ? 0.0
        : (trackedSeconds / totalTrackedSeconds).clamp(0.0, 1.0);
    final accent = active
        ? const Color(0xFF3DDC97)
        : Theme.of(context).colorScheme.secondary.withValues(alpha: 0.9);
    final versionPill = _formatLibraryVersionLabel(entry.gameVersion);

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(18),
        color: _adaptiveScrimColor(context, darkAlpha: 0.06, lightAlpha: 0.12),
        border: Border.all(color: _onSurface(context, 0.08)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(
            'Percentage Of Total Time',
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w800,
              color: _onSurface(context, 0.66),
            ),
          ),
          const SizedBox(height: 8),
          Text(
            _formatTrackedShare(trackedSeconds, totalTrackedSeconds),
            style: TextStyle(
              fontSize: 28,
              fontWeight: FontWeight.w800,
              color: _onSurface(context, 0.96),
            ),
          ),
          const SizedBox(height: 10),
          ClipRRect(
            borderRadius: BorderRadius.circular(999),
            child: LinearProgressIndicator(
              value: share,
              minHeight: 8,
              backgroundColor: _onSurface(context, 0.08),
              valueColor: AlwaysStoppedAnimation<Color>(accent),
            ),
          ),
          const SizedBox(height: 12),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              _statsMetaChip(
                icon: Icons.tag_rounded,
                label: versionPill == '?' ? 'Unknown version' : versionPill,
              ),
              _statsMetaChip(
                icon: active ? null : Icons.history_rounded,
                leading: active
                    ? _statsStatusDot(color: accent, size: 8)
                    : null,
                label: _formatVersionLastPlayed(entry),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _statsVersionCard(
    VersionEntry entry, {
    required int totalTrackedSeconds,
  }) {
    final active = _activeVersionPlaySessions.containsKey(entry.id);
    final trackedSeconds = _effectiveVersionPlaySeconds(entry);

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(22),
        color: _adaptiveScrimColor(context, darkAlpha: 0.08, lightAlpha: 0.16),
        border: Border.all(color: _onSurface(context, 0.08)),
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final compact = constraints.maxWidth < 620;
          final showInsightPanel = constraints.maxWidth >= 980;
          const cardContentPadding = 16.0;
          const sectionSpacing = 18.0;
          const summarySpacing = 12.0;
          final mediaSize = compact ? min(136.0, constraints.maxWidth) : 128.0;
          final mediaCacheSize = _imageCacheExtent(
            mediaSize,
            MediaQuery.of(context).devicePixelRatio,
            max: 1024,
          );
          final imageProvider = ResizeImage(
            _libraryCoverImage(entry),
            width: mediaCacheSize,
          );
          final titleStyle = TextStyle(
            fontSize: 20,
            fontWeight: FontWeight.w800,
            color: _onSurface(context, 0.96),
          );
          final timeStyle = TextStyle(
            fontSize: showInsightPanel ? 42 : 34,
            fontWeight: FontWeight.w800,
            color: _onSurface(context, 0.98),
          );

          double measureTextWidth(String text, TextStyle style) {
            final painter = TextPainter(
              text: TextSpan(text: text, style: style),
              textDirection: Directionality.of(context),
              textScaler: MediaQuery.textScalerOf(context),
              maxLines: 1,
            )..layout();
            return painter.width;
          }

          const minInsightPanelWidth = 320.0;
          final summaryEquivalentWidth =
              constraints.maxWidth + (cardContentPadding * 2);
          final summaryColumns = summaryEquivalentWidth >= 1120
              ? 3
              : summaryEquivalentWidth >= 720
              ? 2
              : 1;
          final summaryCardWidth = summaryColumns == 1
              ? summaryEquivalentWidth
              : (summaryEquivalentWidth -
                        ((summaryColumns - 1) * summarySpacing)) /
                    summaryColumns;
          final alignedInsightPanelStart = summaryColumns == 1
              ? null
              : summaryCardWidth + summarySpacing - cardContentPadding;
          final alignedDetailsWidth = alignedInsightPanelStart == null
              ? null
              : alignedInsightPanelStart - mediaSize - (sectionSpacing * 2);
          final measuredTimeWidth = measureTextWidth(
            _formatTrackedPlaytime(trackedSeconds),
            timeStyle,
          );
          final minDetailsWidth = max(196.0, measuredTimeWidth + 12);
          final maxDetailsWidth = showInsightPanel
              ? constraints.maxWidth -
                    mediaSize -
                    (sectionSpacing * 2) -
                    minInsightPanelWidth
              : null;
          final detailsColumnWidth = showInsightPanel
              ? max(
                  alignedDetailsWidth ?? minDetailsWidth,
                  minDetailsWidth,
                ).clamp(196.0, maxDetailsWidth!).toDouble()
              : null;

          final media = Container(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(20),
              border: Border.all(color: _onSurface(context, 0.08)),
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(20),
              child: Image(
                image: imageProvider,
                width: mediaSize,
                height: mediaSize,
                fit: BoxFit.cover,
                filterQuality: FilterQuality.medium,
                errorBuilder: (context, error, stackTrace) {
                  return Image.asset(
                    'assets/images/missingasset.webp',
                    width: mediaSize,
                    height: mediaSize,
                    fit: BoxFit.cover,
                    filterQuality: FilterQuality.medium,
                  );
                },
              ),
            ),
          );

          final details = Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Expanded(
                    child: Text(
                      entry.name,
                      maxLines: compact ? 2 : 1,
                      overflow: TextOverflow.ellipsis,
                      style: titleStyle,
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 12),
              Text(_formatTrackedPlaytime(trackedSeconds), style: timeStyle),
            ],
          );

          if (compact) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [media, const SizedBox(height: 16), details],
            );
          }

          return Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              media,
              const SizedBox(width: sectionSpacing),
              Expanded(
                child: showInsightPanel
                    ? Row(
                        crossAxisAlignment: CrossAxisAlignment.center,
                        children: [
                          SizedBox(width: detailsColumnWidth, child: details),
                          const SizedBox(width: sectionSpacing),
                          Expanded(
                            child: _statsVersionInsightPanel(
                              entry: entry,
                              trackedSeconds: trackedSeconds,
                              totalTrackedSeconds: totalTrackedSeconds,
                              active: active,
                            ),
                          ),
                        ],
                      )
                    : details,
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _modsTab() {
    if (!_modsLoading && _modsLibrary.isEmpty && _modsLoadError.isEmpty) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _tab == LauncherTab.mods) {
          unawaited(_loadModsLibrary());
        }
      });
    }

    final onSurface = Theme.of(context).colorScheme.onSurface;
    final query = _modsSearchQuery.trim().toLowerCase();
    // Mods of the current type that match the search (before the All/Installed
    // filter) — used both for the counts and as the base list to filter.
    final typeSearchMods = _modsLibrary.where((mod) {
      if (mod.type != _modsType) return false;
      if (query.isEmpty) return true;
      return mod.name.toLowerCase().contains(query) ||
          mod.author.toLowerCase().contains(query) ||
          mod.cardDescription.toLowerCase().contains(query) ||
          mod.description.toLowerCase().contains(query) ||
          mod.version.toLowerCase().contains(query) ||
          mod.tags.any((tag) => tag.toLowerCase().contains(query));
    }).toList();
    final allCount = typeSearchMods.length;
    final installedCount = typeSearchMods.where(_isAtlasModInstalled).length;
    // "Recent" = mods whose catalog entry was updated within the last 7 days.
    final recentCutoffMs =
        DateTime.now().millisecondsSinceEpoch -
        const Duration(days: 7).inMilliseconds;
    bool isRecentMod(_AtlasModEntry mod) =>
        mod.lastUpdatedEpochMs >= recentCutoffMs;
    final recentCount = typeSearchMods.where(isRecentMod).length;
    final List<_AtlasModEntry> visibleMods;
    if (_modsInstalledFilter == _ModsInstalledFilter.recent) {
      // Recent ignores the version sort: only mods updated in the last week,
      // newest first.
      visibleMods = typeSearchMods.where(isRecentMod).toList()
        ..sort((a, b) {
          final byUpdated = b.lastUpdatedEpochMs.compareTo(
            a.lastUpdatedEpochMs,
          );
          if (byUpdated != 0) return byUpdated;
          return a.name.toLowerCase().compareTo(b.name.toLowerCase());
        });
    } else {
      final filteredMods =
          _modsInstalledFilter == _ModsInstalledFilter.installed
          ? typeSearchMods.where(_isAtlasModInstalled).toList()
          : typeSearchMods;
      visibleMods = _sortModsForDisplay(filteredMods);
    }
    final cardEntranceSignature =
        '${_modsType.name}|${_modsInstalledFilter.name}|${_modsSortMode.name}|$query|'
        '${visibleMods.map((mod) => mod.id).join('|')}';
    if (_modsCardEntranceSignature != cardEntranceSignature) {
      _modsCardEntranceSignature = cardEntranceSignature;
      _animatingModCardEntranceKeys.clear();
      _settledModCardEntranceKeys.clear();
    }
    final showFilterBar = _modsLoadError.isEmpty && _modsLibrary.isNotEmpty;
    final hasInstalledMods = _installedAtlasModsSnapshot().isNotEmpty;
    final showBlockingLoading = _modsLoading && _modsLibrary.isEmpty;

    final search = TextField(
      controller: _modsSearchController,
      onChanged: (value) => setState(() => _modsSearchQuery = value),
      decoration: _backendFieldDecoration(hintText: 'Search mods').copyWith(
        prefixIcon: Icon(
          Icons.search_rounded,
          color: onSurface.withValues(alpha: 0.72),
          size: 18,
        ),
        suffixIcon: _modsSearchQuery.trim().isEmpty
            ? null
            : IconButton(
                tooltip: 'Clear search',
                onPressed: () {
                  _modsSearchController.clear();
                  setState(() => _modsSearchQuery = '');
                },
                icon: const Icon(Icons.close_rounded, size: 18),
              ),
      ),
    );
    final refresh = _versionCardAction(
      icon: Icons.refresh_rounded,
      tooltip: 'Refresh mods',
      busy: _modsLoading,
      onTap: _modsLoading
          ? null
          : () => unawaited(_loadModsLibrary(forceRefresh: true)),
    );
    final clearInstalled = _versionCardAction(
      icon: Icons.delete_sweep_rounded,
      tooltip: 'Clear all installed mods',
      onTap: hasInstalledMods
          ? () => unawaited(_clearInstalledAtlasMods())
          : null,
    );
    // The version sort doesn't apply to the Recent tab (it's ordered by update
    // time), so the button is disabled there.
    final sortDisabled = _modsInstalledFilter == _ModsInstalledFilter.recent;
    final sort = _versionCardAction(
      icon: _modsSortIcon,
      tooltip: sortDisabled
          ? 'Sorting by version (switch off Recent to use)'
          : _modsSortTooltip,
      iconRotation: _modsSortMode == _ModsSortMode.lowestFirst ? pi : 0,
      onTap: sortDisabled ? null : _advanceModsSortMode,
    );

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _menuItemEntrance(
          menuKey: LauncherTab.mods,
          index: 0,
          child: _glass(
            radius: 24,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(18, 15, 18, 15),
              child: LayoutBuilder(
                builder: (context, constraints) {
                  final compact = constraints.maxWidth < 1000;
                  if (compact) {
                    return Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _modsHeaderTitle(),
                        const SizedBox(height: 12),
                        _modsSegmentedControl(),
                      ],
                    );
                  }

                  // Wide: a single compact row — title + segmented control grouped
                  // on the left, search + tools on the right (fills the bar so it
                  // doesn't read as empty).
                  return Row(
                    children: [
                      _modsHeaderTitle(),
                      const Spacer(),
                      _modsSegmentedControl(),
                    ],
                  );
                },
              ),
            ),
          ),
        ),
        const SizedBox(height: 14),
        Expanded(
          child: _menuItemEntrance(
            menuKey: LauncherTab.mods,
            index: 1,
            child: _glass(
              radius: 24,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 0, 16),
                child: AnimatedSwitcher(
                  duration: const Duration(milliseconds: 180),
                  layoutBuilder: (currentChild, previousChildren) {
                    return currentChild ?? const SizedBox.shrink();
                  },
                  child: Scrollbar(
                    key: ValueKey(
                      'mods-scroll-${_modsType.name}-${_modsInstalledFilter.name}-${showBlockingLoading
                          ? 'loading'
                          : _modsLoadError.isNotEmpty
                          ? 'error'
                          : visibleMods.isEmpty
                          ? 'empty'
                          : 'grid'}',
                    ),
                    controller: _modsScrollController,
                    thumbVisibility: true,
                    child: Padding(
                      padding: const EdgeInsets.only(right: 16),
                      child: ScrollConfiguration(
                        behavior: ScrollConfiguration.of(
                          context,
                        ).copyWith(scrollbars: false),
                        child: CustomScrollView(
                          controller: _modsScrollController,
                          clipBehavior: Clip.none,
                          slivers: [
                            if (showFilterBar) ...[
                              SliverToBoxAdapter(
                                child: _modsFilterBar(
                                  allCount: allCount,
                                  installedCount: installedCount,
                                  recentCount: recentCount,
                                  search: search,
                                  refresh: refresh,
                                  clearInstalled: clearInstalled,
                                  sort: sort,
                                ),
                              ),
                              const SliverToBoxAdapter(
                                child: SizedBox(height: 14),
                              ),
                            ],
                            if (showBlockingLoading)
                              const SliverFillRemaining(
                                hasScrollBody: false,
                                child: Center(
                                  key: ValueKey('mods-loading'),
                                  child: CircularProgressIndicator(),
                                ),
                              )
                            else if (_modsLoadError.isNotEmpty)
                              SliverFillRemaining(
                                hasScrollBody: false,
                                child: _modsCenteredState(
                                  key: const ValueKey('mods-error'),
                                  icon: Icons.cloud_off_rounded,
                                  title: _modsLoadError,
                                  subtitle:
                                      'Check the ATLAS-Resources repo and try refresh.',
                                ),
                              )
                            else if (visibleMods.isEmpty)
                              SliverFillRemaining(
                                hasScrollBody: false,
                                child: _modsCenteredState(
                                  key: const ValueKey('mods-empty'),
                                  icon: switch (_modsInstalledFilter) {
                                    _ModsInstalledFilter.installed =>
                                      Icons.download_done_rounded,
                                    _ModsInstalledFilter.recent =>
                                      Icons.history_rounded,
                                    _ModsInstalledFilter.all =>
                                      Icons.extension_off_rounded,
                                  },
                                  title: switch (_modsInstalledFilter) {
                                    _ModsInstalledFilter.installed =>
                                      'No Installed ${_modsType.displayPlural}',
                                    _ModsInstalledFilter.recent =>
                                      'No Recent ${_modsType.displayPlural}',
                                    _ModsInstalledFilter.all =>
                                      'No ${_modsType.displayPlural} Available',
                                  },
                                  subtitle: _modsSearchQuery.trim().isNotEmpty
                                      ? 'No mods match your search.'
                                      : switch (_modsInstalledFilter) {
                                          _ModsInstalledFilter.installed =>
                                            'Install a mod and it will appear here.',
                                          _ModsInstalledFilter.recent =>
                                            'No ${_modsType.displayPlural} updated in the last week.',
                                          _ModsInstalledFilter.all =>
                                            'There are currently no available ${_modsType.displayPlural} to download.',
                                        },
                                ),
                              )
                            else
                              SliverLayoutBuilder(
                                builder: (context, constraints) {
                                  final columns =
                                      constraints.crossAxisExtent >= 1040
                                      ? 2
                                      : 1;
                                  return SliverPadding(
                                    padding: const EdgeInsets.fromLTRB(
                                      4,
                                      6,
                                      8,
                                      12,
                                    ),
                                    sliver: SliverGrid(
                                      gridDelegate:
                                          SliverGridDelegateWithFixedCrossAxisCount(
                                            crossAxisCount: columns,
                                            crossAxisSpacing: 16,
                                            mainAxisSpacing: 16,
                                            mainAxisExtent: columns == 1
                                                ? 138
                                                : 150,
                                          ),
                                      delegate: SliverChildBuilderDelegate(
                                        (
                                          context,
                                          index,
                                        ) => _modGridItemEntrance(
                                          switchKey:
                                              '${_modsType.name}-${_modsInstalledFilter.name}-${visibleMods[index].id}',
                                          index: index,
                                          child: _atlasModCard(
                                            visibleMods[index],
                                          ),
                                        ),
                                        childCount: visibleMods.length,
                                      ),
                                    ),
                                  );
                                },
                              ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }

  // Centered empty/error/loading state shown inside the mods content panel.
  Widget _modsCenteredState({
    required Key key,
    required IconData icon,
    required String title,
    required String subtitle,
  }) {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    return Center(
      key: key,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 34, color: onSurface.withValues(alpha: 0.6)),
          const SizedBox(height: 12),
          Text(
            title,
            textAlign: TextAlign.center,
            style: TextStyle(
              color: onSurface.withValues(alpha: 0.92),
              fontSize: 18,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 6),
          Text(
            subtitle,
            textAlign: TextAlign.center,
            style: TextStyle(
              color: onSurface.withValues(alpha: 0.6),
              fontWeight: FontWeight.w600,
            ),
          ),
        ],
      ),
    );
  }

  // Toolbar inside the content panel: filter between all and installed mods.
  Widget _modsFilterBar({
    required int allCount,
    required int installedCount,
    required int recentCount,
    required Widget search,
    required Widget refresh,
    required Widget clearInstalled,
    required Widget sort,
  }) {
    final chips = Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        _modsFilterChip(
          label: 'All',
          count: allCount,
          selected: _modsInstalledFilter == _ModsInstalledFilter.all,
          onTap: () =>
              setState(() => _modsInstalledFilter = _ModsInstalledFilter.all),
        ),
        const SizedBox(width: 8),
        _modsFilterChip(
          label: 'Installed',
          count: installedCount,
          selected: _modsInstalledFilter == _ModsInstalledFilter.installed,
          onTap: () => setState(
            () => _modsInstalledFilter = _ModsInstalledFilter.installed,
          ),
        ),
        const SizedBox(width: 8),
        _modsFilterChip(
          label: 'Recent',
          count: recentCount,
          selected: _modsInstalledFilter == _ModsInstalledFilter.recent,
          onTap: () => setState(
            () => _modsInstalledFilter = _ModsInstalledFilter.recent,
          ),
        ),
      ],
    );

    final tools = Row(
      children: [
        clearInstalled,
        const SizedBox(width: 8),
        refresh,
        const SizedBox(width: 8),
        sort,
        const SizedBox(width: 8),
        Expanded(child: search),
      ],
    );

    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 760;
        if (compact) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [chips, const SizedBox(height: 10), tools],
          );
        }

        return Row(
          children: [
            chips,
            const Spacer(),
            SizedBox(width: 404, child: tools),
          ],
        );
      },
    );
  }

  Widget _modsFilterChip({
    required String label,
    required int count,
    required bool selected,
    required VoidCallback onTap,
  }) {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final secondary = Theme.of(context).colorScheme.secondary;
    return MouseRegion(
      cursor: SystemMouseCursors.click,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 160),
          curve: Curves.easeOutCubic,
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          decoration: BoxDecoration(
            color: selected
                ? secondary.withValues(alpha: 0.18)
                : onSurface.withValues(alpha: 0.05),
            borderRadius: BorderRadius.circular(999),
            border: Border.all(
              color: selected
                  ? secondary.withValues(alpha: 0.50)
                  : onSurface.withValues(alpha: 0.10),
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                label,
                style: TextStyle(
                  color: onSurface.withValues(alpha: selected ? 0.95 : 0.72),
                  fontSize: 12.5,
                  fontWeight: selected ? FontWeight.w900 : FontWeight.w700,
                ),
              ),
              const SizedBox(width: 6),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 1),
                decoration: BoxDecoration(
                  color: selected
                      ? secondary.withValues(alpha: 0.30)
                      : onSurface.withValues(alpha: 0.10),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  '$count',
                  style: TextStyle(
                    color: onSurface.withValues(alpha: selected ? 0.92 : 0.62),
                    fontSize: 10.5,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _modGridItemEntrance({
    required String switchKey,
    required int index,
    required Widget child,
  }) {
    final cardKey = ValueKey('mod-card-$switchKey');
    final disableAnimations =
        MediaQuery.of(context).disableAnimations ||
        _windowResizeBlurPaused ||
        _suppressModCardEntranceAnimations;
    final settled = _settledModCardEntranceKeys.contains(switchKey);
    if (disableAnimations || settled) {
      _animatingModCardEntranceKeys.remove(switchKey);
      _settledModCardEntranceKeys.add(switchKey);
      return KeyedSubtree(key: cardKey, child: child);
    }

    _animatingModCardEntranceKeys.add(switchKey);
    final delay = (0.045 * min(index, 8)).clamp(0.0, 0.36);
    return TweenAnimationBuilder<double>(
      key: cardKey,
      tween: Tween<double>(begin: 0.0, end: 1.0),
      duration: const Duration(milliseconds: 480),
      curve: Interval(delay, 1.0, curve: Curves.easeOutCubic),
      onEnd: () {
        _animatingModCardEntranceKeys.remove(switchKey);
        _settledModCardEntranceKeys.add(switchKey);
      },
      builder: (context, t, child) {
        return Opacity(
          opacity: t,
          child: Transform.translate(
            offset: Offset(0, (1 - t) * 14),
            child: child,
          ),
        );
      },
      child: child,
    );
  }

