  String _formatAtlasModLastUpdated(int epochMs) {
    if (epochMs <= 0) return 'Last Updated: Unknown';
    final updatedAt = DateTime.fromMillisecondsSinceEpoch(epochMs, isUtc: true);
    final difference = DateTime.now().toUtc().difference(updatedAt);
    if (difference.isNegative || difference.inMinutes < 1) {
      return 'Last Updated: just now';
    }

    int value;
    String unit;
    if (difference.inDays >= 365) {
      value = difference.inDays ~/ 365;
      unit = 'year';
    } else if (difference.inDays >= 30) {
      value = difference.inDays ~/ 30;
      unit = 'month';
    } else if (difference.inDays >= 7) {
      value = difference.inDays ~/ 7;
      unit = 'week';
    } else if (difference.inDays >= 1) {
      value = difference.inDays;
      unit = 'day';
    } else if (difference.inHours >= 1) {
      value = difference.inHours;
      unit = 'hour';
    } else {
      value = difference.inMinutes;
      unit = 'minute';
    }

    return 'Last Updated: $value $unit${value == 1 ? '' : 's'} ago';
  }

  // Segmented toggle for the mod type (Paks / DLLs) with live counts. Uses a
  // single sliding highlight behind fixed-width segments so switching animates
  // smoothly instead of flickering per-segment.
  Widget _modsSegmentedControl() {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final secondary = Theme.of(context).colorScheme.secondary;
    const segWidth = 122.0;
    const segHeight = 38.0;
    final types = _AtlasModType.values;
    final selectedIndex = types.indexOf(_modsType).clamp(0, types.length - 1);
    final highlightAlign = types.length <= 1
        ? 0.0
        : (selectedIndex / (types.length - 1)) * 2 - 1;
    return Container(
      padding: const EdgeInsets.all(4),
      decoration: BoxDecoration(
        color: onSurface.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(13),
        border: Border.all(color: onSurface.withValues(alpha: 0.10)),
      ),
      child: SizedBox(
        width: segWidth * types.length,
        height: segHeight,
        child: Stack(
          children: [
            AnimatedAlign(
              duration: const Duration(milliseconds: 220),
              curve: Curves.easeOutCubic,
              alignment: Alignment(highlightAlign, 0),
              child: Container(
                width: segWidth,
                height: segHeight,
                decoration: BoxDecoration(
                  color: secondary.withValues(alpha: 0.92),
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
            ),
            Row(
              children: [
                for (final type in types)
                  SizedBox(
                    width: segWidth,
                    height: segHeight,
                    child: _modsSegmentLabel(type),
                  ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  void _advanceModsSortMode() {
    setState(() {
      _modsSortMode = _modsSortMode == _ModsSortMode.highestFirst
          ? _ModsSortMode.lowestFirst
          : _ModsSortMode.highestFirst;
    });
  }

  IconData get _modsSortIcon => Icons.filter_list_rounded;

  String get _modsSortTooltip => switch (_modsSortMode) {
    _ModsSortMode.highestFirst => 'Sort: highest version at top',
    _ModsSortMode.lowestFirst => 'Sort: lowest version at top',
  };

  /// Orders mods for display. Versions with no numeric component (or an empty
  /// version) are pinned to the top, sorted alphabetically. Numeric versions
  /// follow, ordered by the current sort direction (highest-first by default).
  /// Returns a new list; the input is not mutated.
  List<_AtlasModEntry> _sortModsForDisplay(List<_AtlasModEntry> mods) {
    bool isNumericVersion(String v) => RegExp(r'\d').hasMatch(v);
    final sorted = List<_AtlasModEntry>.from(mods);
    sorted.sort((a, b) {
      final aNumeric = isNumericVersion(a.version);
      final bNumeric = isNumericVersion(b.version);
      // Non-numeric / blank versions always sit at the top, alphabetically.
      if (aNumeric != bNumeric) return aNumeric ? 1 : -1;
      if (!aNumeric) {
        final byVersion = a.version.trim().toLowerCase().compareTo(
          b.version.trim().toLowerCase(),
        );
        if (byVersion != 0) return byVersion;
        return a.name.toLowerCase().compareTo(b.name.toLowerCase());
      }
      final byVersion = _modsSortMode == _ModsSortMode.lowestFirst
          ? _compareVersionStrings(a.version, b.version)
          : _compareVersionStrings(b.version, a.version);
      if (byVersion != 0) return byVersion;
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });
    return sorted;
  }

  Widget _modsSegmentLabel(_AtlasModType type) {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final selected = _modsType == type;
    final icon = switch (type) {
      _AtlasModType.pak => Icons.inventory_2_rounded,
      _AtlasModType.dll => Icons.science_rounded,
      _AtlasModType.exe => Icons.bolt_rounded,
    };
    // GestureDetector (not InkWell) so there's no ripple/circle on tap — only
    // the sliding highlight animates.
    return MouseRegion(
      cursor: selected ? MouseCursor.defer : SystemMouseCursors.click,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: selected ? null : () => setState(() => _modsType = type),
        child: Center(
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                icon,
                size: 15,
                color: selected
                    ? Colors.white
                    : onSurface.withValues(alpha: 0.70),
              ),
              const SizedBox(width: 7),
              Text(
                type.displayPlural,
                style: TextStyle(
                  color: selected
                      ? Colors.white
                      : onSurface.withValues(alpha: 0.80),
                  fontSize: 12.5,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _atlasModCard(_AtlasModEntry mod) {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final secondary = Theme.of(context).colorScheme.secondary;
    final installed = _isAtlasModInstalled(mod);
    final updateAvailable = _atlasModUpdateAvailable(mod);
    final descriptionPreview = _plainTextMarkdownPreview(
      mod.cardDescription.trim().isNotEmpty
          ? mod.cardDescription
          : mod.description,
    );
    final image = _launcherContentImageProvider(
      mod.primaryImage,
      fallbackAsset: 'assets/images/missingasset.webp',
    );
    final cardRadius = BorderRadius.circular(18);

    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 520;
        final dpr = MediaQuery.of(context).devicePixelRatio;
        final thumbSize = compact ? 78.0 : 88.0;
        final thumbProvider = ResizeImage(
          image,
          width: _imageCacheExtent(
            thumbSize,
            dpr,
            qualityScale: 3.0,
            max: 1024,
          ),
        );
        final bgProvider = ResizeImage(
          image,
          width: _imageCacheExtent(
            compact ? 360 : 520,
            dpr,
            qualityScale: 0.7,
            max: 1024,
          ),
        );

        final thumbImage = ClipRRect(
          borderRadius: BorderRadius.circular(12),
          child: Image(
            image: thumbProvider,
            width: thumbSize,
            height: thumbSize,
            fit: BoxFit.cover,
            alignment: Alignment.center,
            filterQuality: FilterQuality.high,
            gaplessPlayback: true,
            errorBuilder: (context, error, stackTrace) {
              return Image.asset(
                'assets/images/missingasset.webp',
                width: thumbSize,
                height: thumbSize,
                fit: BoxFit.cover,
                filterQuality: FilterQuality.high,
              );
            },
          ),
        );
        // A "!" badge marks installed mods that have a newer catalog release.
        final thumb = updateAvailable
            ? Stack(
                clipBehavior: Clip.none,
                children: [
                  thumbImage,
                  Positioned(
                    top: -5,
                    right: -5,
                    child: _atlasUpdateBadge(size: 18),
                  ),
                ],
              )
            : thumbImage;

        // Pills are fully metadata-driven: the optional version pill and any
        // free-form tags from the mod's metadata.json. Tags are capped to fit
        // the card; overflow collapses into a "+N" pill (the details dialog
        // shows the full list). "Installed" is launcher runtime state.
        final maxVisibleTags = compact ? 1 : 3;
        final visibleTags = mod.tags.length <= maxVisibleTags
            ? mod.tags
            : mod.tags.take(maxVisibleTags).toList();
        final hiddenTagCount = mod.tags.length - visibleTags.length;
        final pills = Wrap(
          spacing: 6,
          runSpacing: 6,
          children: [
            if (mod.version.trim().isNotEmpty)
              _modPill(
                mod.version.trim(),
                icon: Icons.sell_rounded,
                prominent: true,
              ),
            for (final tag in visibleTags) _modPill(tag),
            if (hiddenTagCount > 0) _modPill('+$hiddenTagCount'),
            if (updateAvailable)
              _modPill(
                'Update',
                icon: Icons.upgrade_rounded,
                color: const Color(0xFFE8A23D),
              )
            else if (installed)
              _modPill(
                'Installed',
                icon: Icons.check_rounded,
                color: secondary,
              ),
          ],
        );

        final details = Column(
          mainAxisAlignment: MainAxisAlignment.center,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              mod.name,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: onSurface.withValues(alpha: 0.98),
                fontSize: compact ? 20 : 23,
                height: 1,
                fontWeight: FontWeight.w800,
              ),
            ),
            const SizedBox(height: 6),
            Text(
              mod.author,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: onSurface.withValues(alpha: 0.72),
                fontSize: 12.5,
                fontWeight: FontWeight.w800,
              ),
            ),
            const SizedBox(height: 8),
            Text(
              descriptionPreview.isEmpty
                  ? 'No description provided.'
                  : descriptionPreview,
              maxLines: compact ? 1 : 2,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: onSurface.withValues(alpha: 0.74),
                height: 1.22,
                fontSize: 13,
                fontWeight: FontWeight.w600,
              ),
            ),
            const SizedBox(height: 9),
            pills,
          ],
        );

        return _HoverScale(
          scale: 1.01,
          child: InkWell(
            borderRadius: cardRadius,
            onTap: () => unawaited(_showAtlasModDetails(mod)),
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 180),
              curve: Curves.easeOutCubic,
              decoration: BoxDecoration(
                borderRadius: cardRadius,
                boxShadow: installed
                    ? [
                        BoxShadow(
                          color: secondary.withValues(alpha: 0.34),
                          blurRadius: 24,
                          spreadRadius: 0.7,
                        ),
                        BoxShadow(
                          color: _adaptiveScrimColor(
                            context,
                            darkAlpha: 0.30,
                            lightAlpha: 0.10,
                          ),
                          blurRadius: 16,
                          offset: const Offset(0, 8),
                        ),
                      ]
                    : [
                        BoxShadow(
                          color: _adaptiveScrimColor(
                            context,
                            darkAlpha: 0.18,
                            lightAlpha: 0.08,
                          ),
                          blurRadius: 10,
                          offset: const Offset(0, 4),
                        ),
                      ],
              ),
              child: ClipRRect(
                borderRadius: cardRadius,
                clipBehavior: Clip.antiAlias,
                child: Stack(
                  children: [
                    Positioned.fill(
                      child: ImageFiltered(
                        imageFilter: ImageFilter.blur(sigmaX: 9, sigmaY: 9),
                        child: Image(
                          image: bgProvider,
                          fit: BoxFit.cover,
                          filterQuality: FilterQuality.low,
                          gaplessPlayback: true,
                          errorBuilder: (context, error, stackTrace) {
                            return Image.asset(
                              'assets/images/missingasset.webp',
                              fit: BoxFit.cover,
                              filterQuality: FilterQuality.low,
                            );
                          },
                        ),
                      ),
                    ),
                    Positioned.fill(
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                            colors: [
                              _adaptiveScrimColor(
                                context,
                                darkAlpha: 0.50,
                                lightAlpha: 0.30,
                              ),
                              _adaptiveScrimColor(
                                context,
                                darkAlpha: 0.40,
                                lightAlpha: 0.18,
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                    Positioned.fill(
                      child: IgnorePointer(
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            borderRadius: cardRadius,
                            border: Border.all(
                              color: installed
                                  ? secondary.withValues(alpha: 0.82)
                                  : onSurface.withValues(alpha: 0.20),
                              width: installed ? 1.35 : 1.0,
                            ),
                          ),
                        ),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 14,
                        vertical: 12,
                      ),
                      child: Row(
                        children: [
                          thumb,
                          const SizedBox(width: 14),
                          Expanded(child: details),
                          const SizedBox(width: 10),
                          Container(
                            width: 32,
                            height: 32,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: _adaptiveScrimColor(
                                context,
                                darkAlpha: 0.22,
                                lightAlpha: 0.24,
                              ),
                              border: Border.all(
                                color: onSurface.withValues(alpha: 0.22),
                              ),
                            ),
                            child: Icon(
                              Icons.chevron_right_rounded,
                              color: onSurface.withValues(alpha: 0.88),
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  String _plainTextMarkdownPreview(String value) {
    var text = value
        .replaceAll('\r\n', '\n')
        .replaceAll('\r', '\n')
        .replaceAll(RegExp(r'```[\s\S]*?```'), ' ')
        .replaceAllMapped(RegExp(r'`([^`]*)`'), (match) => match.group(1) ?? '')
        .replaceAll(RegExp(r'!\[[^\]]*\]\([^)]+\)'), ' ')
        .replaceAllMapped(
          RegExp(r'\[([^\]]+)\]\([^)]+\)'),
          (match) => match.group(1) ?? '',
        )
        .replaceAll(RegExp(r'^\s{0,3}#{1,6}\s*', multiLine: true), '')
        .replaceAll(RegExp(r'^\s{0,3}[-*_]{3,}\s*$', multiLine: true), ' ')
        .replaceAll(RegExp(r'^\s*[-*+]\s+', multiLine: true), '')
        .replaceAll(RegExp(r'^\s*\d+[.)]\s+', multiLine: true), '')
        .replaceAll(RegExp(r'[*_~>#]'), '')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    return text;
  }

  Widget _modPill(
    String label, {
    IconData? icon,
    Color? color,
    bool prominent = false,
    double? maxWidth,
  }) {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final base = color ?? Theme.of(context).colorScheme.secondary;
    final neutralFillAlpha = prominent ? 0.54 : 0.50;
    final neutralBorderAlpha = prominent ? 0.34 : 0.32;
    final textColor = color == null
        ? Colors.white.withValues(alpha: prominent ? 1.0 : 0.94)
        : Colors.white;
    final labelText = Text(
      label,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: TextStyle(
        color: textColor,
        fontSize: 11,
        fontWeight: FontWeight.w900,
      ),
    );
    final pill = Container(
      padding: EdgeInsets.fromLTRB(icon == null ? 10 : 8, 5, 10, 5),
      decoration: BoxDecoration(
        color: color == null
            ? Colors.black.withValues(alpha: neutralFillAlpha)
            : base.withValues(alpha: 0.72),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(
          color: color == null
              ? Colors.white.withValues(alpha: neutralBorderAlpha)
              : base.withValues(alpha: 0.68),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.18),
            blurRadius: 10,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (icon != null) ...[
            Icon(
              icon,
              size: 12,
              color: color == null
                  ? onSurface.withValues(alpha: prominent ? 0.95 : 0.78)
                  : Colors.white,
            ),
            const SizedBox(width: 5),
          ],
          if (maxWidth == null) labelText else Flexible(child: labelText),
        ],
      ),
    );
    if (maxWidth == null) return pill;
    return ConstrainedBox(
      constraints: BoxConstraints(maxWidth: maxWidth),
      child: pill,
    );
  }

  Widget _atlasModMediaSlide(
    BuildContext context,
    _AtlasModMedia media, {
    required ValueChanged<bool> onWatchingChanged,
  }) {
    if (media.type == _AtlasModMediaType.image) {
      final provider = _atlasModDetailImageProvider(media, context);
      return Stack(
        fit: StackFit.expand,
        children: [
          ColoredBox(
            color: _adaptiveScrimColor(
              context,
              darkAlpha: 0.18,
              lightAlpha: 0.14,
            ),
          ),
          Image(
            image: provider,
            fit: BoxFit.cover,
            filterQuality: FilterQuality.medium,
            gaplessPlayback: true,
            frameBuilder: (context, child, frame, wasSynchronouslyLoaded) {
              final visible = wasSynchronouslyLoaded || frame != null;
              return AnimatedOpacity(
                opacity: visible ? 1 : 0,
                duration: const Duration(milliseconds: 220),
                curve: Curves.easeOutCubic,
                child: child,
              );
            },
            errorBuilder: (context, error, stackTrace) {
              return Image.asset(
                'assets/images/missingasset.webp',
                fit: BoxFit.cover,
                filterQuality: FilterQuality.medium,
              );
            },
          ),
        ],
      );
    }
    return _AtlasModPlaybackViewer(
      media: media,
      onWatchingChanged: onWatchingChanged,
      onOpenExternal: (url) => unawaited(_openUrl(url)),
    );
  }

  ImageProvider<Object> _atlasModDetailImageProvider(
    _AtlasModMedia media,
    BuildContext context,
  ) {
    final dpr = MediaQuery.of(context).devicePixelRatio;
    return ResizeImage(
      _launcherContentImageProvider(
        media.url,
        fallbackAsset: 'assets/images/missingasset.webp',
      ),
      width: _imageCacheExtent(760, dpr, qualityScale: 1.0, max: 2048),
    );
  }

  Future<void> _precacheAtlasModDetailImages(List<_AtlasModMedia> media) async {
    if (!mounted || media.isEmpty) return;
    final imageMedia = media
        .where((item) => item.type == _AtlasModMediaType.image)
        .take(2)
        .toList();
    for (final item in imageMedia) {
      if (!mounted) return;
      try {
        await precacheImage(
          _atlasModDetailImageProvider(item, context),
          context,
        );
      } catch (_) {
        // Ignore missing or slow media; the dialog has its own fallback.
      }
    }
  }

  Future<void> _showAtlasModDetails(_AtlasModEntry mod) async {
    if (!mounted) return;
    final media = mod.detailMedia;
    unawaited(_precacheAtlasModDetailImages(media));
    final pageController = PageController();
    final detailsScrollController = ScrollController();
    Timer? mediaTimer;
    final watchingMediaIndexes = <int>{};
    var imageIndex = 0;
    var actionBusy = false;
    var updating = false;
    var mediaHover = false;
    const mediaSwitchDuration = Duration(milliseconds: 360);
    const mediaSwitchCurve = Curves.easeOutCubic;

    void animateToMedia(
      int index,
      void Function(void Function()) setDialogState,
    ) {
      if (media.isEmpty) return;
      final nextIndex = index % media.length;
      final previousIndex = imageIndex;
      pageController.animateToPage(
        nextIndex,
        duration: mediaSwitchDuration,
        curve: mediaSwitchCurve,
      );
      if (previousIndex != nextIndex) {
        setDialogState(() => imageIndex = nextIndex);
      }
    }

    void startMediaTimer(void Function(void Function()) setDialogState) {
      mediaTimer?.cancel();
      if (media.length <= 1) return;
      if (watchingMediaIndexes.contains(imageIndex % media.length)) return;
      final seconds = _activeLauncherContentPage.heroRotationSeconds;
      if (seconds <= 0) return;
      mediaTimer = Timer.periodic(Duration(seconds: seconds), (_) {
        if (!mounted || !pageController.hasClients) return;
        if (watchingMediaIndexes.contains(imageIndex % media.length)) {
          mediaTimer?.cancel();
          mediaTimer = null;
          return;
        }
        animateToMedia(imageIndex + 1, setDialogState);
      });
    }

    void selectMedia(
      int index,
      void Function(void Function()) setDialogState, {
      bool restartTimer = true,
    }) {
      animateToMedia(index, setDialogState);
      if (restartTimer) startMediaTimer(setDialogState);
    }

    try {
      await showGeneralDialog<void>(
        context: context,
        barrierDismissible: true,
        barrierLabel: MaterialLocalizations.of(
          context,
        ).modalBarrierDismissLabel,
        barrierColor: Colors.transparent,
        transitionDuration: const Duration(milliseconds: 220),
        pageBuilder: (dialogContext, animation, secondaryAnimation) {
          return SafeArea(
            child: Center(
              child: Material(
                type: MaterialType.transparency,
                child: LayoutBuilder(
                  builder: (context, constraints) {
                    return ConstrainedBox(
                      constraints: BoxConstraints(
                        maxWidth: 760,
                        maxHeight: constraints.maxHeight * 0.92,
                      ),
                      child: StatefulBuilder(
                        builder: (dialogContext, setDialogState) {
                          if (mediaTimer == null && media.length > 1) {
                            WidgetsBinding.instance.addPostFrameCallback((_) {
                              if (dialogContext.mounted) {
                                startMediaTimer(setDialogState);
                              }
                            });
                          }
                          final onSurface = Theme.of(
                            dialogContext,
                          ).colorScheme.onSurface;
                          final secondary = Theme.of(
                            dialogContext,
                          ).colorScheme.secondary;
                          final installed = _isAtlasModInstalled(mod);
                          final updateAvailable =
                              installed && _atlasModUpdateAvailable(mod);
                          // Build-targeted mods can only install into a
                          // compatible imported build that is not running.
                          final compatibleBuilds = mod.type.isBuildTargeted
                              ? _compatibleVersionsForMod(mod)
                              : const <VersionEntry>[];
                          final hasCompatibleBuild =
                              !mod.type.isBuildTargeted ||
                              compatibleBuilds.isNotEmpty;
                          final installBlockedByRunningBuild =
                              !installed &&
                              mod.type.isBuildTargeted &&
                              compatibleBuilds.isNotEmpty &&
                              compatibleBuilds.every(
                                (version) => _isVersionRunning(version.id),
                              );
                          return Container(
                            margin: const EdgeInsets.symmetric(horizontal: 20),
                            padding: const EdgeInsets.fromLTRB(20, 20, 0, 18),
                            decoration: BoxDecoration(
                              color: _dialogSurfaceColor(dialogContext),
                              borderRadius: BorderRadius.circular(24),
                              border: Border.all(
                                color: _onSurface(dialogContext, 0.12),
                              ),
                              boxShadow: [
                                BoxShadow(
                                  color: _dialogShadowColor(dialogContext),
                                  blurRadius: 34,
                                  offset: const Offset(0, 18),
                                ),
                              ],
                            ),
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Flexible(
                                  child: Scrollbar(
                                    controller: detailsScrollController,
                                    thumbVisibility: true,
                                    child: Padding(
                                      padding: const EdgeInsets.only(right: 20),
                                      child: ScrollConfiguration(
                                        behavior: ScrollConfiguration.of(
                                          dialogContext,
                                        ).copyWith(scrollbars: false),
                                        child: SingleChildScrollView(
                                          controller: detailsScrollController,
                                          primary: false,
                                          child: Column(
                                            crossAxisAlignment:
                                                CrossAxisAlignment.start,
                                            children: [
                                              MouseRegion(
                                                onEnter: (_) => setDialogState(
                                                  () => mediaHover = true,
                                                ),
                                                onExit: (_) => setDialogState(
                                                  () => mediaHover = false,
                                                ),
                                                child: ClipRRect(
                                                  borderRadius:
                                                      BorderRadius.circular(18),
                                                  child: AspectRatio(
                                                    aspectRatio: 16 / 8.4,
                                                    child: Stack(
                                                      fit: StackFit.expand,
                                                      children: [
                                                        PageView.builder(
                                                          controller:
                                                              pageController,
                                                          itemCount:
                                                              media.length,
                                                          onPageChanged: (index) {
                                                            setDialogState(
                                                              () => imageIndex =
                                                                  index,
                                                            );
                                                            startMediaTimer(
                                                              setDialogState,
                                                            );
                                                          },
                                                          itemBuilder: (context, index) {
                                                            return _atlasModMediaSlide(
                                                              dialogContext,
                                                              media[index],
                                                              onWatchingChanged: (watching) {
                                                                if (watching) {
                                                                  watchingMediaIndexes
                                                                      .add(
                                                                        index,
                                                                      );
                                                                } else {
                                                                  watchingMediaIndexes
                                                                      .remove(
                                                                        index,
                                                                      );
                                                                }
                                                                if (index ==
                                                                    imageIndex) {
                                                                  if (watching) {
                                                                    mediaTimer
                                                                        ?.cancel();
                                                                    mediaTimer =
                                                                        null;
                                                                  } else {
                                                                    startMediaTimer(
                                                                      setDialogState,
                                                                    );
                                                                  }
                                                                }
