  void _queueLibrarySplashPrefetch(
    List<VersionEntry> versions, {
    required String signature,
  }) {
    if (!mounted) return;
    if (_tab != LauncherTab.library) return;
    if (versions.isEmpty) return;
    if (_librarySplashPrefetchQueued) return;
    if (_librarySplashPrefetchSignature == signature) return;

    _librarySplashPrefetchSignature = signature;
    _librarySplashPrefetchQueued = true;

    WidgetsBinding.instance.addPostFrameCallback((_) {
      _librarySplashPrefetchQueued = false;
      if (!mounted) return;

      // Pre-cache the first batch of splash images so scrolling feels instant.
      final dpr = MediaQuery.of(context).devicePixelRatio;
      final cacheWidth = _imageCacheExtent(520, dpr, qualityScale: 1.0);
      final count = min(8, versions.length);

      unawaited(() async {
        await Future<void>.delayed(const Duration(milliseconds: 220));
        for (var i = 0; i < count; i++) {
          if (!mounted) return;
          if (_tab != LauncherTab.library) return;
          final provider = ResizeImage(
            _libraryCoverImage(versions[i]),
            width: cacheWidth,
          );
          try {
            await precacheImage(provider, context);
          } catch (_) {
            // Ignore bad images.
          }
          // Yield to the UI thread to avoid jank.
          await Future<void>.delayed(const Duration(milliseconds: 8));
        }
      }());
    });
  }

  Widget _installedVersionCard(VersionEntry entry) {
    final active = _settings.selectedVersionId == entry.id;
    final favorite = entry.isFavorite;
    final lockedByModDownload = _isModDownloadLockedVersion(entry.id);
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final secondary = Theme.of(context).colorScheme.secondary;
    final splashImage = _libraryCoverImage(entry);
    final cardRadius = BorderRadius.circular(18);

    return LayoutBuilder(
      builder: (context, constraints) {
        final dpr = MediaQuery.of(context).devicePixelRatio;
        final thumbCache = _imageCacheExtent(
          72,
          dpr,
          qualityScale: 1.15,
          max: 384,
        );
        final bgProvider = ResizeImage(
          splashImage,
          width: _imageCacheExtent(520, dpr, qualityScale: 0.7, max: 1024),
        );
        final thumbProvider = ResizeImage(splashImage, width: thumbCache);

        final versionPill = _formatLibraryVersionLabel(entry.gameVersion);

        return _HoverScale(
          scale: 1.01,
          child: InkWell(
            borderRadius: cardRadius,
            onTap: () {
              if (active) return;
              setState(() {
                _settings = _settings.copyWith(selectedVersionId: entry.id);
              });
              unawaited(_saveSettings(toast: false));
            },
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 180),
              curve: Curves.easeOutCubic,
              height: 116,
              decoration: BoxDecoration(
                borderRadius: cardRadius,
                boxShadow: active
                    ? [
                        BoxShadow(
                          color: secondary.withValues(alpha: 0.34),
                          blurRadius: 24,
                          spreadRadius: 0.7,
                        ),
                        BoxShadow(
                          color: _adaptiveScrimColor(
                            context,
                            darkAlpha: 0.30,
                            lightAlpha: 0.10,
                          ),
                          blurRadius: 16,
                          offset: const Offset(0, 8),
                        ),
                      ]
                    : [
                        BoxShadow(
                          color: _adaptiveScrimColor(
                            context,
                            darkAlpha: 0.18,
                            lightAlpha: 0.08,
                          ),
                          blurRadius: 10,
                          offset: const Offset(0, 4),
                        ),
                      ],
              ),
              child: ClipRRect(
                borderRadius: cardRadius,
                clipBehavior: Clip.antiAlias,
                child: Stack(
                  children: [
                    Positioned.fill(
                      child: ImageFiltered(
                        imageFilter: ImageFilter.blur(sigmaX: 9, sigmaY: 9),
                        child: Image(
                          image: bgProvider,
                          fit: BoxFit.cover,
                          filterQuality: FilterQuality.low,
                          gaplessPlayback: true,
                          errorBuilder: (context, error, stackTrace) {
                            return Image.asset(
                              'assets/images/missingasset.webp',
                              fit: BoxFit.cover,
                              filterQuality: FilterQuality.low,
                            );
                          },
                        ),
                      ),
                    ),
                    Positioned.fill(
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                            colors: [
                              _adaptiveScrimColor(
                                context,
                                darkAlpha: 0.58,
                                lightAlpha: 0.36,
                              ),
                              _adaptiveScrimColor(
                                context,
                                darkAlpha: 0.48,
                                lightAlpha: 0.24,
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                    Positioned.fill(
                      child: IgnorePointer(
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            borderRadius: cardRadius,
                            border: Border.all(
                              color: active
                                  ? secondary.withValues(alpha: 0.78)
                                  : onSurface.withValues(alpha: 0.20),
                              width: active ? 1.2 : 1.0,
                            ),
                          ),
                        ),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 10,
                      ),
                      child: Row(
                        children: [
                          ClipRRect(
                            borderRadius: BorderRadius.circular(10),
                            child: Image(
                              image: thumbProvider,
                              width: 72,
                              height: 72,
                              fit: BoxFit.cover,
                              filterQuality: FilterQuality.medium,
                              gaplessPlayback: true,
                              errorBuilder: (context, error, stackTrace) {
                                return Image.asset(
                                  'assets/images/missingasset.webp',
                                  width: 72,
                                  height: 72,
                                  fit: BoxFit.cover,
                                  filterQuality: FilterQuality.medium,
                                );
                              },
                            ),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Text(
                                  entry.name,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                    fontSize: 22,
                                    fontWeight: FontWeight.w700,
                                    color: onSurface.withValues(alpha: 0.98),
                                    height: 1,
                                  ),
                                ),
                                const SizedBox(height: 6),
                                _modPill(
                                  versionPill == '?' ? 'Unknown' : versionPill,
                                  icon: Icons.sell_rounded,
                                  prominent: true,
                                ),
                              ],
                            ),
                          ),
                          if (active) ...[
                            Container(
                              width: 24,
                              height: 24,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color: secondary.withValues(alpha: 0.9),
                              ),
                              child: const Icon(
                                Icons.check_rounded,
                                size: 15,
                                color: Colors.white,
                              ),
                            ),
                            const SizedBox(width: 8),
                          ],
                          _versionCardAction(
                            icon: favorite
                                ? Icons.star_rounded
                                : Icons.star_border_rounded,
                            tooltip: favorite
                                ? 'Remove favorite'
                                : 'Favorite build',
                            iconColor: favorite
                                ? const Color(0xFFFACC15)
                                : Colors.white,
                            onTap: () => _toggleVersionFavorite(entry.id),
                          ),
                          const SizedBox(width: 6),
                          _versionCardAction(
                            icon: Icons.edit_rounded,
                            tooltip: lockedByModDownload
                                ? 'Finish mod download before editing'
                                : 'Edit build',
                            onTap: lockedByModDownload
                                ? null
                                : () => _editVersion(entry),
                          ),
                          const SizedBox(width: 6),
                          _versionCardAction(
                            icon: Icons.delete_outline_rounded,
                            tooltip: lockedByModDownload
                                ? 'Finish mod download before removing'
                                : 'Remove build',
                            onTap: lockedByModDownload
                                ? null
                                : () => _removeVersion(entry.id),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _versionCardAction({
    required IconData icon,
    required String tooltip,
    required VoidCallback? onTap,
    double iconRotation = 0,
    Color? iconColor,
    bool busy = false,
  }) {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final enabled = onTap != null;
    final resolvedColor = enabled
        ? iconColor ?? onSurface.withValues(alpha: 0.92)
        : onSurface.withValues(alpha: 0.38);
    return Tooltip(
      message: tooltip,
      child: IconButton(
        onPressed: onTap,
        icon: busy
            ? SizedBox(
                width: 16,
                height: 16,
                child: CircularProgressIndicator(
                  strokeWidth: 2,
                  valueColor: AlwaysStoppedAnimation<Color>(resolvedColor),
                ),
              )
            : Transform.rotate(
                angle: iconRotation,
                child: Icon(icon, size: 18),
              ),
        color: resolvedColor,
        style: IconButton.styleFrom(
          minimumSize: const Size(32, 32),
          padding: const EdgeInsets.all(6),
          backgroundColor: _adaptiveScrimColor(
            context,
            darkAlpha: enabled ? 0.22 : 0.10,
            lightAlpha: enabled ? 0.24 : 0.10,
          ),
          side: BorderSide(
            color: onSurface.withValues(alpha: enabled ? 0.24 : 0.12),
          ),
        ),
      ),
    );
  }

  Widget _dllPresetDefaultTag(BuildContext context) {
    final dark = Theme.of(context).brightness == Brightness.dark;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: const Color(0xFF22C55E).withValues(alpha: dark ? 0.18 : 0.12),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(
          color: const Color(0xFF22C55E).withValues(alpha: 0.58),
        ),
      ),
      child: Text(
        'Default',
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: TextStyle(
          fontSize: 10.5,
          fontWeight: FontWeight.w900,
          color: dark ? const Color(0xFF86EFAC) : const Color(0xFF166534),
        ),
      ),
    );
  }

  Widget _backendTab() {
    final onSurface = Theme.of(context).colorScheme.onSurface;
    final secondary = Theme.of(context).colorScheme.secondary;
    final resolvedHost = _effectiveBackendHost().trim();
    final hostLabel = resolvedHost.isEmpty ? _defaultBackendHost : resolvedHost;
    final portLabel = _effectiveBackendPort().toString();
    final configuredEndpoint = '$hostLabel:$portLabel';
    final backendActionBusy = _backendActionBusy;
    final backendBusyLabel = _backendActionMessage.trim().isEmpty
        ? 'Checking Backend...'
        : _backendActionMessage;
    final backendBusyStatus = backendBusyLabel.replaceAll('...', '').trim();
    final statusLabel = backendActionBusy
        ? '$backendBusyStatus on $configuredEndpoint'
        : _backendOnline
        ? 'Connected on $configuredEndpoint'
        : 'Waiting on $configuredEndpoint';
    final managedBackendName =
        _settings.backendConnectionType == BackendConnectionType.embedded
        ? _settings.embeddedBackendType.label
        : 'ATLAS Backend';
    // The selected embedded backend may not be installed on disk (the installer
    // makes each backend optional). When missing, the primary action becomes a
    // download instead of a launch.
    final selectedEmbeddedBackend = _settings.embeddedBackendType;
    final selectedEmbeddedMissing =
        _settings.backendConnectionType == BackendConnectionType.embedded &&
        !_embeddedBackendInstalled(selectedEmbeddedBackend);
    final isDownloadingSelectedBackend =
        _downloadingBackend == selectedEmbeddedBackend;
    final backendLaunchLabel = selectedEmbeddedMissing
        ? (isDownloadingSelectedBackend
              ? 'Downloading ${selectedEmbeddedBackend.label}...'
              : 'Download ${selectedEmbeddedBackend.label}')
        : _atlasBackendActionBusy
        ? backendBusyLabel
        : _atlasBackendProcess != null
        ? 'Stop Backend'
        : 'Launch $managedBackendName';
    final canUseManagedBackend =
        _settings.backendConnectionType != BackendConnectionType.remote;
    final embeddedBackendSelectorLocked =
        _atlasBackendProcess != null || _backendActionBusy;

    if (_showBackendConnectionTip &&
        _backendQuickTipStep == 0 &&
        _backendQuickTipOriginalType == null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted ||
            !_showBackendConnectionTip ||
            _backendQuickTipStep != 0 ||
            _backendQuickTipOriginalType != null) {
          return;
        }
        _previewBackendTypeForTip(BackendConnectionType.local);
      });
    }

    final backendPanel = _glass(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(14),
                color: onSurface.withValues(alpha: 0.06),
                border: Border.all(color: onSurface.withValues(alpha: 0.12)),
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    children: [
                      Container(
                        width: 10,
                        height: 10,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: _backendOnline
                              ? const Color(0xFF16C47F)
                              : backendActionBusy
                              ? secondary.withValues(alpha: 0.92)
                              : const Color(0xFFDC3545),
                        ),
                      ),
                      const SizedBox(width: 10),
                      Text(
                        _backendOnline
                            ? 'Backend Reachable'
                            : backendActionBusy
                            ? backendBusyLabel.replaceAll('...', '')
                            : 'Backend Not Detected',
                        style: TextStyle(
                          fontWeight: FontWeight.w700,
                          color: onSurface.withValues(alpha: 0.92),
                        ),
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Align(
                          alignment: Alignment.centerRight,
                          child: Text(
                            statusLabel,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            textAlign: TextAlign.end,
                            style: TextStyle(
                              color: onSurface.withValues(alpha: 0.74),
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
            if (_showBackendConnectionTip) ...[
              const SizedBox(height: 12),
              _backendConnectionTipCard(),
            ],
            const SizedBox(height: 14),
            _backendSettingTile(
              icon: Icons.settings_ethernet_rounded,
              title: 'Type',
              subtitle: 'The type of backend to use when logging into Fortnite',
              trailing: _tipPulseGlowIf(
                DropdownButtonFormField<BackendConnectionType>(
                  initialValue: _settings.backendConnectionType,
                  decoration: _backendFieldDecoration(),
                  items: _backendConnectionTypeDropdownOrder.map((type) {
                    return DropdownMenuItem<BackendConnectionType>(
                      value: type,
                      child: Text(type.label),
                    );
                  }).toList(),
                  onChanged: (type) {
                    if (type == null) return;
                    unawaited(_setBackendConnectionType(type));
                  },
                ),
                enabled: _showBackendConnectionTip && _backendQuickTipStep < 2,
              ),
            ),
            if (_settings.backendConnectionType ==
                BackendConnectionType.embedded)
              const SizedBox(height: 8),
            if (_settings.backendConnectionType ==
                BackendConnectionType.embedded)
              _backendSettingTile(
                icon: Icons.inventory_2_rounded,
                title: 'Alternative Backends',
                subtitle:
                    'Choose an alternative embedded backend provided in the launcher.',
                trailingWidth: 290,
                trailing: Row(
                  children: [
                    SizedBox(
                      width: 42,
                      height: 42,
                      child: IconButton(
                        tooltip: selectedEmbeddedMissing
                            ? 'Backend not installed'
                            : 'Open backend folder',
                        onPressed: selectedEmbeddedMissing
                            ? null
                            : () => unawaited(_openEmbeddedBackendFolder()),
                        icon: const Icon(Icons.folder_open_rounded, size: 20),
                      ),
                    ),
                    const SizedBox(width: 8),
                    SizedBox(
                      width: 240,
                      child: _tipPulseGlowIf(
                        DropdownButtonFormField<EmbeddedBackendType>(
                          key: ValueKey(_settings.embeddedBackendType),
                          initialValue: _settings.embeddedBackendType,
                          decoration: _backendFieldDecoration(),
                          items: EmbeddedBackendType.values.map((backend) {
                            return DropdownMenuItem<EmbeddedBackendType>(
                              value: backend,
                              child: Text(backend.label),
                            );
                          }).toList(),
                          onChanged: embeddedBackendSelectorLocked
                              ? null
                              : (backend) {
                                  if (backend == null) return;
                                  unawaited(_setEmbeddedBackendType(backend));
                                },
                        ),
                        enabled:
                            _showBackendConnectionTip &&
                            _backendQuickTipStep == 2 &&
                            !embeddedBackendSelectorLocked,
                      ),
                    ),
                  ],
                ),
              ),
            if (_settings.backendConnectionType == BackendConnectionType.remote)
              const SizedBox(height: 8),
            if (_settings.backendConnectionType == BackendConnectionType.remote)
              _backendSettingTile(
                icon: Icons.language_rounded,
                title: 'Host',
                subtitle: 'The hostname of the backend',
                trailing: TextField(
                  controller: _backendHostController,
                  keyboardType: TextInputType.url,
                  decoration: _backendFieldDecoration(hintText: 'Enter IP Here')
                      .copyWith(
                        suffixIconConstraints: const BoxConstraints.tightFor(
                          width: 40,
                          height: 40,
                        ),
                        suffixIcon: _tipPulseGlowIf(
                          SizedBox(
                            width: 40,
                            height: 40,
                            child: IconButton(
                              tooltip: 'Save backend',
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints.tightFor(
                                width: 40,
                                height: 40,
                              ),
                              onPressed: () =>
                                  unawaited(_saveCurrentRemoteBackend()),
                              icon: const Icon(
                                Icons.bookmark_add_rounded,
                                size: 18,
                              ),
                            ),
                          ),
                          enabled:
                              _showBackendConnectionTip &&
                              _backendQuickTipStep == 3,
                        ),
                      ),
                  onChanged: (value) {
                    final trimmed = value.trim();
                    setState(() {
                      _settings = _settings.copyWith(
                        remoteBackendHost: trimmed,
                        backendHost: trimmed,
                      );
                    });
                    unawaited(_saveSettings(toast: false));
                    unawaited(_refreshRuntime());
                  },
                ),
              ),
            if (_settings.backendConnectionType !=
                BackendConnectionType.embedded)
              const SizedBox(height: 8),
            if (_settings.backendConnectionType !=
                BackendConnectionType.embedded)
              _backendSettingTile(
                icon: Icons.numbers_rounded,
                title: 'Port',
                subtitle: 'The port of the backend',
                trailing: TextField(
                  controller: _backendPortController,
                  keyboardType: TextInputType.number,
                  inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                  decoration: _backendFieldDecoration(hintText: '3551'),
                  onChanged: (value) {
                    final parsed = int.tryParse(value);
                    if (parsed == null || parsed <= 0) return;
                    setState(() {
                      if (_settings.backendConnectionType !=
                          BackendConnectionType.remote) {
                        _settings = _settings.copyWith(
                          localBackendPort: parsed,
                          backendPort: parsed,
                        );
                      } else {
                        _settings = _settings.copyWith(
                          remoteBackendPort: parsed,
                          backendPort: parsed,
                        );
                      }
                    });
                    unawaited(_saveSettings(toast: false));
                    unawaited(_refreshRuntime());
                  },
                ),
              ),
            if (_settings.backendConnectionType ==
                BackendConnectionType.embedded)
              const SizedBox(height: 8),
            if (_settings.backendConnectionType ==
                BackendConnectionType.embedded)
              _backendSettingTile(
                icon: Icons.terminal_rounded,
                title: 'Backend Terminal',
                subtitle:
                    "Show the backend's process terminal for logs and more.",
                trailingWidth: 88,
                trailing: Align(
                  alignment: Alignment.centerRight,
                  child: Switch(
                    value: _settings.backendTerminalEnabled,
                    onChanged: (value) {
                      setState(() {
                        _settings = _settings.copyWith(
                          backendTerminalEnabled: value,
                        );
                      });
                      unawaited(_saveSettings(toast: false));
                    },
                  ),
                ),
              ),
            const SizedBox(height: 12),
            LayoutBuilder(
              builder: (context, constraints) {
                final compactActions = constraints.maxWidth < 980;
                final backendLaunchEnabled = selectedEmbeddedMissing
                    ? _downloadingBackend == null
                    : canUseManagedBackend &&
                          !backendActionBusy &&
                          (_settings.backendConnectionType ==
                                  BackendConnectionType.embedded ||
                              _atlasBackendProcess != null ||
                              !_backendOnline);
                const buttonTextStyle = TextStyle(
                  fontWeight: FontWeight.w700,
                  fontSize: 15,
                );

                final launchButton = FilledButton.icon(
                  onPressed: backendLaunchEnabled
                      ? (selectedEmbeddedMissing
                            ? () => unawaited(
                                _downloadEmbeddedBackend(
                                  selectedEmbeddedBackend,
                                ),
                              )
                            : _atlasBackendProcess != null
                            ? _stopManagedBackend
                            : _launchManagedBackend)
                      : null,
                  style: FilledButton.styleFrom(
                    backgroundColor: secondary.withValues(alpha: 0.92),
                    foregroundColor: Colors.white,
                    disabledBackgroundColor: onSurface.withValues(alpha: 0.15),
                    disabledForegroundColor: onSurface.withValues(alpha: 0.58),
                    minimumSize: const Size.fromHeight(48),
                    padding: const EdgeInsets.symmetric(vertical: 13),
                    shape: const StadiumBorder(),
                    textStyle: buttonTextStyle,
                    elevation: 0,
                  ),
                  icon: Icon(
                    selectedEmbeddedMissing
                        ? Icons.download_rounded
                        : _atlasBackendProcess != null
                        ? Icons.stop_rounded
                        : Icons.play_arrow_rounded,
                    size: 18,
                  ),
                  label: Text(backendLaunchLabel),
                );

                final checkButton = FilledButton.tonalIcon(
                  onPressed: backendActionBusy ? null : _checkBackendNow,
                  style: FilledButton.styleFrom(
                    backgroundColor: secondary.withValues(alpha: 0.92),
                    foregroundColor: Colors.white,
                    disabledBackgroundColor: onSurface.withValues(alpha: 0.15),
                    disabledForegroundColor: onSurface.withValues(alpha: 0.58),
                    minimumSize: const Size.fromHeight(48),
                    padding: const EdgeInsets.symmetric(vertical: 13),
                    shape: const StadiumBorder(),
                    textStyle: buttonTextStyle,
                    elevation: 0,
                  ),
                  icon: const Icon(Icons.network_check_rounded, size: 18),
                  label: Text(
                    _backendConnectionActionBusy
                        ? backendBusyLabel
                        : 'Check Backend',
                  ),
                );

                // Third action button is mode-dependent:
                //  - Embedded: "Delete Backend" removes the selected backend.
                //  - Local: "Reset" reverts the port to default.
                //  - Remote: "Reset" clears the host IP and reverts the port.
                final Widget resetButton;
                if (_settings.backendConnectionType ==
                    BackendConnectionType.embedded) {
                  final canDelete =
                      !backendActionBusy &&
                      _downloadingBackend == null &&
                      _atlasBackendProcess == null &&
                      _embeddedBackendInstalled(selectedEmbeddedBackend);
                  const deleteColor = Color(0xFFB3261E);
                  resetButton = FilledButton.icon(
                    onPressed: canDelete
                        ? _deleteSelectedEmbeddedBackend
                        : null,
                    style: FilledButton.styleFrom(
                      backgroundColor: deleteColor,
                      foregroundColor: Colors.white,
                      disabledBackgroundColor: onSurface.withValues(
                        alpha: 0.15,
                      ),
                      disabledForegroundColor: onSurface.withValues(
                        alpha: 0.58,
                      ),
                      minimumSize: const Size.fromHeight(48),
                      padding: const EdgeInsets.symmetric(vertical: 13),
                      shape: const StadiumBorder(),
                      textStyle: buttonTextStyle,
                    ),
                    icon: const Icon(Icons.delete_outline_rounded, size: 18),
                    label: const Text('Delete Backend'),
                  );
                } else {
                  final isRemote =
                      _settings.backendConnectionType ==
                      BackendConnectionType.remote;
                  resetButton = OutlinedButton.icon(
                    onPressed: backendActionBusy
                        ? null
                        : (isRemote
                              ? _resetRemoteBackendEndpoint
                              : _resetLocalBackendPort),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: onSurface.withValues(alpha: 0.9),
                      side: BorderSide(
                        color: onSurface.withValues(alpha: 0.22),
                      ),
                      backgroundColor: onSurface.withValues(alpha: 0.03),
                      minimumSize: const Size.fromHeight(48),
                      padding: const EdgeInsets.symmetric(vertical: 13),
                      shape: const StadiumBorder(),
