  void _updateAtlasBackendInstallDialog({
    required String message,
    double? progress,
  }) {
    final normalized = progress?.clamp(0.0, 1.0).toDouble();
    _atlasBackendInstallProgress.value = _BackendInstallProgress(
      message: message,
      progress: normalized,
    );
  }

  Future<void> _hideAtlasBackendInstallDialog() async {
    if (!_atlasBackendInstallDialogVisible) return;
    for (var attempt = 0; attempt < 8; attempt++) {
      final dialogContext = _atlasBackendInstallDialogContext;
      if (dialogContext != null) {
        if (!dialogContext.mounted) {
          _atlasBackendInstallDialogContext = null;
          _atlasBackendInstallDialogVisible = false;
          return;
        }
        _atlasBackendInstallDialogContext = null;
        _atlasBackendInstallDialogVisible = false;
        Navigator.of(dialogContext, rootNavigator: true).pop();
        return;
      }
      await Future<void>.delayed(const Duration(milliseconds: 40));
      if (!_atlasBackendInstallDialogVisible) return;
    }
    _atlasBackendInstallDialogVisible = false;
    _atlasBackendInstallDialogContext = null;
  }

  Future<String?> _fetchAtlasBackendInstallerUrl() async {
    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 8)
      ..userAgent = 'ATLAS-Link';
    try {
      Future<dynamic> fetchGitHubJson(String url) async {
        final request = await client.getUrl(Uri.parse(url));
        request.followRedirects = true;
        request.maxRedirects = 8;
        request.headers.set('Accept', 'application/vnd.github+json');
        final response = await request.close();
        final body = await response.transform(utf8.decoder).join();
        if (response.statusCode != 200) {
          final remaining = response.headers.value('x-ratelimit-remaining');
          final hint = remaining == null || remaining.trim().isEmpty
              ? ''
              : ' (rate remaining $remaining)';
          _log(
            'backend',
            'GitHub API request failed ($url): HTTP ${response.statusCode}$hint',
          );
          return null;
        }
        if (body.trim().isEmpty) return null;
        try {
          return jsonDecode(body);
        } catch (_) {
          return null;
        }
      }

      final latest = await fetchGitHubJson(_atlasBackendLatestReleaseApi);
      if (latest is Map<String, dynamic>) {
        final picked = AtlasBackendInstallSupport.selectInstallerUrl(
          latest['assets'],
        );
        if (picked != null) return picked;
      }

      // Fallback: scan recent releases in case /latest is missing assets, points
      // at an older tag, or the installer was attached to a different release.
      final recent = await fetchGitHubJson(
        'https://api.github.com/repos/cipherfps/ATLAS-Backend/releases?per_page=12',
      );
      if (recent is! List) return null;

      String? scanReleases({required bool includePrerelease}) {
        for (final release in recent) {
          if (release is! Map<String, dynamic>) continue;
          if (release['draft'] == true) continue;
          if (!includePrerelease && release['prerelease'] == true) continue;
          final picked = AtlasBackendInstallSupport.selectInstallerUrl(
            release['assets'],
          );
          if (picked != null) return picked;
        }
        return null;
      }

      return scanReleases(includePrerelease: false) ??
          scanReleases(includePrerelease: true);
    } catch (error) {
      _log('backend', 'Failed to resolve backend installer URL: $error');
      return null;
    } finally {
      client.close(force: true);
    }
  }

  /// Pulls a Google Drive file id out of any of its common share URL shapes.
  String? _extractGoogleDriveFileId(String url) {
    for (final pattern in const <String>[
      r'/file/d/([A-Za-z0-9_-]{10,})',
      r'/d/([A-Za-z0-9_-]{10,})',
      r'[?&]id=([A-Za-z0-9_-]{10,})',
    ]) {
      final match = RegExp(pattern).firstMatch(url);
      if (match != null) return match.group(1);
    }
    return null;
  }

  /// Scrapes a MediaFire file page for its real direct-download URL.
  Future<String?> _resolveMediaFireDirectUrl(String pageUrl) async {
    try {
      final html = await _downloadText(pageUrl);
      final href = RegExp(
        r'href="(https?://download[^"]+\.mediafire\.com/[^"]+)"',
      ).firstMatch(html);
      if (href != null) return href.group(1);
      // Newer pages base64-encode the link in a data attribute.
      final scrambled = RegExp(
        r'data-scrambled-url="([^"]+)"',
      ).firstMatch(html);
      if (scrambled != null) {
        try {
          final decoded = utf8.decode(
            base64.decode(scrambled.group(1)!.trim()),
          );
          if (decoded.startsWith('http')) return decoded;
        } catch (_) {}
      }
      return null;
    } catch (error) {
      _log('mods', 'Failed to resolve MediaFire link $pageUrl: $error');
      return null;
    }
  }

  /// Converts known share-link hosts into direct download URLs. Direct/raw
  /// links (including GitHub) pass through unchanged. MEGA can't be fetched
  /// with a plain GET (end-to-end encrypted), so it fails with a clear message.
  Future<String> _resolveModDownloadUrl(String url) async {
    final trimmed = url.trim();
    final uri = Uri.tryParse(trimmed);
    if (uri == null || (uri.scheme != 'http' && uri.scheme != 'https')) {
      return trimmed;
    }
    final host = uri.host.toLowerCase();

    if (host.contains('mega.nz') || host.contains('mega.co.nz')) {
      throw 'MEGA links are not supported. Host the file on a direct-download '
          'URL instead.';
    }

    if (host.contains('drive.google.com') || host.contains('docs.google.com')) {
      final id = _extractGoogleDriveFileId(trimmed);
      if (id != null && id.isNotEmpty) {
        // The usercontent endpoint serves large files without the virus-scan
        // interstitial that the classic uc?export=download URL shows.
        return 'https://drive.usercontent.google.com/download'
            '?id=$id&export=download&confirm=t';
      }
      return trimmed;
    }

    if (host.contains('mediafire.com')) {
      if (host.startsWith('download')) return trimmed; // already direct
      return await _resolveMediaFireDirectUrl(trimmed) ?? trimmed;
    }

    return trimmed;
  }

  Future<void> _downloadToFile(
    String url,
    File destination, {
    void Function(int receivedBytes, int? totalBytes)? onProgress,
    // For mod files: rewrite known share-link hosts (Google Drive, MediaFire)
    // into direct download URLs, and reject HTML landing pages so they can't be
    // saved as a pak/dll.
    bool resolveShareLinks = false,
    bool rejectHtmlResponse = false,
    // Polled during the transfer; returning true aborts the download (the
    // partial file is dropped and [_kModDownloadCancelled] is thrown).
    bool Function()? isCancelled,
  }) async {
    if (isCancelled?.call() ?? false) throw _kModDownloadCancelled;
    final trimmed = url.trim();
    final uri = Uri.tryParse(trimmed);
    if (uri?.scheme.toLowerCase() == 'file') {
      final source = File(uri!.toFilePath());
      final length = await source.exists() ? await source.length() : 0;
      await source.copy(destination.path);
      onProgress?.call(length, length);
      return;
    }
    if (uri == null || (uri.scheme != 'http' && uri.scheme != 'https')) {
      final source = File(trimmed);
      if (await source.exists()) {
        final length = await source.length();
        await source.copy(destination.path);
        onProgress?.call(length, length);
        return;
      }
    }

    final client = HttpClient()
      ..connectionTimeout = const Duration(seconds: 20)
      ..userAgent = 'ATLAS-Link';
    // Download to a temp file and atomically swap it into place on success, so
    // an interrupted or stalled download can never leave a partial/corrupt file
    // at the destination.
    final partFile = File('${destination.path}.part');
    IOSink? sink;
    try {
      final effectiveUrl = resolveShareLinks
          ? await _resolveModDownloadUrl(trimmed)
          : trimmed;
      final request = await client.getUrl(Uri.parse(effectiveUrl));
      request.followRedirects = true;
      request.maxRedirects = 8;
      final response = await request.close();
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw 'Download failed (HTTP ${response.statusCode}).';
      }
      if (rejectHtmlResponse) {
        final mime = response.headers.contentType?.mimeType.toLowerCase() ?? '';
        if (mime == 'text/html' || mime == 'application/xhtml+xml') {
          throw 'Download did not return a file (got an HTML page). Use a '
              'direct download link.';
        }
      }
      sink = partFile.openWrite();
      final totalBytes = response.contentLength > 0
          ? response.contentLength
          : null;
      var receivedBytes = 0;
      // Idle timeout: if no data arrives for a while, fail instead of hanging
      // forever on a stalled connection.
      await for (final chunk in response.timeout(const Duration(seconds: 60))) {
        if (isCancelled?.call() ?? false) throw _kModDownloadCancelled;
        sink.add(chunk);
        receivedBytes += chunk.length;
        onProgress?.call(receivedBytes, totalBytes);
      }
      await sink.flush();
      await sink.close();
      sink = null;
      if (await destination.exists()) {
        await destination.delete();
      }
      await partFile.rename(destination.path);
    } catch (_) {
      // Drop the partial temp file; leave any existing destination untouched.
      try {
        await sink?.close();
      } catch (_) {}
      sink = null;
      try {
        if (await partFile.exists()) await partFile.delete();
      } catch (_) {}
      rethrow;
    } finally {
      try {
        await sink?.close();
      } catch (_) {}
      client.close(force: true);
    }
  }

  Future<String?> _detectWindowsInstallerExtension(File file) async {
    RandomAccessFile? raf;
    try {
      raf = await file.open();
      final header = await raf.read(8);
      if (header.length >= 2 && header[0] == 0x4D && header[1] == 0x5A) {
        return '.exe';
      }
      const oleMagic = <int>[0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1];
      if (header.length >= 8) {
        var matchesOle = true;
        for (var i = 0; i < oleMagic.length; i++) {
          if (header[i] != oleMagic[i]) {
            matchesOle = false;
            break;
          }
        }
        if (matchesOle) return '.msi';
      }
      return null;
    } catch (_) {
      return null;
    } finally {
      try {
        await raf?.close();
      } catch (_) {
        // Ignore header read close failures.
      }
    }
  }

  String _formatByteSize(int bytes) {
    if (bytes < 1024) return '$bytes B';
    const units = <String>['KB', 'MB', 'GB', 'TB'];
    var value = bytes / 1024.0;
    var unitIndex = 0;
    while (value >= 1024 && unitIndex < units.length - 1) {
      value /= 1024;
      unitIndex++;
    }
    final digits = value >= 100
        ? 0
        : value >= 10
        ? 1
        : 2;
    return '${value.toStringAsFixed(digits)} ${units[unitIndex]}';
  }

  Future<String?> _findInstalledAtlasBackendExecutable() async {
    final candidates = <String>[];
    void addWithNames(String? dirPath) {
      if (dirPath == null || dirPath.trim().isEmpty) return;
      candidates.addAll(
        AtlasBackendInstallSupport.executableCandidatesForRoot(dirPath),
      );
    }

    final configuredPath = _settings.backendWorkingDirectory.trim();
    if (configuredPath.isNotEmpty) {
      final normalizedConfigured = configuredPath.replaceAll('\\', '/');
      if (normalizedConfigured.toLowerCase().endsWith('.exe') &&
          File(configuredPath).existsSync()) {
        return configuredPath;
      }
      addWithNames(configuredPath);
    }

    final localAppData = Platform.environment['LOCALAPPDATA'];
    final programFiles = Platform.environment['ProgramFiles'];
    final programFilesX86 = Platform.environment['ProgramFiles(x86)'];
    addWithNames(
      localAppData == null
          ? null
          : _joinPath([localAppData, 'Programs', 'ATLAS Backend']),
    );
    addWithNames(
      localAppData == null
          ? null
          : _joinPath([localAppData, 'Programs', 'ATLAS-Backend']),
    );
    addWithNames(
      localAppData == null ? null : _joinPath([localAppData, 'ATLAS Backend']),
    );
    addWithNames(
      localAppData == null
          ? null
          : _joinPath([localAppData, 'ATLAS Backend', 'ATLAS Backend']),
    );
    addWithNames(
      localAppData == null ? null : _joinPath([localAppData, 'ATLAS']),
    );
    addWithNames(
      programFiles == null ? null : _joinPath([programFiles, 'ATLAS Backend']),
    );
    addWithNames(
      programFiles == null ? null : _joinPath([programFiles, 'ATLAS-Backend']),
    );
    addWithNames(
      programFiles == null ? null : _joinPath([programFiles, 'ATLAS']),
    );
    addWithNames(
      programFilesX86 == null
          ? null
          : _joinPath([programFilesX86, 'ATLAS Backend']),
    );
    addWithNames(
      programFilesX86 == null
          ? null
          : _joinPath([programFilesX86, 'ATLAS-Backend']),
    );
    addWithNames(
      programFilesX86 == null ? null : _joinPath([programFilesX86, 'ATLAS']),
    );

    final seen = <String>{};
    for (final candidate in candidates) {
      final normalized = candidate.toLowerCase();
      if (!seen.add(normalized)) continue;
      if (File(candidate).existsSync()) return candidate;
    }

    final appData = Platform.environment['APPDATA'];
    final scanRoots = <String>[
      if (localAppData != null && localAppData.trim().isNotEmpty)
        _joinPath([localAppData, 'Programs']),
      if (localAppData != null && localAppData.trim().isNotEmpty) localAppData,
      if (appData != null && appData.trim().isNotEmpty) appData,
      if (programFiles != null && programFiles.trim().isNotEmpty) programFiles,
      if (programFilesX86 != null && programFilesX86.trim().isNotEmpty)
        programFilesX86,
    ];
    for (final root in scanRoots) {
      final found = await _scanForAtlasBackendExecutableUnder(
        root,
        maxDepth: root.toLowerCase().endsWith('programs') ? 4 : 3,
      );
      if (found != null) return found;
    }

    return _findInstalledAtlasBackendExecutableFromRegistry();
  }

  Future<String?> _scanForAtlasBackendExecutableUnder(
    String rootPath, {
    int maxDepth = 3,
  }) async {
    final root = Directory(rootPath);
    if (!await root.exists()) return null;

    final queue = ListQueue<_DirectoryDepth>()
      ..add(_DirectoryDepth(directory: root, depth: 0));
    while (queue.isNotEmpty) {
      final current = queue.removeFirst();
      try {
        await for (final entity in current.directory.list(followLinks: false)) {
          if (entity is File) {
            final fileName = _basename(entity.path).toLowerCase();
            final lowerPath = entity.path.toLowerCase();
            if (fileName.endsWith('.exe') &&
                ((fileName.contains('atlas') && fileName.contains('backend')) ||
                    (fileName == 'atlas_gui_flutter.exe' &&
                        lowerPath.contains('atlas')) ||
                    (fileName == 'atlas.exe' &&
                        (lowerPath.contains('\\atlas backend\\') ||
                            lowerPath.contains('/atlas backend/') ||
                            lowerPath.contains('\\atlas-backend\\') ||
                            lowerPath.contains('/atlas-backend/'))))) {
              return entity.path;
            }
          } else if (entity is Directory && current.depth < maxDepth) {
            queue.add(
              _DirectoryDepth(directory: entity, depth: current.depth + 1),
            );
          }
        }
      } catch (_) {
        // Skip unreadable directories.
      }
    }
    return null;
  }

  Future<String?> _findInstalledAtlasBackendExecutableFromRegistry() async {
    const script = r'''
$paths = @(
  'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
  'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
  'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
)
$entries = Get-ItemProperty -Path $paths -ErrorAction SilentlyContinue |
  Where-Object { $_.DisplayName -like '*ATLAS*' }
foreach ($entry in $entries) {
  if ($entry.DisplayIcon) {
    Write-Output $entry.DisplayIcon
  }
  if ($entry.InstallLocation) {
    $loc = $entry.InstallLocation.ToString().Trim()
    Write-Output (Join-Path $loc 'ATLAS Backend.exe')
    Write-Output (Join-Path $loc 'ATLAS-Backend.exe')
    Write-Output (Join-Path $loc 'ATLAS.exe')
  }
}
$appPathRoots = @(
  'HKCU:\Software\Microsoft\Windows\CurrentVersion\App Paths\*.exe',
  'HKLM:\Software\Microsoft\Windows\CurrentVersion\App Paths\*.exe',
  'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths\*.exe'
)
$appPaths = Get-ItemProperty -Path $appPathRoots -ErrorAction SilentlyContinue |
  Where-Object { $_.PSChildName -like '*atlas*backend*.exe' }
foreach ($app in $appPaths) {
  if ($app.'(default)') {
    Write-Output $app.'(default)'
  }
  if ($app.Path) {
    $loc = $app.Path.ToString().Trim()
    Write-Output (Join-Path $loc 'ATLAS Backend.exe')
    Write-Output (Join-Path $loc 'ATLAS-Backend.exe')
  }
}
''';
    try {
      final result = await Process.run('powershell', [
        '-NoProfile',
        '-ExecutionPolicy',
        'Bypass',
        '-Command',
        script,
      ], runInShell: true);
      if (result.exitCode != 0) return null;
      final lines = result.stdout.toString().split(RegExp(r'\r?\n'));
      for (final raw in lines) {
        var candidate = raw.trim();
        if (candidate.isEmpty) continue;
        candidate = candidate.replaceAll('"', '');
        candidate = candidate.replaceFirst(RegExp(r',\s*\d+$'), '');
        if (File(candidate).existsSync()) return candidate;
      }
      return null;
    } catch (_) {
      return null;
    }
  }

  Future<void> _checkBackendNow() async {
    return _checkBackendNowWithStatus();
  }

  Future<void> _checkBackendNowWithStatus({
    String busyMessage = 'Checking Backend...',
  }) async {
    if (_backendActionBusy) return;
    if (_settings.backendConnectionType == BackendConnectionType.remote) {
      final host = _backendHostController.text.trim();
      if (host.isEmpty) {
        _toast('Remote host is required');
        return;
      }
    }
    if (mounted) {
      setState(() {
        _backendConnectionActionBusy = true;
        _backendActionMessage = busyMessage;
      });
    } else {
      _backendConnectionActionBusy = true;
      _backendActionMessage = busyMessage;
    }
    _toastProgress(busyMessage, progress: null, indeterminate: true);
    try {
      await _saveSettings(toast: false);
      await _refreshRuntime(force: true);
      if (!mounted) return;
      final configured =
          '${_effectiveBackendHost()}:${_effectiveBackendPort()}';
      if (_backendOnline) {
        _toast('Connected to backend on $configured');
      } else {
        _toast('No backend detected on $configured');
      }
    } finally {
      _toastProgressDismiss();
      if (mounted) {
        setState(() {
          _backendConnectionActionBusy = false;
          _backendActionMessage = '';
        });
      } else {
        _backendConnectionActionBusy = false;
        _backendActionMessage = '';
      }
    }
  }

  // Local mode reset: revert the backend port back to the default.
  Future<void> _resetLocalBackendPort() async {
    setState(() {
      _settings = _settings.copyWith(
        localBackendPort: _defaultBackendPort,
        backendPort: _defaultBackendPort,
      );
      _backendPortController.text = _defaultBackendPort.toString();
    });
    await _saveSettings(toast: false);
    await _refreshRuntime();
    if (mounted) {
      _toast('Backend port reset to $_defaultBackendPort');
    }
  }

  // Remote mode reset: clear the saved host IP and revert to the default port.
  Future<void> _resetRemoteBackendEndpoint() async {
    setState(() {
      _settings = _settings.copyWith(
        remoteBackendHost: '',
        backendHost: '',
        remoteBackendPort: _defaultBackendPort,
        backendPort: _defaultBackendPort,
      );
      _backendHostController.text = '';
      _backendPortController.text = _defaultBackendPort.toString();
    });
    await _saveSettings(toast: false);
    await _refreshRuntime();
    if (mounted) {
      _toast('Remote backend reset');
    }
  }

  // The installed backend payloads live next to the executable. Using this
  // explicit path (rather than the working-directory search) ensures deletes
  // never touch a development source tree.
  String _installedEmbeddedBackendRoot() {
    final exeDir = File(Platform.resolvedExecutable).parent.path;
    return _joinPath([exeDir, 'data', 'flutter_assets', 'assets', 'backend']);
  }

  String _embeddedBackendFolderName(EmbeddedBackendType backend) =>
      backend.bundledAssetDirectory.split('/').last;

  String _embeddedBackendExeName(EmbeddedBackendType backend) =>
      backend.executableAssetPath.split('/').last;

  // Embedded mode "Delete Backend": remove the currently selected embedded
  // backend from disk so the Backend tab shows "Download" again.
  Future<void> _deleteSelectedEmbeddedBackend() async {
    final backend = _settings.embeddedBackendType;
    if (_downloadingBackend != null) return;
    if (_atlasBackendProcess != null) {
      _toast('Stop ${backend.label} before deleting it');
      return;
    }
    if (!_embeddedBackendInstalled(backend)) {
      _toast('${backend.label} is not installed');
      return;
    }

    Future<void> deleteDir(Directory dir) async {
      try {
        if (await dir.exists()) await dir.delete(recursive: true);
      } catch (_) {
        // Ignore cleanup failures (locks, permissions, etc.).
      }
    }

    Future<void> deleteFile(File file) async {
      try {
        if (await file.exists()) await file.delete();
      } catch (_) {
        // Ignore cleanup failures (locks, permissions, etc.).
      }
    }

    try {
      await _cleanupOrphanedEmbeddedBackendProcesses(force: true);
      final root = _installedEmbeddedBackendRoot();
      await deleteDir(
        Directory(_joinPath([root, _embeddedBackendFolderName(backend)])),
      );
      await deleteFile(
        File(_joinPath([root, 'bin', _embeddedBackendExeName(backend)])),
      );

      // Remove the shared Node runtime (and the bin folder) only when no other
      // embedded backend still needs it.
      final otherStillInstalled = EmbeddedBackendType.values
          .where((other) => other != backend)
          .any(
            (other) => Directory(
              _joinPath([root, _embeddedBackendFolderName(other)]),
            ).existsSync(),
          );
      if (!otherStillInstalled) {
        await deleteDir(Directory(_joinPath([root, 'node'])));
        await deleteDir(Directory(_joinPath([root, 'bin'])));
      }

      if (mounted) {
        setState(() {});
        _toast('${backend.label} deleted');
      }
      await _refreshRuntime();
    } catch (error) {
      _log('backend', 'Failed to delete ${backend.label}: $error');
      if (mounted) _toast('Failed to delete ${backend.label}');
    }
  }

  String _backendHostKey(String host) {
    final normalized = host
        .trim()
        .toLowerCase()
        .replaceFirst(RegExp(r'^http://', caseSensitive: false), '')
        .replaceFirst(RegExp(r'^https://', caseSensitive: false), '')
        .split('/')
        .first;
    final bare = normalized.startsWith('[')
        ? normalized.split(']').first.replaceFirst('[', '')
        : normalized.split(':').first;
    return bare.trim();
  }

  String _savedBackendStatusKey(String host, int port) {
    return '${_backendHostKey(host)}:$port';
  }

  void _refreshSavedBackendStatus(SavedBackend entry, {bool force = false}) {
    final key = _savedBackendStatusKey(entry.host, entry.port);
    final cached = _savedBackendStatusCache[key];
    if (!force &&
        cached != null &&
        DateTime.now().difference(cached.checkedAt) <
            const Duration(seconds: 30)) {
      return;
    }
    if (!_savedBackendStatusRefreshInFlight.add(key)) return;

    unawaited(
      Future<void>(() async {
        try {
          final online = await _pingBackend(entry.host, entry.port) != null;
          if (!mounted) {
            _savedBackendStatusCache[key] = (
              online: online,
              checkedAt: DateTime.now(),
            );
            return;
          }
          setState(() {
            _savedBackendStatusCache[key] = (
              online: online,
              checkedAt: DateTime.now(),
            );
          });
        } finally {
          _savedBackendStatusRefreshInFlight.remove(key);
        }
      }),
    );
  }

  Future<void> _saveCurrentRemoteBackend() async {
    if (!mounted) return;
    if (_settings.backendConnectionType != BackendConnectionType.remote) return;

    final host = _backendHostController.text.trim();
    if (host.isEmpty) {
      _toast('Enter a backend host first');
      return;
    }

    final port =
        int.tryParse(_backendPortController.text.trim()) ??
        _effectiveBackendPort();
    if (port <= 0 || port > 65535) {
      _toast('Enter a valid backend port');
      return;
    }

    final name = await _promptSavedBackendName();
    if (!mounted) return;
    final trimmedName = (name ?? '').trim();
    if (trimmedName.isEmpty) return;

    final next = List<SavedBackend>.from(_settings.savedBackends);
    final lower = trimmedName.toLowerCase();
    final nameConflict = next.any(
      (entry) => entry.name.trim().toLowerCase() == lower,
    );
    if (nameConflict) {
      _toast('A saved backend with that name already exists');
      return;
    }

    final hostKey = _backendHostKey(host);
    final endpointConflict = next.any(
      (entry) => _backendHostKey(entry.host) == hostKey && entry.port == port,
    );
    if (endpointConflict) {
      _toast('That backend (IP + port) is already saved');
      return;
    }

    final entry = SavedBackend(name: trimmedName, host: host, port: port);
    next.add(entry);

    setState(() {
      _settings = _settingsWithSavedBackendsForActiveProfile(next);
    });
    _refreshSavedBackendStatus(entry, force: true);
    await _saveSettings(toast: false, applyControllers: false);
    if (mounted) _toast('Saved backend: ${entry.name}');
  }

  Future<void> _editSavedBackend(SavedBackend entry) async {
    if (!mounted) return;
    final index = _settings.savedBackends.indexWhere(
      (candidate) =>
          candidate.name == entry.name &&
          candidate.host == entry.host &&
          candidate.port == entry.port,
    );
    if (index < 0) return;

    final others = <SavedBackend>[];
    for (var i = 0; i < _settings.savedBackends.length; i++) {
      if (i == index) continue;
      others.add(_settings.savedBackends[i]);
    }

    final updated = await _promptEditSavedBackend(entry, others: others);
    if (!mounted) return;
    if (updated == null) return;

    final next = List<SavedBackend>.from(_settings.savedBackends);
    next[index] = updated;
    _savedBackendStatusCache.remove(
      _savedBackendStatusKey(entry.host, entry.port),
    );
    setState(() {
      _settings = _settingsWithSavedBackendsForActiveProfile(next);
    });
    _refreshSavedBackendStatus(updated, force: true);
    await _saveSettings(toast: false, applyControllers: false);
    if (mounted) _toast('Updated backend: ${updated.name}');
  }

  Future<SavedBackend?> _promptEditSavedBackend(
    SavedBackend entry, {
    required List<SavedBackend> others,
  }) async {
    if (!mounted) return null;

    final nameController = TextEditingController(text: entry.name);
    final hostController = TextEditingController(text: entry.host);
    final portController = TextEditingController(text: entry.port.toString());
    var nameError = '';
    var hostError = '';
    var portError = '';

    void clearErrors(StateSetter setDialogState) {
      if (nameError.isEmpty && hostError.isEmpty && portError.isEmpty) return;
      setDialogState(() {
        nameError = '';
        hostError = '';
        portError = '';
      });
    }

    final result = await showGeneralDialog<SavedBackend>(
      context: context,
      barrierDismissible: true,
      barrierLabel: MaterialLocalizations.of(context).modalBarrierDismissLabel,
      barrierColor: Colors.transparent,
      transitionDuration: const Duration(milliseconds: 240),
      pageBuilder: (dialogContext, animation, secondaryAnimation) {
        final onSurface = Theme.of(dialogContext).colorScheme.onSurface;
        final secondary = Theme.of(dialogContext).colorScheme.secondary;
        final maxHeight = min(
          640.0,
          MediaQuery.sizeOf(dialogContext).height - 40,
        );

        void submit(StateSetter setDialogState) {
          final name = nameController.text.trim();
          final host = hostController.text.trim();
          final portRaw = portController.text.trim();

          var nextNameError = '';
          var nextHostError = '';
          var nextPortError = '';

          if (name.isEmpty) nextNameError = 'Name is required';
          if (host.isEmpty) nextHostError = 'Host is required';

          final parsedPort = int.tryParse(portRaw);
          if (parsedPort == null || parsedPort <= 0 || parsedPort > 65535) {
            nextPortError = 'Invalid port';
          }

          if (nextNameError.isEmpty) {
            final lower = name.toLowerCase();
            final nameConflict = others.any(
              (other) => other.name.trim().toLowerCase() == lower,
            );
            if (nameConflict) {
              nextNameError = 'Name already exists';
            }
          }

          if (nextHostError.isEmpty && nextPortError.isEmpty) {
            final hostKey = _backendHostKey(host);
            final endpointConflict = others.any(
              (other) =>
                  _backendHostKey(other.host) == hostKey &&
                  other.port == parsedPort,
            );
            if (endpointConflict) {
              nextHostError = 'Backend already saved';
            }
          }

          if (nextNameError.isNotEmpty ||
              nextHostError.isNotEmpty ||
              nextPortError.isNotEmpty) {
            setDialogState(() {
              nameError = nextNameError;
              hostError = nextHostError;
              portError = nextPortError;
            });
            return;
          }

          Navigator.of(
            dialogContext,
          ).pop(SavedBackend(name: name, host: host, port: parsedPort!));
        }

        InputDecoration fieldDecoration({
          required String label,
          required String error,
          String? hint,
        }) {
          return InputDecoration(
            labelText: label,
            hintText: hint,
            isDense: true,
            filled: true,
            fillColor: _onSurface(dialogContext, 0.06),
            contentPadding: const EdgeInsets.symmetric(
              horizontal: 14,
              vertical: 12,
            ),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(12),
              borderSide: BorderSide(color: _onSurface(dialogContext, 0.18)),
            ),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(12),
              borderSide: BorderSide(color: _onSurface(dialogContext, 0.18)),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(12),
              borderSide: BorderSide(color: secondary, width: 1.2),
            ),
            errorText: error.isEmpty ? null : error,
          );
        }

        return SafeArea(
          child: Center(
            child: Material(
              type: MaterialType.transparency,
              child: ConstrainedBox(
                constraints: BoxConstraints(
                  maxWidth: 620,
                  maxHeight: maxHeight,
                ),
                child: StatefulBuilder(
                  builder: (dialogContext, setDialogState) {
                    return Container(
                      decoration: BoxDecoration(
                        color: _dialogSurfaceColor(dialogContext),
                        borderRadius: BorderRadius.circular(28),
                        border: Border.all(
                          color: _onSurface(dialogContext, 0.1),
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: _dialogShadowColor(dialogContext),
                            blurRadius: 34,
                            offset: const Offset(0, 18),
                          ),
                        ],
                      ),
                      child: Padding(
                        padding: const EdgeInsets.fromLTRB(24, 22, 24, 18),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                _dialogHeaderIconBadge(
                                  dialogContext,
                                  Icons.edit_rounded,
                                ),
                                const SizedBox(width: 12),
                                Expanded(
                                  child: FittedBox(
                                    fit: BoxFit.scaleDown,
                                    alignment: Alignment.centerLeft,
                                    child: Text(
                                      'Edit Saved Backend',
                                      style: TextStyle(
                                        fontSize: 34,
                                        fontWeight: FontWeight.w700,
                                        color: _onSurface(dialogContext, 0.96),
                                      ),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 8),
                            Flexible(
                              child: SingleChildScrollView(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      'Update the saved backend name and endpoint. Names and IP:port must be unique.',
                                      style: TextStyle(
                                        fontSize: 16,
                                        fontWeight: FontWeight.w700,
                                        color: _onSurface(dialogContext, 0.74),
                                        height: 1.25,
                                      ),
                                    ),
                                    const SizedBox(height: 16),
                                    TextField(
                                      controller: nameController,
                                      textInputAction: TextInputAction.next,
                                      onChanged: (_) =>
                                          clearErrors(setDialogState),
                                      decoration: fieldDecoration(
                                        label: 'Name',
                                        hint: 'Players Backend',
                                        error: nameError,
                                      ),
                                      style: TextStyle(color: onSurface),
                                    ),
                                    const SizedBox(height: 12),
                                    TextField(
                                      controller: hostController,
                                      keyboardType: TextInputType.url,
                                      textInputAction: TextInputAction.next,
                                      onChanged: (_) =>
                                          clearErrors(setDialogState),
                                      decoration: fieldDecoration(
                                        label: 'Host',
                                        hint: 'Enter IP Here',
                                        error: hostError,
                                      ),
                                      style: TextStyle(color: onSurface),
                                    ),
                                    const SizedBox(height: 12),
                                    TextField(
                                      controller: portController,
                                      keyboardType: TextInputType.number,
                                      inputFormatters: [
                                        FilteringTextInputFormatter.digitsOnly,
                                      ],
                                      textInputAction: TextInputAction.done,
                                      onChanged: (_) =>
                                          clearErrors(setDialogState),
                                      onSubmitted: (_) =>
                                          submit(setDialogState),
                                      decoration: fieldDecoration(
                                        label: 'Port',
                                        hint: '3551',
                                        error: portError,
                                      ),
                                      style: TextStyle(color: onSurface),
                                    ),
                                    const SizedBox(height: 16),
                                    Row(
                                      children: [
                                        _dialogCancelButton(
                                          dialogContext,
                                          onPressed: () => Navigator.of(
                                            dialogContext,
                                          ).pop(null),
                                        ),
                                        const Spacer(),
                                        FilledButton.icon(
                                          onPressed: () =>
                                              submit(setDialogState),
                                          style: FilledButton.styleFrom(
                                            backgroundColor: secondary
                                                .withValues(alpha: 0.92),
                                            foregroundColor: Colors.white,
                                            shape: const StadiumBorder(),
                                            padding: const EdgeInsets.symmetric(
                                              horizontal: 18,
                                              vertical: 12,
                                            ),
                                          ),
                                          icon: const Icon(
                                            Icons.save_rounded,
                                            size: 18,
                                          ),
                                          label: const Text('Save'),
                                        ),
                                      ],
                                    ),
                                  ],
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  },
                ),
              ),
            ),
          ),
        );
      },
      transitionBuilder: (dialogContext, animation, _, child) {
        final curved = CurvedAnimation(
          parent: animation,
          curve: Curves.easeOutCubic,
        );
        return Stack(
          children: [
            Positioned.fill(
              child: _settings.popupBackgroundBlurEnabled
                  ? BackdropFilter(
                      filter: ImageFilter.blur(
                        sigmaX: 3.2 * curved.value,
                        sigmaY: 3.2 * curved.value,
                      ),
                      child: Container(
