                      child: IconButton(
                        tooltip: 'Clear search',
                        padding: EdgeInsets.zero,
                        constraints: const BoxConstraints.tightFor(
                          width: 40,
                          height: 40,
                        ),
                        onPressed: () {
                          _savedBackendSearchController.clear();
                          setState(() => _savedBackendSearchQuery = '');
