                        await _saveSettings(
                          toast: false,
                          applyControllers: false,
                        );
                        await _refreshRuntime(force: true);
                        if (mounted) {
                          _toast('Connected to ${entry.host}:${entry.port}');
                        }
                      },
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 12,
                          vertical: 10,
                        ),
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(12),
                          color: onSurface.withValues(alpha: 0.04),
                          border: Border.all(
                            color: onSurface.withValues(alpha: 0.10),
                          ),
                        ),
                        child: Row(
                          children: [
                            Tooltip(
                              message: statusTooltip,
                              child: Container(
                                width: 10,
                                height: 10,
                                decoration: BoxDecoration(
                                  shape: BoxShape.circle,
                                  color: statusColor,
                                ),
                              ),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    entry.name,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      fontWeight: FontWeight.w700,
                                      color: onSurface.withValues(alpha: 0.92),
                                    ),
                                  ),
                                  const SizedBox(height: 2),
                                  Text(
                                    '${entry.host}:${entry.port}',
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      fontWeight: FontWeight.w600,
                                      color: onSurface.withValues(alpha: 0.72),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(width: 10),
                            _versionCardAction(
                              icon: Icons.edit_rounded,
                              tooltip: 'Edit backend',
                              onTap: () => unawaited(_editSavedBackend(entry)),
                            ),
                            const SizedBox(width: 6),
                            _versionCardAction(
                              icon: Icons.delete_outline_rounded,
                              tooltip: 'Delete backend',
                              onTap: () =>
