  /// Installed DLL mods assigned to [slot], paired with the on-disk `.dll` to
  /// use. Slot assignment comes from the install record's `dataSlot`, falling
  /// back to the catalog entry for installs made before slot tracking existed.
  List<({_InstalledAtlasMod mod, String dllPath})> _installedDllsForSlot(
    _DataDllSlot slot,
  ) {
    final result = <({_InstalledAtlasMod mod, String dllPath})>[];
    for (final installed in _installedModsById.values) {
      if (installed.type != _AtlasModType.dll) continue;
      var slotValue = installed.dataSlot.trim();
      if (slotValue.isEmpty) {
        for (final mod in _modsLibrary) {
          if (mod.id == installed.id) {
            slotValue = mod.dataSlot.trim();
            break;
          }
        }
      }
      if (slotValue.isEmpty || _DataDllSlot.resolve(slotValue) != slot) {
        continue;
      }
      final dllPath = installed.installedFilePaths.firstWhere(
        (path) =>
            path.toLowerCase().endsWith('.dll') && File(path).existsSync(),
        orElse: () => '',
      );
      if (dllPath.isEmpty) continue;
      result.add((mod: installed, dllPath: dllPath));
    }
    result.sort(
      (a, b) => a.mod.name.toLowerCase().compareTo(b.mod.name.toLowerCase()),
    );
    return result;
  }

  Future<void> _uninstallInstalledDllMod(_InstalledAtlasMod installed) async {
    if (installed.type != _AtlasModType.dll) return;
    for (final path in installed.installedFilePaths) {
      try {
        final file = File(path);
        if (await file.exists()) await file.delete();
      } catch (error) {
        _log('mods', 'Failed to remove installed DLL mod file $path: $error');
      }
    }
    _installedModsById.remove(installed.id);
    await _saveInstalledMods();
    if (mounted) setState(() {});
    _toast('Removed ${installed.name}');
  }

  /// Opens the installed-DLL library for [slot] and, on selection, points the
  /// slot's path field at the chosen mod's `.dll`.
  Future<void> _pickInstalledDllForSlot(
    _DataDllSlot slot,
    TextEditingController controller,
    ValueChanged<String> onChanged,
  ) async {
    var candidates = _installedDllsForSlot(slot);
    var currentPath = controller.text.trim().toLowerCase();
    var searchQuery = '';
    final selected = await showGeneralDialog<String>(
      context: context,
      barrierDismissible: true,
      barrierLabel: MaterialLocalizations.of(context).modalBarrierDismissLabel,
      barrierColor: Colors.transparent,
      transitionDuration: const Duration(milliseconds: 220),
      pageBuilder: (dialogContext, animation, secondaryAnimation) {
        return SafeArea(
          child: Center(
            child: Material(
              type: MaterialType.transparency,
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 520),
                child: StatefulBuilder(
                  builder: (dialogContext, setDialogState) {
                    final onSurface = Theme.of(
                      dialogContext,
                    ).colorScheme.onSurface;
                    final normalizedSearch = searchQuery.trim().toLowerCase();
                    final visibleCandidates = normalizedSearch.isEmpty
                        ? candidates
                        : candidates.where((candidate) {
                            return candidate.mod.name.toLowerCase().contains(
                                  normalizedSearch,
                                ) ||
                                candidate.dllPath.toLowerCase().contains(
                                  normalizedSearch,
                                ) ||
                                _basename(
                                  candidate.dllPath,
                                ).toLowerCase().contains(normalizedSearch);
                          }).toList();

                    Future<void> removeCandidate(
                      ({_InstalledAtlasMod mod, String dllPath}) candidate,
                    ) async {
                      final removedPath = candidate.dllPath.toLowerCase();
                      await _uninstallInstalledDllMod(candidate.mod);
                      if (!dialogContext.mounted) return;
                      setDialogState(() {
                        candidates = _installedDllsForSlot(slot);
                        if (currentPath == removedPath) {
                          currentPath = '';
                          controller.clear();
                          onChanged('');
                        }
                      });
                    }

                    final searchInput = TextFormField(
                      key: ValueKey(
                        searchQuery.isEmpty
                            ? 'installed-dll-search-empty'
                            : 'installed-dll-search-active',
                      ),
                      initialValue: searchQuery,
                      onChanged: (value) {
                        setDialogState(() => searchQuery = value);
                      },
                      decoration:
                          _backendFieldDecoration(
                            hintText: 'Search DLLs by name',
                          ).copyWith(
                            prefixIcon: Icon(
                              Icons.search_rounded,
                              size: 18,
                              color: onSurface.withValues(alpha: 0.72),
                            ),
                            suffixIconConstraints:
                                const BoxConstraints.tightFor(
                                  width: 40,
                                  height: 40,
                                ),
                            suffixIcon: searchQuery.trim().isEmpty
                                ? null
                                : SizedBox(
                                    width: 40,
                                    height: 40,
                                    child: IconButton(
                                      tooltip: 'Clear search',
                                      padding: EdgeInsets.zero,
                                      constraints:
                                          const BoxConstraints.tightFor(
                                            width: 40,
                                            height: 40,
                                          ),
                                      onPressed: () {
                                        setDialogState(() => searchQuery = '');
                                      },
                                      icon: const Icon(
                                        Icons.close_rounded,
                                        size: 18,
                                      ),
                                    ),
                                  ),
                          ),
                    );

                    return Container(
                      margin: const EdgeInsets.symmetric(horizontal: 20),
                      padding: const EdgeInsets.fromLTRB(22, 20, 22, 18),
                      decoration: BoxDecoration(
                        color: _dialogSurfaceColor(dialogContext),
                        borderRadius: BorderRadius.circular(22),
                        border: Border.all(
                          color: _onSurface(dialogContext, 0.12),
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: _dialogShadowColor(dialogContext),
                            blurRadius: 34,
                            offset: const Offset(0, 18),
                          ),
                        ],
                      ),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            children: [
                              Expanded(
                                child: Text(
                                  '${slot.label} DLLs',
                                  style: Theme.of(dialogContext)
                                      .textTheme
                                      .headlineSmall
                                      ?.copyWith(fontWeight: FontWeight.w800),
                                ),
                              ),
                              IconButton(
                                tooltip: 'Close',
                                onPressed: () =>
                                    Navigator.of(dialogContext).pop(),
                                icon: const Icon(Icons.close_rounded),
                              ),
                            ],
                          ),
                          const SizedBox(height: 10),
                          Text(
                            candidates.isEmpty
                                ? 'You currently have no DLLs downloaded from the Mod library. Install a DLL from there to see it appear here.'
                                : 'Choose an installed DLL mod to use for the ${slot.label}.',
                            style: TextStyle(
                              color: onSurface.withValues(alpha: 0.74),
                              fontWeight: FontWeight.w600,
                              height: 1.35,
                            ),
                          ),
                          if (candidates.isNotEmpty) ...[
                            const SizedBox(height: 14),
                            searchInput,
                            const SizedBox(height: 10),
                            ConstrainedBox(
                              constraints: const BoxConstraints(maxHeight: 360),
                              child: ScrollConfiguration(
                                behavior: ScrollConfiguration.of(
                                  dialogContext,
                                ).copyWith(scrollbars: false),
                                child: ListView(
                                  shrinkWrap: true,
                                  primary: false,
                                  children: [
                                    if (visibleCandidates.isEmpty)
                                      Padding(
                                        padding: const EdgeInsets.only(
                                          bottom: 12,
                                        ),
                                        child: Text(
                                          'No DLLs match your search.',
                                          style: TextStyle(
                                            color: onSurface.withValues(
                                              alpha: 0.56,
                                            ),
                                            fontWeight: FontWeight.w600,
                                          ),
                                        ),
                                      )
                                    else
                                      for (final candidate
                                          in visibleCandidates) ...[
                                        _installedDllChoiceTile(
                                          context: dialogContext,
                                          title: candidate.mod.name,
                                          subtitle: candidate.dllPath,
                                          selected:
                                              candidate.dllPath.toLowerCase() ==
                                              currentPath,
                                          onTap: () => Navigator.of(
                                            dialogContext,
                                          ).pop(candidate.dllPath),
                                          onRemove: () => unawaited(
                                            removeCandidate(candidate),
                                          ),
                                        ),
                                        const SizedBox(height: 8),
                                      ],
                                  ],
                                ),
                              ),
                            ),
                          ],
                          const SizedBox(height: 14),
                          Row(
                            children: [
                              _dialogCancelButton(
                                dialogContext,
                                onPressed: () =>
                                    Navigator.of(dialogContext).pop(),
                              ),
                              const Spacer(),
                            ],
                          ),
                        ],
                      ),
                    );
                  },
                ),
              ),
            ),
          ),
        );
      },
      transitionBuilder: _dialogPopupTransition,
    );
    if (selected != null && selected.trim().isNotEmpty) {
      controller.text = selected;
      onChanged(selected);
      _toast('Set ${slot.label} to ${_basename(selected)}');
    }
  }

