  Widget _glass({required Widget child, double radius = 28}) {
    final panelProgress = CurvedAnimation(
      parent: _shellEntranceController,
      curve: const Interval(0.2, 1.0, curve: Curves.easeOutCubic),
    );
    return AnimatedBuilder(
      animation: _shellEntranceController,
      builder: (context, panelChild) {
        final t = panelProgress.value.clamp(0.0, 1.0);
        return Opacity(
          opacity: t,
          child: Transform.translate(
            offset: Offset(0, (1 - t) * 18),
            child: Transform.scale(scale: 0.97 + (0.03 * t), child: panelChild),
          ),
        );
      },
      child: ClipRRect(
        borderRadius: BorderRadius.circular(radius),
        child: ValueListenableBuilder<bool>(
          valueListenable: _windowResizeBlurPausedNotifier,
          child: child,
          builder: (context, blurPaused, panelChild) {
            return TweenAnimationBuilder<double>(
              tween: Tween<double>(end: blurPaused ? 0.0 : 16.0),
              duration: blurPaused
                  ? Duration.zero
                  : _windowResizeBlurFadeInDuration,
              curve: Curves.easeOutCubic,
              builder: (context, blurSigma, panelChild) {
                final panel = Container(
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(radius),
                    color: _glassSurfaceColor(context),
                    border: Border.all(color: _onSurface(context, 0.08)),
                  ),
                  child: panelChild,
                );
                if (blurSigma <= 0.01) return panel;
                return BackdropFilter(
                  filter: ImageFilter.blur(
                    sigmaX: blurSigma,
                    sigmaY: blurSigma,
                  ),
                  child: panel,
                );
              },
              child: panelChild,
            );
          },
        ),
      ),
    );
  }

