class _ToastOverlayHost extends StatefulWidget {
  const _ToastOverlayHost({super.key, required this.onEmpty});

  final VoidCallback onEmpty;

  @override
  State<_ToastOverlayHost> createState() => _ToastOverlayHostState();
}

class _ToastOverlayHostState extends State<_ToastOverlayHost> {
  static const _toastDuration = Duration(seconds: 3);
  final GlobalKey<_AnimatedToastCardState> _cardKey =
      GlobalKey<_AnimatedToastCardState>();
  Timer? _timer;
  String _message = '';
  bool _progressMode = false;
  double? _progress;
  bool _progressIndeterminate = false;
  VoidCallback? _onCancel;

  void show(String message) {
    if (!mounted) return;
    final trimmed = message.trim();
    if (trimmed.isEmpty) return;

    _timer?.cancel();
    _message = trimmed;
    _progressMode = false;
    _progress = null;
    _progressIndeterminate = false;
    _onCancel = null;

    if (mounted) {
      setState(() {});
    }

    WidgetsBinding.instance.addPostFrameCallback((_) {
      _cardKey.currentState?.show(_message);
    });

    _timer = Timer(_toastDuration, () {
      if (!mounted) return;
      _cardKey.currentState?.dismiss();
    });
  }

  void showProgress(
    String message, {
    required double? progress,
    required bool indeterminate,
    VoidCallback? onCancel,
  }) {
    if (!mounted) return;
    final trimmed = message.trim();
    if (trimmed.isEmpty) return;

    _timer?.cancel();
    _message = trimmed;
    _progressMode = true;
    _progress = progress;
    _progressIndeterminate = indeterminate;
    _onCancel = onCancel;

    setState(() {});

    WidgetsBinding.instance.addPostFrameCallback((_) {
      _cardKey.currentState?.showProgress(
        _message,
        progress: _progress,
        indeterminate: _progressIndeterminate,
        onCancel: _onCancel,
      );
    });
  }

  void dismissProgressSoon() {
    if (!mounted) return;
    if (!_progressMode) return;
    _timer?.cancel();
    if (_onCancel != null) setState(() => _onCancel = null);
    _timer = Timer(const Duration(milliseconds: 550), () {
      if (!mounted) return;
      _cardKey.currentState?.dismiss();
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // Toasts are normally click-through; only a progress toast offering a Cancel
    // action needs to receive taps.
    return IgnorePointer(
      ignoring: _onCancel == null,
      child: _AnimatedToastCard(
        key: _cardKey,
        initialMessage: _message,
        onDismissed: widget.onEmpty,
      ),
    );
  }
}

class _AnimatedToastCard extends StatefulWidget {
  const _AnimatedToastCard({
    super.key,
    required this.initialMessage,
    required this.onDismissed,
  });

  final String initialMessage;
  final VoidCallback onDismissed;

  @override
  State<_AnimatedToastCard> createState() => _AnimatedToastCardState();
}

class _AnimatedToastCardState extends State<_AnimatedToastCard>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  late final Animation<double> _fade;
  late final Animation<Offset> _slide;
  bool _dismissing = false;
  String _message = '';
  bool _showProgressBar = false;
  double? _progress;
  bool _progressIndeterminate = false;
  VoidCallback? _onCancel;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 220),
      reverseDuration: const Duration(milliseconds: 180),
    );
    final curve = CurvedAnimation(parent: _controller, curve: Curves.easeOut);
    final reverseCurve = CurvedAnimation(
      parent: _controller,
      curve: Curves.easeOut,
      reverseCurve: Curves.easeIn,
    );
    _fade = Tween<double>(begin: 0, end: 1).animate(reverseCurve);
    _slide = Tween<Offset>(
      begin: const Offset(0, 0.18),
      end: Offset.zero,
    ).animate(curve);
    _message = widget.initialMessage;
    if (_message.trim().isNotEmpty) {
      _controller.forward();
    }
  }

  void show(String message) {
    if (!mounted) return;
    final trimmed = message.trim();
    if (trimmed.isEmpty) return;

    setState(() {
      _message = trimmed;
      _showProgressBar = false;
      _progress = null;
      _progressIndeterminate = false;
      _onCancel = null;
    });

    final wasHidden = _controller.value <= 0.001;
    _dismissing = false;

    // If we're mid-dismiss and a new toast arrives, keep it visible without
    // re-running an entrance animation.
    _controller.stop();
    if (wasHidden) {
      _controller
        ..value = 0
        ..forward();
    } else {
      _controller.value = 1;
    }
  }

  void showProgress(
    String message, {
    required double? progress,
    required bool indeterminate,
    VoidCallback? onCancel,
  }) {
    if (!mounted) return;
    final trimmed = message.trim();
    if (trimmed.isEmpty) return;

    setState(() {
      _message = trimmed;
      _showProgressBar = true;
      _progress = progress;
      _progressIndeterminate = indeterminate;
      _onCancel = onCancel;
    });

    final wasHidden = _controller.value <= 0.001;
    _dismissing = false;

    _controller.stop();
    if (wasHidden) {
      _controller
        ..value = 0
        ..forward();
    } else {
      _controller.value = 1;
    }
  }

  Future<void> dismiss() async {
    if (!mounted || _dismissing) return;
    _dismissing = true;
    try {
      // Reverse uses the same slide tween, so it slides back down.
      await _controller.reverse();
    } finally {
      if (mounted) widget.onDismissed();
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final onSurface = _onSurface(context, 0.92);
    final barColor = Theme.of(context).colorScheme.secondary;
    final barTrack = _onSurface(context, 0.10);
    const radius = 18.0;
    return FadeTransition(
      opacity: _fade,
      child: SlideTransition(
        position: _slide,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 420),
          child: Container(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(radius),
              boxShadow: [
                BoxShadow(
                  color: _dialogShadowColor(context),
                  blurRadius: 34,
                  offset: const Offset(0, 18),
                ),
              ],
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(radius),
              child: DecoratedBox(
                decoration: BoxDecoration(
                  color: _dialogSurfaceColor(context),
                  borderRadius: BorderRadius.circular(radius),
                  border: Border.all(color: _onSurface(context, 0.12)),
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Padding(
                      padding: EdgeInsets.fromLTRB(
                        16,
                        12,
                        _onCancel == null ? 16 : 8,
                        12,
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Expanded(
                            child: Text(
                              _message,
                              maxLines: 3,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: onSurface,
                                fontWeight: FontWeight.w600,
                                height: 1.2,
                              ),
                            ),
                          ),
                          if (_onCancel != null) ...[
                            const SizedBox(width: 8),
                            Tooltip(
                              message: 'Cancel',
                              child: InkWell(
                                onTap: () {
                                  final cancel = _onCancel;
                                  setState(() => _onCancel = null);
                                  cancel?.call();
                                },
                                borderRadius: BorderRadius.circular(8),
                                child: Padding(
                                  padding: const EdgeInsets.all(4),
                                  child: Icon(
                                    Icons.close_rounded,
                                    size: 18,
                                    color: _onSurface(context, 0.7),
                                  ),
                                ),
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                    if (_showProgressBar)
                      SizedBox(
                        height: 3,
                        child: LinearProgressIndicator(
                          value: _progressIndeterminate ? null : _progress,
                          backgroundColor: barTrack,
                          valueColor: AlwaysStoppedAnimation<Color>(barColor),
                          minHeight: 3,
                        ),
                      ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

