class _AtlasModEntry {
  const _AtlasModEntry({
    required this.id,
    required this.type,
    required this.folderName,
    required this.folderPath,
    required this.name,
    required this.author,
    required this.cardDescription,
    required this.description,
    required this.version,
    required this.tags,
    required this.cardImage,
    required this.images,
    required this.media,
    required this.sourceUrl,
    required this.files,
    this.dependencies = const <String>[],
    this.dataSlot = '',
    this.lastUpdatedEpochMs = 0,
  });

  final String id;
  final _AtlasModType type;
  final String folderName;
  final String folderPath;
  final String name;
  final String author;
  final String cardDescription;
  final String description;
  final String version;
  // Free-form labels defined entirely by the mod's metadata.json ("tags").
  final List<String> tags;
  final String cardImage;
  final List<String> images;
  final List<_AtlasModMedia> media;
  final String sourceUrl;
  final List<_AtlasModFile> files;
  // Other mods this one needs installed first. Each entry references a catalog
  // mod by folder path ("EXEs/27.11"), id, or display name. Resolved against the
  // loaded library; the user is prompted to install any missing ones first.
  final List<String> dependencies;
  // For DLL mods: which Data Management patcher slot this DLL is meant for
  // (free-form metadata value, resolved via [_DataDllSlot.resolve]). Empty when
  // the mod doesn't target a slot.
  final String dataSlot;
  final int lastUpdatedEpochMs;

  _AtlasModEntry copyWith({int? lastUpdatedEpochMs}) {
    return _AtlasModEntry(
      id: id,
      type: type,
      folderName: folderName,
      folderPath: folderPath,
      name: name,
      author: author,
      cardDescription: cardDescription,
      description: description,
      version: version,
      tags: tags,
      cardImage: cardImage,
      images: images,
      media: media,
      sourceUrl: sourceUrl,
      files: files,
      dependencies: dependencies,
      dataSlot: dataSlot,
      lastUpdatedEpochMs: lastUpdatedEpochMs ?? this.lastUpdatedEpochMs,
    );
  }

  String get primaryImage {
    if (cardImage.trim().isNotEmpty) return cardImage;
    if (images.isNotEmpty) return images.first;
    for (final item in media) {
      if (item.type == _AtlasModMediaType.image && item.url.trim().isNotEmpty) {
        return item.url;
      }
    }
    return '';
  }

  List<_AtlasModMedia> get detailMedia {
    final result = <_AtlasModMedia>[];
    final primary = primaryImage.trim();
    if (primary.isNotEmpty) {
      result.add(
        _AtlasModMedia(
          url: primary,
          type: _AtlasModMediaType.image,
          label: _atlasPathBasename(primary),
        ),
      );
    }
    for (final item in media) {
      if (item.url.trim().isEmpty) continue;
      if (primary.isNotEmpty &&
          item.url.trim().toLowerCase() == primary.toLowerCase()) {
        continue;
      }
      result.add(item);
    }
    if (result.isEmpty) {
      result.add(
        const _AtlasModMedia(
          url: '',
          type: _AtlasModMediaType.image,
          label: 'Missing image',
        ),
      );
    }
    return result;
  }

  factory _AtlasModEntry.fromJson(Map<String, dynamic> json) {
    _AtlasModType parseType(dynamic value) {
      final text = value.toString().trim().toLowerCase();
      if (text == 'dll' || text == 'dlls') return _AtlasModType.dll;
      if (text == 'exe' || text == 'exes') return _AtlasModType.exe;
      return _AtlasModType.pak;
    }

    List<String> stringList(dynamic value) {
      if (value is! List) return const <String>[];
      return value
          .map((item) => item.toString().trim())
          .where((item) => item.isNotEmpty)
          .toList();
    }

    int asInt(dynamic value, int fallback) {
      if (value is int) return value;
      if (value is num) return value.toInt();
      if (value is String) return int.tryParse(value) ?? fallback;
      return fallback;
    }

    final filesRaw = json['files'];
    final files = filesRaw is List
        ? filesRaw
              .whereType<Map>()
              .map(
                (item) => _AtlasModFile.fromJson(item.cast<String, dynamic>()),
              )
              .where((file) => file.name.trim().isNotEmpty)
              .toList()
        : <_AtlasModFile>[];
    final mediaRaw = json['media'];
    final images = stringList(json['images']);
    final media = mediaRaw is List
        ? mediaRaw
              .whereType<Map>()
              .map(
                (item) => _AtlasModMedia.fromJson(item.cast<String, dynamic>()),
              )
              .where((item) => item.url.trim().isNotEmpty)
              .toList()
        : images
              .map(
                (image) => _AtlasModMedia(
                  url: image,
                  type: _AtlasModMediaType.image,
                  label: _atlasPathBasename(image),
                ),
              )
              .toList();

    return _AtlasModEntry(
      id: (json['id'] ?? '').toString(),
      type: parseType(json['type']),
      folderName: (json['folderName'] ?? '').toString(),
      folderPath: (json['folderPath'] ?? '').toString(),
      name: (json['name'] ?? '').toString(),
      author: (json['author'] ?? '').toString(),
      cardDescription: (json['cardDescription'] ?? '').toString(),
      description: (json['description'] ?? '').toString(),
      version: (json['version'] ?? '').toString(),
      tags: stringList(json['tags']),
      cardImage: (json['cardImage'] ?? '').toString(),
      images: images,
      media: media,
      sourceUrl: (json['sourceUrl'] ?? '').toString(),
      files: files,
      dependencies: stringList(
        json['dependencies'] ?? json['requires'] ?? json['dependsOn'],
      ),
      dataSlot:
          (json['dataSlot'] ??
                  json['dataManagementSlot'] ??
                  json['patcherSlot'] ??
                  json['dllRole'] ??
                  json['slot'] ??
                  '')
              .toString()
              .trim(),
      lastUpdatedEpochMs: asInt(
        json['lastUpdatedEpochMs'] ??
            json['lastUpdatedAtEpochMs'] ??
            json['updatedAtEpochMs'],
        0,
      ),
    );
  }

  Map<String, dynamic> toJson() {
    return <String, dynamic>{
      'id': id,
      'type': type.name,
      'folderName': folderName,
      'folderPath': folderPath,
      'name': name,
      'author': author,
      'cardDescription': cardDescription,
      'description': description,
      'version': version,
      'tags': tags,
      'cardImage': cardImage,
      'images': images,
      'media': media.map((item) => item.toJson()).toList(),
      'sourceUrl': sourceUrl,
      'files': files.map((file) => file.toJson()).toList(),
      'dependencies': dependencies,
      'dataSlot': dataSlot,
      'lastUpdatedEpochMs': lastUpdatedEpochMs,
    };
  }
}

class _InstalledAtlasMod {
  const _InstalledAtlasMod({
    required this.id,
    required this.type,
    required this.name,
    required this.version,
    required this.targetVersionId,
    this.targetVersionIds = const <String>[],
    required this.installedFilePaths,
    required this.installedAtEpochMs,
    this.sourceLastUpdatedEpochMs = 0,
    this.filesFingerprint = '',
    this.dataSlot = '',
  });

  final String id;
  final _AtlasModType type;
  final String name;
  final String version;
  // For DLL mods: the Data Management slot this DLL targets (copied from the
  // catalog entry at install time so the slot picker works without the catalog
  // loaded). Empty for non-DLL mods or mods that don't declare a slot.
  final String dataSlot;
  // Kept for backwards compatibility (first install target).
  final String targetVersionId;
  // Every build this mod was installed to. A pak mod can target multiple
  // compatible builds at once.
  final List<String> targetVersionIds;
  final List<String> installedFilePaths;
  final int installedAtEpochMs;
  // The catalog mod's "last updated" commit time at the moment this copy was
  // installed/updated. Fallback update signal when file SHAs are unavailable.
  final int sourceLastUpdatedEpochMs;
  // Content fingerprint of the installable files (sorted name:sha). The library
  // shows an update when the catalog's fingerprint differs from this, so only
  // changes to the actual game files count (not metadata/screenshots).
  final String filesFingerprint;

  _InstalledAtlasMod copyWith({
    String? name,
    String? version,
    String? targetVersionId,
    List<String>? targetVersionIds,
    List<String>? installedFilePaths,
    int? installedAtEpochMs,
    int? sourceLastUpdatedEpochMs,
    String? filesFingerprint,
    String? dataSlot,
  }) {
    return _InstalledAtlasMod(
      id: id,
      type: type,
      name: name ?? this.name,
      version: version ?? this.version,
      targetVersionId: targetVersionId ?? this.targetVersionId,
      targetVersionIds: targetVersionIds ?? this.targetVersionIds,
      installedFilePaths: installedFilePaths ?? this.installedFilePaths,
      installedAtEpochMs: installedAtEpochMs ?? this.installedAtEpochMs,
      sourceLastUpdatedEpochMs:
          sourceLastUpdatedEpochMs ?? this.sourceLastUpdatedEpochMs,
      filesFingerprint: filesFingerprint ?? this.filesFingerprint,
      dataSlot: dataSlot ?? this.dataSlot,
    );
  }

  factory _InstalledAtlasMod.fromJson(Map<String, dynamic> json) {
    int asInt(dynamic value, int fallback) {
      if (value is int) return value;
      if (value is num) return value.toInt();
      if (value is String) return int.tryParse(value) ?? fallback;
      return fallback;
    }

    _AtlasModType parseType(dynamic value) {
      final text = value.toString().trim().toLowerCase();
      if (text == 'dll' || text == 'dlls') return _AtlasModType.dll;
      if (text == 'exe' || text == 'exes') return _AtlasModType.exe;
      return _AtlasModType.pak;
    }

    List<String> stringList(dynamic value) {
      if (value is! List) return <String>[];
      return value
          .map((item) => item.toString().trim())
          .where((item) => item.isNotEmpty)
          .toList();
    }

    final pathsRaw = json['installedFilePaths'] ?? json['files'];
    final paths = stringList(pathsRaw);

    final singleTarget = (json['targetVersionId'] ?? '').toString();
    var targetVersionIds = stringList(json['targetVersionIds']);
    if (targetVersionIds.isEmpty && singleTarget.trim().isNotEmpty) {
      targetVersionIds = <String>[singleTarget];
    }

    return _InstalledAtlasMod(
      id: (json['id'] ?? '').toString(),
      type: parseType(json['type']),
      name: (json['name'] ?? '').toString(),
      version: (json['version'] ?? '').toString(),
      targetVersionId: singleTarget,
      targetVersionIds: targetVersionIds,
      installedFilePaths: paths,
      installedAtEpochMs: asInt(json['installedAtEpochMs'], 0),
      sourceLastUpdatedEpochMs: asInt(json['sourceLastUpdatedEpochMs'], 0),
      filesFingerprint: (json['filesFingerprint'] ?? '').toString(),
      dataSlot: (json['dataSlot'] ?? '').toString().trim(),
    );
  }

  Map<String, dynamic> toJson() {
    return <String, dynamic>{
      'id': id,
      'type': type.name,
      'name': name,
      'version': version,
      'targetVersionId': targetVersionId,
      'targetVersionIds': targetVersionIds,
      'installedFilePaths': installedFilePaths,
      'installedAtEpochMs': installedAtEpochMs,
      'sourceLastUpdatedEpochMs': sourceLastUpdatedEpochMs,
      'filesFingerprint': filesFingerprint,
      'dataSlot': dataSlot,
    };
  }
}

